import 'package:flutter/material.dart';

import '../theme/app_theme.dart';

class LessonExample {
  const LessonExample(this.turkish, this.arabic);
  final String turkish;
  final String arabic;
}

class LessonContent {
  const LessonContent({
    required this.goal,
    required this.explanation,
    required this.examples,
    required this.question,
    required this.options,
    required this.answer,
    required this.feedback,
  });

  final String goal;
  final String explanation;
  final List<LessonExample> examples;
  final String question;
  final List<String> options;
  final int answer;
  final String feedback;

  static LessonContent? find(String unitId, int lessonIndex) =>
      _lessons['$unitId-${lessonIndex + 1}'];

  static const Map<String, LessonContent> _lessons = {
    'a1-u1-1': LessonContent(goal: 'التعرّف إلى الحروف التركية وقراءة الأبجدية كاملة.', explanation: 'تتكوّن الأبجدية التركية الحديثة من 29 حرفاً. تُكتب من اليسار إلى اليمين، ولكل حرف صوت ثابت غالباً. انتبه إلى الحروف الخاصة: Ç ç، Ğ ğ، I ı، İ i، Ö ö، Ş ş، Ü ü.', examples: [LessonExample('A a – Araba', 'أ – سيارة'), LessonExample('Ç ç – Çay', 'تش – شاي'), LessonExample('Ş ş – Şeker', 'ش – سكر')], question: 'كم حرفاً في الأبجدية التركية؟', options: ['26', '28', '29', '30'], answer: 2, feedback: 'الأبجدية التركية تتكوّن من 29 حرفاً.'),
    'a1-u1-2': LessonContent(goal: 'تمييز الحروف المتحركة وتصنيفها إلى مجموعات.', explanation: 'الحروف المتحركة التركية هي: a, e, ı, i, o, ö, u, ü. وتنقسم إلى حروف خلفية (a, ı, o, u) وأمامية (e, i, ö, ü). هذا التصنيف مهم لفهم انسجام اللواحق.', examples: [LessonExample('a – kapı', 'a حرف خلفي في كلمة باب'), LessonExample('e – ev', 'e حرف أمامي في كلمة بيت'), LessonExample('ü – üzüm', 'ü حرف أمامي مستدير في كلمة عنب')], question: 'أي مجموعة تتكوّن من حروف متحركة خلفية؟', options: ['e, i, ö, ü', 'a, ı, o, u', 'a, e, i, o', 'ı, i, u, ü'], answer: 1, feedback: 'الحروف الخلفية الأربعة هي a, ı, o, u.'),
    'a1-u1-3': LessonContent(goal: 'فهم فكرة الانسجام الصوتي الأساسي في اللواحق.', explanation: 'غالباً ما تتغير حركة اللاحقة لتنسجم مع آخر حركة في الكلمة. في الانسجام الثنائي نستخدم a بعد الحركات الخلفية وe بعد الأمامية، مثل -lar/-ler للجمع. توجد قواعد أخرى أكثر تفصيلاً ستتعلمها تدريجياً.', examples: [LessonExample('ev → evler', 'بيوت: آخر حركة أمامية، لذلك -ler'), LessonExample('araba → arabalar', 'سيارات: آخر حركة خلفية، لذلك -lar'), LessonExample('gül → güller', 'ورود: آخر حركة أمامية، لذلك -ler')], question: 'ما جمع كلمة ev؟', options: ['evlar', 'evler', 'evlerı', 'evlerlar'], answer: 1, feedback: 'ev تنتهي بحركة أمامية e، لذلك نضيف -ler.'),
    'a1-u1-4': LessonContent(goal: 'التعرّف إلى أصوات تركية قد لا توجد بالطريقة نفسها في العربية.', explanation: 'تحتاج بعض الحروف إلى تدريب خاص: c يُنطق مثل j في كلمة journal، وç مثل ch في chair، وş مثل sh في ship. أما ı فصوت مستقل غير منقوط، ويختلف عن i المنقوط.', examples: [LessonExample('cam', 'زجاج – يبدأ بصوت j'), LessonExample('çocuk', 'طفل – يبدأ بصوت ch'), LessonExample('şapka', 'قبعة – يبدأ بصوت sh')], question: 'أي حرف تركي يُنطق قريباً من sh الإنجليزية؟', options: ['c', 'ş', 'ç', 'j'], answer: 1, feedback: 'الحرف ş صوته قريب من sh في الإنجليزية.'),
    'a1-u1-5': LessonContent(goal: 'تقسيم الكلمات إلى مقاطع وقراءتها بوضوح.', explanation: 'في التركية تحتوي كل مقطعية عادةً على حركة واحدة، ويمكن استخدام عدد الحركات لتقدير عدد المقاطع. اقرأ ببطء، ولا تحذف الحركات، وحافظ على وضوح كل مقطع.', examples: [LessonExample('a-ra-ba', 'سيارة – ثلاثة مقاطع'), LessonExample('ki-tap', 'كتاب – مقطعان'), LessonExample('o-kul', 'مدرسة – مقطعان')], question: 'كم مقطعاً في كلمة araba؟', options: ['مقطع واحد', 'مقطعان', 'ثلاثة مقاطع', 'أربعة مقاطع'], answer: 2, feedback: 'a-ra-ba تتكوّن من ثلاثة مقاطع.'),
    'a1-u1-6': LessonContent(goal: 'تطبيق النطق على كلمات يومية قصيرة.', explanation: 'اقرأ الكلمة كاملة ثم قسّمها إلى مقاطع، وانتبه إلى الحروف المنقوطة وغير المنقوطة. لا تعتمد على شكل الحرف وحده؛ استمع إلى نطقه وكرره.', examples: [LessonExample('merhaba', 'مرحباً'), LessonExample('teşekkür', 'شكراً'), LessonExample('lütfen', 'من فضلك')], question: 'أي كلمة تعني «من فضلك»؟', options: ['Merhaba', 'Lütfen', 'Teşekkür', 'Günaydın'], answer: 1, feedback: 'Lütfen تعني من فضلك.'),
    'a1-u1-7': LessonContent(goal: 'تمييز الكلمات المتقاربة في الصوت والكتابة.', explanation: 'قد يؤدي اختلاف نقطة أو علامة صغيرة إلى اختلاف الحرف والكلمة. قارن بين I وİ، وبين o وö، وبين u وü. كرر الكلمات بصوت واضح ولا تستبدل الحروف الخاصة بحروف عربية تقريبية.', examples: [LessonExample('Işık', 'ضوء'), LessonExample('İsim', 'اسم'), LessonExample('Göl', 'بحيرة')], question: 'أي حرف هو i المنقوط الكبير؟', options: ['I', 'İ', 'ı', 'j'], answer: 1, feedback: 'الحرف İ كبير ومنقوط، ويختلف عن I غير المنقوط.'),
    'a1-u1-8': LessonContent(goal: 'قراءة عبارات قصيرة تجمع الحروف التي تعلمتها.', explanation: 'ابدأ بقراءة الكلمات منفردة، ثم اقرأ العبارة كاملة. لاحظ أن التركية تستخدم علامات مثل ş وç وğ، وأن الحرف ğ غالباً يطيل الحركة السابقة أو يسهّل الانتقال بين الحركات.', examples: [LessonExample('Güzel bir gün.', 'إنه يوم جميل.'), LessonExample('Çay çok sıcak.', 'الشاي ساخن جداً.'), LessonExample('Üç küçük kuş.', 'ثلاثة طيور صغيرة.')], question: 'ما معنى Güzel؟', options: ['كبير', 'جميل', 'بارد', 'سريع'], answer: 1, feedback: 'Güzel تعني جميل أو جميلة.'),
    'a1-u1-9': LessonContent(goal: 'مراجعة الحروف والأصوات والقراءة الأساسية.', explanation: 'راجع الحروف المتحركة الثمانية، والحروف الخاصة، والتمييز بين c/ç وs/ş وı/i. استخدم القراءة المتدرجة: حرف، ثم مقطع، ثم كلمة، ثم جملة قصيرة.', examples: [LessonExample('çanta', 'حقيبة'), LessonExample('öğrenci', 'طالب'), LessonExample('üzüm', 'عنب')], question: 'أي كلمة تبدأ بالحرف ş؟', options: ['Çanta', 'Şeker', 'Öğrenci', 'Üzüm'], answer: 1, feedback: 'Şeker تبدأ بالحرف ş.'),
    'a1-u2-1': LessonContent(goal: 'استخدام التحيات المناسبة في أوقات ومواقف مختلفة.', explanation: 'تختلف التحية التركية بحسب الوقت والرسمية. Merhaba تحية عامة، Günaydın للصباح، İyi akşamlar للمساء. عند المغادرة نقول Hoşça kal أو Güle güle بحسب المتحدث والسياق.', examples: [LessonExample('Merhaba!', 'مرحباً!'), LessonExample('Günaydın!', 'صباح الخير!'), LessonExample('İyi akşamlar.', 'مساء الخير.')], question: 'ما التحية المناسبة في الصباح؟', options: ['İyi geceler', 'Günaydın', 'Hoşça kal', 'Güle güle'], answer: 1, feedback: 'Günaydın تعني صباح الخير.'),
    'a1-u2-2': LessonContent(goal: 'تقديم نفسك بجمل قصيرة وبسيطة.', explanation: 'يمكنك استخدام Benim adım ... بمعنى اسمي ...، أو Ben ... بمعنى أنا ... . ولذكر المهنة أو الصفة نستخدم جملة اسمية بسيطة مثل Ben öğrenciyim (أنا طالب/طالبة).', examples: [LessonExample('Benim adım Ali.', 'اسمي علي.'), LessonExample('Ben öğrenciyim.', 'أنا طالب/طالبة.'), LessonExample('Memnun oldum.', 'سعيد/سعيدة بلقائك.')], question: 'كيف تقول «اسمي سارة»؟', options: ['Benim adım Sara.', 'Senin adın Sara.', 'Nerelisin Sara?', 'Hoşça kal Sara.'], answer: 0, feedback: 'Benim adım Sara تعني اسمي سارة.'),
    'a1-u2-3': LessonContent(goal: 'السؤال عن الاسم والبلد والأصل والإجابة عنها.', explanation: 'للسؤال عن الاسم نقول Adın ne؟ وللسؤال عن البلد أو الأصل Nerelisin؟. يمكن الإجابة بـ Ben Suriyeliyim (أنا سوري/سورية) أو Suriyeliyim.', examples: [LessonExample('Adın ne?', 'ما اسمك؟'), LessonExample('Nerelisin?', 'من أين أنت؟'), LessonExample('Ben Suriyeliyim.', 'أنا سوري/سورية.')], question: 'أي سؤال يعني «من أين أنت؟»', options: ['Kaç yaşındasın?', 'Nerelisin?', 'Adın ne?', 'Nasılsın?'], answer: 1, feedback: 'Nerelisin تعني من أين أنت؟'),
    'a1-u2-4': LessonContent(goal: 'استخدام الضمائر الشخصية الأساسية.', explanation: 'الضمائر هي Ben أنا، Sen أنت، O هو/هي، Biz نحن، Siz أنتم أو حضرتك، Onlar هم. كثيراً ما يُحذف الضمير في التركية لأن نهاية الفعل أو الجملة قد تدل على الشخص.', examples: [LessonExample('Ben', 'أنا'), LessonExample('Biz', 'نحن'), LessonExample('Onlar', 'هم / هن')], question: 'ما الضمير التركي الذي يعني «نحن»؟', options: ['Ben', 'Sen', 'Biz', 'Siz'], answer: 2, feedback: 'Biz تعني نحن.'),
    'a1-u2-5': LessonContent(goal: 'تكوين جمل اسمية بسيطة للتعريف بالهوية والصفة.', explanation: 'في التركية تُضاف نهايات إلى الاسم أو الصفة لتدل على الشخص. مثال: Ben öğrenciyim (أنا طالب)، Sen öğrencisin (أنت طالب)، O öğrenci (هو/هي طالب). تتغير النهاية بحسب الضمير والانسجام الصوتي.', examples: [LessonExample('Ben öğretmenim.', 'أنا معلّم/معلّمة.'), LessonExample('Sen yorgunsun.', 'أنت متعب/متعبة.'), LessonExample('O doktor.', 'هو/هي طبيب.')], question: 'أكمل: Ben öğrenci___ .', options: ['-sin', '-yim', '-siniz', 'لا شيء دائماً'], answer: 1, feedback: 'مع Ben نستخدم هنا -yim: Ben öğrenciyim.'),
    'a1-u2-6': LessonContent(goal: 'طرح سؤال بسيط وصياغة النفي في الجمل الاسمية.', explanation: 'أداة السؤال mı/mi/mu/mü تُكتب منفصلة وتتغير حركتها حسب الانسجام الصوتي. للنفي في الجمل الاسمية نستخدم değil، مثل Ben doktor değilim (أنا لست طبيباً).', examples: [LessonExample('Öğrenci misin?', 'هل أنت طالب؟'), LessonExample('Mutlu musun?', 'هل أنت سعيد؟'), LessonExample('Ben öğretmen değilim.', 'أنا لست معلماً.')], question: 'أي كلمة تُستخدم للنفي في الجملة الاسمية؟', options: ['var', 'değil', 'mi', 've'], answer: 1, feedback: 'değil أداة النفي في الجمل الاسمية.'),
    'a1-u2-7': LessonContent(goal: 'قراءة الأرقام والسؤال عن العمر والإجابة عنه.', explanation: 'الأرقام الأساسية: bir واحد، iki اثنان، üç ثلاثة، dört أربعة، beş خمسة، on عشرة، yirmi عشرون. للسؤال عن العمر نقول Kaç yaşındasın؟ والإجابة Ben ... yaşındayım.', examples: [LessonExample('Kaç yaşındasın?', 'كم عمرك؟'), LessonExample('On sekiz yaşındayım.', 'عمري ثمانية عشر عاماً.'), LessonExample('Yirmi bir', 'واحد وعشرون')], question: 'ما معنى üç؟', options: ['اثنان', 'ثلاثة', 'أربعة', 'خمسة'], answer: 1, feedback: 'üç تعني ثلاثة.'),
    'a1-u2-8': LessonContent(goal: 'إجراء حوار تعارف قصير من التحية حتى الوداع.', explanation: 'اجمع ما تعلمته في حوار مرتب: التحية، السؤال عن الحال، الاسم، البلد أو المهنة، ثم عبارة المجاملة والوداع. استخدم Sen عند الحديث غير الرسمي وSiz في السياق الرسمي أو الاحترام.', examples: [LessonExample('A: Merhaba, nasılsın?', 'أ: مرحباً، كيف حالك؟'), LessonExample('B: İyiyim, teşekkürler. Ya sen?', 'ب: أنا بخير، شكراً. وأنت؟'), LessonExample('A: Ben de iyiyim.', 'أ: أنا أيضاً بخير.')], question: 'ما الرد الشائع على Nasılsın؟', options: ['İyiyim, teşekkürler.', 'Benim adım.', 'Güle güle.', 'Nerelisin?'], answer: 0, feedback: 'İyiyim, teşekkürler تعني أنا بخير، شكراً.'),
    'a1-u2-9': LessonContent(goal: 'مراجعة التحيات والتعارف والضمائر والأرقام.', explanation: 'تأكد من قدرتك على بدء التعارف، ذكر اسمك وبلدك، السؤال عن شخص آخر، استخدام الضمائر، وتكوين سؤال بسيط وجواب منفي. حاول أن تنشئ حواراً من أربع إلى ست جمل.', examples: [LessonExample('Benim adım Lina.', 'اسمي لينا.'), LessonExample('Nerelisin? – Mısırlıyım.', 'من أين أنت؟ – أنا مصري/مصرية.'), LessonExample('Kaç yaşındasın? – Yirmi yaşındayım.', 'كم عمرك؟ – عمري عشرون عاماً.')], question: 'اختر العبارة التي تعني «أنا أيضاً بخير».', options: ['Ben de iyiyim.', 'Ben öğrenciyim.', 'İyi geceler.', 'Adın ne?'], answer: 0, feedback: 'Ben de iyiyim تعني أنا أيضاً بخير.'),
    'a1-u3-1': LessonContent(goal: 'تسمية الأشياء والأدوات الشائعة في المنزل والدراسة.', explanation: 'ابدأ بحفظ أسماء الأشياء مع أداة التعريف العربية ومع مثال بسيط. الأسماء التركية لا تتغير بحسب المذكر والمؤنث كما في العربية.', examples: [LessonExample('kitap', 'كتاب'), LessonExample('kalem', 'قلم'), LessonExample('masa', 'طاولة'), LessonExample('kapı', 'باب'), LessonExample('telefon', 'هاتف')], question: 'ما معنى kalem؟', options: ['كتاب', 'قلم', 'باب', 'كرسي'], answer: 1, feedback: 'kalem تعني قلم.'),
    'a1-u3-2': LessonContent(goal: 'وصف الأشياء باستخدام الألوان والصفات الأساسية.', explanation: 'تأتي الصفة عادة قبل الاسم في التركية. من الألوان: kırmızı أحمر، mavi أزرق، beyaz أبيض، siyah أسود. ومن الصفات: büyük كبير، küçük صغير، güzel جميل، yeni جديد.', examples: [LessonExample('kırmızı araba', 'سيارة حمراء'), LessonExample('büyük ev', 'بيت كبير'), LessonExample('mavi kalem', 'قلم أزرق')], question: 'ما معنى beyaz؟', options: ['أسود', 'أحمر', 'أبيض', 'أزرق'], answer: 2, feedback: 'beyaz تعني أبيض.'),
    'a1-u3-3': LessonContent(goal: 'تكوين جمع الأسماء باستخدام -lar و-ler.', explanation: 'نضيف -lar أو -ler إلى الاسم بحسب آخر حركة: بعد a, ı, o, u نستخدم -lar، وبعد e, i, ö, ü نستخدم -ler. لا نضيف لاحقة الجمع عادةً إذا كان العدد مذكوراً.', examples: [LessonExample('kitap → kitaplar', 'كتب'), LessonExample('ev → evler', 'بيوت'), LessonExample('kalem → kalemler', 'أقلام')], question: 'ما جمع كلمة araba؟', options: ['arabaler', 'arabalar', 'arabalarlar', 'arabas'], answer: 1, feedback: 'آخر حركة في araba هي a، لذلك نضيف -lar.'),
    'a1-u3-4': LessonContent(goal: 'استخدام أسماء الإشارة هذا وذاك وهؤلاء.', explanation: 'Bu تعني هذا/هذه للقريب، Şu للإشارة إلى شيء محدد عادةً، وO تعني ذلك/تلك للبعيد. للجمع نستخدم Bunlar (هؤلاء/هذه الأشياء) وOnlar (أولئك/هم).', examples: [LessonExample('Bu bir kitap.', 'هذا كتاب.'), LessonExample('Şu kalem.', 'ذلك القلم المشار إليه.'), LessonExample('Bunlar kitaplar.', 'هذه كتب.')], question: 'أي كلمة تعني «هذا/هذه» للقريب؟', options: ['O', 'Bu', 'Onlar', 'Nerede'], answer: 1, feedback: 'Bu تستخدم للإشارة إلى القريب.'),
    'a1-u3-5': LessonContent(goal: 'تركيب جمل لوصف الأشياء باللون والحجم والصفة.', explanation: 'ضع الصفة قبل الاسم، ثم استخدم Bu أو Şu لتكوين جملة. مثال: Bu büyük bir masa (هذه طاولة كبيرة). لاحظ أن bir تأتي غالباً قبل الاسم المفرد المعدود في هذا التركيب.', examples: [LessonExample('Bu kırmızı bir çanta.', 'هذه حقيبة حمراء.'), LessonExample('Şu küçük ev.', 'ذلك البيت الصغير.'), LessonExample('Bu yeni telefon.', 'هذا هاتف جديد.')], question: 'اختر الترتيب الصحيح لعبارة «سيارة زرقاء».', options: ['araba mavi', 'mavi araba', 'araba mavil', 'mavi bir'], answer: 1, feedback: 'الصفة تسبق الاسم: mavi araba.'),
    'a1-u3-6': LessonContent(goal: 'وصف الغرفة وتحديد مكان الأشياء.', explanation: 'تعلّم كلمات المكان: içinde داخل، üstünde فوق، altında تحت، yanında بجانب، önünde أمام، arkasında خلف. للسؤال عن المكان نقول Nerede؟ أي أين؟', examples: [LessonExample('Kitap masanın üstünde.', 'الكتاب فوق الطاولة.'), LessonExample('Çanta sandalyenin yanında.', 'الحقيبة بجانب الكرسي.'), LessonExample('Telefon çantanın içinde.', 'الهاتف داخل الحقيبة.')], question: 'ما معنى altında؟', options: ['فوق', 'تحت', 'بجانب', 'أمام'], answer: 1, feedback: 'altında تعني تحت.'),
    'a1-u3-7': LessonContent(goal: 'التعبير عن الملكية باستخدام الضمائر واللواحق.', explanation: 'يمكن أن نذكر ضمير الملكية مثل benim أو senin، ثم نضيف لاحقة الملكية إلى الاسم. تتغير اللاحقة بحسب آخر حركة، وقد يتغير آخر حرف في بعض الأسماء مثل kitap → kitabım.', examples: [LessonExample('Benim kitabım.', 'كتابي.'), LessonExample('Senin çantan.', 'حقيبتك.'), LessonExample('Bizim evimiz.', 'بيتنا.')], question: 'كيف نقول «كتابي»؟', options: ['kitabın', 'kitabım', 'kitabı', 'kitabımız'], answer: 1, feedback: 'لاحقة المتكلم المفرد هنا -ım: kitabım.'),
    'a1-u3-8': LessonContent(goal: 'السؤال عن الأشياء ومالكها ووصفها في حوار يومي.', explanation: 'للسؤال عن ماهية الشيء نقول Bu ne؟ (ما هذا؟)، وعن صاحبه Bu kimin؟ (لمن هذا؟)، وعن مكانه Nerede؟ (أين؟). وللسؤال عن السعر Ne kadar؟ (كم السعر؟).', examples: [LessonExample('Bu ne?', 'ما هذا؟'), LessonExample('Bu kimin çantası?', 'لمن هذه الحقيبة؟'), LessonExample('Ne kadar?', 'كم السعر؟'), LessonExample('Çanta nerede?', 'أين الحقيبة؟')], question: 'كيف تسأل «لمن هذا؟»', options: ['Bu ne?', 'Bu kimin?', 'Nerede?', 'Ne kadar?'], answer: 1, feedback: 'Bu kimin؟ تعني لمن هذا؟'),
    'a1-u3-9': LessonContent(goal: 'مراجعة مفردات الأشياء والألوان والجمع والإشارة والمكان والملكية.', explanation: 'استخدم ما تعلمته لوصف غرفة أو حقيبة أو مكتب. اذكر اسم الشيء ولونه وحجمه ومكانه وصاحبه. كوّن خمس جمل مترابطة ثم أجب عن أسئلة المراجعة.', examples: [LessonExample('Bu benim mavi çantam.', 'هذه حقيبتي الزرقاء.'), LessonExample('Kitap masanın üstünde.', 'الكتاب فوق الطاولة.'), LessonExample('Bunlar yeni kalemler.', 'هذه أقلام جديدة.')], question: 'أي جملة تعني «هذه حقيبتي الزرقاء»؟', options: ['Bu benim mavi çantam.', 'Bu senin kırmızı evin.', 'O benim kitabım.', 'Bunlar küçük masalar.'], answer: 0, feedback: 'Bu benim mavi çantam تعني هذه حقيبتي الزرقاء.'),

    'a1-u4-1': LessonContent(goal: 'تعلّم أسماء أفراد العائلة الأساسية.', explanation: 'تُستخدم كلمات القرابة كثيراً في التعارف والحديث اليومي. احفظ الكلمة مع ضمير الملكية لتستطيع قول عائلتي وأمي وأبي.', examples: [LessonExample('aile', 'عائلة'), LessonExample('anne / baba', 'أم / أب'), LessonExample('kardeş', 'أخ أو أخت'), LessonExample('çocuk', 'طفل')], question: 'ما معنى anne؟', options: ['أب', 'أم', 'أخ', 'جد'], answer: 1, feedback: 'anne تعني الأم.'),
    'a1-u4-2': LessonContent(goal: 'التحدث عن أفراد الأسرة والعلاقات العائلية.', explanation: 'تعرّف إلى كلمات مثل abla الأخت الكبرى، ağabey أو abi الأخ الأكبر، kız kardeş الأخت، erkek kardeş الأخ، وçocuk الطفل. قد تختلف صيغة الاستخدام اليومية عن الصيغة الكاملة.', examples: [LessonExample('Benim bir kız kardeşim var.', 'لدي أخت.'), LessonExample('İki erkek kardeşim var.', 'لدي أخوان.'), LessonExample('Ağabeyim burada.', 'أخي الأكبر هنا.')], question: 'ماذا تعني kız kardeş؟', options: ['أخ أصغر', 'أخت', 'أم', 'ابنة'], answer: 1, feedback: 'kız kardeş تعني أخت.'),
    'a1-u4-3': LessonContent(goal: 'استخدام صفات بسيطة لوصف الأشخاص.', explanation: 'يمكن وصف الأشخاص بصفات أساسية مثل uzun طويل، kısa قصير، genç شاب، yaşlı كبير في السن، çalışkan مجتهد، sakin هادئ. تأتي الصفة قبل الاسم عندما تصفه مباشرة.', examples: [LessonExample('uzun boylu', 'طويل القامة'), LessonExample('genç bir kadın', 'امرأة شابة'), LessonExample('çalışkan öğrenci', 'طالب مجتهد')], question: 'ما معنى genç؟', options: ['قديم', 'شاب', 'متعب', 'سريع'], answer: 1, feedback: 'genç تعني شاب أو صغير السن.'),
    'a1-u4-4': LessonContent(goal: 'السؤال عن أفراد العائلة وتقديم معلومات بسيطة عنهم.', explanation: 'استخدم Kim؟ للسؤال عن الشخص، وBu kim؟ بمعنى من هذا؟، وKaç kardeşin var؟ للسؤال عن عدد إخوتك. أجب بجملة قصيرة مع اسم الشخص أو صلة القرابة.', examples: [LessonExample('Bu kim?', 'من هذا؟'), LessonExample('Bu benim annem.', 'هذه أمي.'), LessonExample('Kaç kardeşin var?', 'كم أخاً أو أختاً لديك؟')], question: 'كيف تسأل «من هذا؟»', options: ['Bu ne?', 'Bu kim?', 'Nerede?', 'Kaç yaşında?'], answer: 1, feedback: 'Bu kim؟ تعني من هذا؟'),
    'a1-u4-5': LessonContent(goal: 'التعبير عن العمر عند الحديث عن أفراد الأسرة.', explanation: 'للسؤال عن عمر شخص آخر نستخدم Kaç yaşında؟ أي كم عمره/عمرها؟ وللإجابة نقول Annem kırk yaşında (أمي عمرها أربعون عاماً). لاحظ الفرق بين yaşındayım للمتكلم وyaşında للغائب.', examples: [LessonExample('Annem kaç yaşında?', 'كم عمر أمي؟'), LessonExample('Babam elli yaşında.', 'أبي عمره خمسون عاماً.'), LessonExample('Kardeşim on yaşında.', 'أخي/أختي عمره عشرة أعوام.')], question: 'أكمل: Babam otuz yaş___ .', options: ['-ındayım', '-ında', '-sın', '-ız'], answer: 1, feedback: 'مع الغائب نستخدم yaşında: Babam otuz yaşında.'),
    'a1-u4-6': LessonContent(goal: 'استخدام ضمائر الملكية مع أسماء أفراد العائلة.', explanation: 'تظهر الملكية كثيراً مع أسماء الأسرة: annem أمي، baban أبوك، kardeşi أخوه/أخته، ailemiz عائلتنا. انتبه إلى أن لاحقة الملكية تتصل بالكلمة، وقد تختلف وفق الانسجام الصوتي.', examples: [LessonExample('annem', 'أمي'), LessonExample('baban', 'أبوك'), LessonExample('kardeşimiz', 'أخونا / أختنا'), LessonExample('aileleri', 'عائلتهم')], question: 'ما معنى annem؟', options: ['أمك', 'أمي', 'أمه', 'أمنا'], answer: 1, feedback: 'anne + m تصبح annem، أي أمي.'),
    'a1-u4-7': LessonContent(goal: 'التحدث عن المهن والأنشطة اليومية لأفراد الأسرة.', explanation: 'من أسماء المهن öğretmen معلّم، doktor طبيب، mühendis مهندس، öğrenci طالب. لتكوين جملة اسمية استخدم لاحقة الشخص المناسبة: Annem öğretmen (أمي معلمة)، Babam doktor (أبي طبيب).', examples: [LessonExample('Annem öğretmen.', 'أمي معلمة.'), LessonExample('Babam doktor.', 'أبي طبيب.'), LessonExample('Kardeşim öğrenci.', 'أخي/أختي طالب.')], question: 'ما معنى doktor؟', options: ['مهندس', 'طبيب', 'معلم', 'طالب'], answer: 1, feedback: 'doktor تعني طبيب.'),
    'a1-u4-8': LessonContent(goal: 'إجراء حوار بسيط للتعريف بالعائلة.', explanation: 'في الحوار ابدأ بالسؤال Ailen nasıl؟ (كيف حال عائلتك؟) أو Ailende kaç kişi var؟ (كم شخصاً في عائلتك؟). أجب بعدد أفراد الأسرة، ثم اذكر شخصاً أو اثنين مع أعمارهم أو مهنهم.', examples: [LessonExample('Ailende kaç kişi var?', 'كم شخصاً في عائلتك؟'), LessonExample('Ailemde dört kişi var.', 'في عائلتي أربعة أشخاص.'), LessonExample('Annem öğretmen, babam doktor.', 'أمي معلمة وأبي طبيب.')], question: 'ما معنى Ailemde dört kişi var؟', options: ['عائلتي كبيرة', 'في عائلتي أربعة أشخاص', 'لدي أربعة إخوة', 'أبي طبيب'], answer: 1, feedback: 'Ailemde dört kişi var تعني في عائلتي أربعة أشخاص.'),
    'a1-u4-9': LessonContent(goal: 'مراجعة مفردات العائلة والصفات والعمر والمهن والملكية.', explanation: 'كوّن فقرة قصيرة من أربع أو خمس جمل عن عائلتك. اذكر عدد أفرادها، وصلة القرابة، والعمر أو المهنة، واستخدم لاحقة ملكية واحدة على الأقل.', examples: [LessonExample('Bu benim ailem.', 'هذه عائلتي.'), LessonExample('Bir kız kardeşim var.', 'لدي أخت.'), LessonExample('Annem genç ve çalışkan.', 'أمي شابة ومجتهدة.')], question: 'أي جملة تعني «لدي أخ»؟', options: ['Ben kardeşim.', 'Bir erkek kardeşim var.', 'Babam var.', 'Ailem dört kişi.'], answer: 1, feedback: 'Bir erkek kardeşim var تعني لدي أخ.'),

    'a1-u5-1': LessonContent(goal: 'تعلّم أسماء الأطعمة والمكوّنات الشائعة.', explanation: 'ابدأ بأسماء الطعام الأساسية. احفظ الاسم مع مثال أو صورة ذهنية، وانتبه إلى أن بعض الكلمات تُستخدم كاسم عام للطعام وبعضها لوجبة أو مكوّن محدد.', examples: [LessonExample('ekmek', 'خبز'), LessonExample('peynir', 'جبن'), LessonExample('yumurta', 'بيضة'), LessonExample('et', 'لحم'), LessonExample('sebze', 'خضروات'), LessonExample('meyve', 'فاكهة')], question: 'ما معنى peynir؟', options: ['خبز', 'جبن', 'حليب', 'بيض'], answer: 1, feedback: 'peynir تعني جبن.'),
    'a1-u5-2': LessonContent(goal: 'التعرّف إلى المشروبات وطلبها بطريقة بسيطة.', explanation: 'من المشروبات الشائعة su ماء، çay شاي، kahve قهوة، süt حليب، meyve suyu عصير فواكه. يمكن استخدام Bir ... lütfen لطلب شيء بأدب، أي واحد من ... من فضلك.', examples: [LessonExample('Bir çay, lütfen.', 'شاي واحد، من فضلك.'), LessonExample('Su istiyorum.', 'أريد ماءً.'), LessonExample('Kahve içer misin?', 'هل تشرب القهوة؟')], question: 'أي كلمة تعني «ماء»؟', options: ['süt', 'çay', 'su', 'kahve'], answer: 2, feedback: 'su تعني ماء.'),
    'a1-u5-3': LessonContent(goal: 'التحدث عن الوجبات وأوقات تناول الطعام.', explanation: 'وجبات اليوم: kahvaltı الإفطار، öğle yemeği الغداء، akşam yemeği العشاء. الفعل yemek يعني يأكل أو طعام بحسب السياق، وiçmek يعني يشرب. استخدم هذه الكلمات لوصف ما تتناوله خلال اليوم.', examples: [LessonExample('Kahvaltı yapıyorum.', 'أتناول الإفطار.'), LessonExample('Öğle yemeği yiyorum.', 'أتناول الغداء.'), LessonExample('Akşam çorba içiyorum.', 'أشرب الحساء مساءً.')], question: 'ما معنى kahvaltı؟', options: ['العشاء', 'الإفطار', 'الغداء', 'الحلوى'], answer: 1, feedback: 'kahvaltı تعني وجبة الإفطار.'),
    'a1-u5-4': LessonContent(goal: 'استخدام أحب ولا أحب عند الحديث عن الطعام.', explanation: 'للتعبير عن الإعجاب بشيء نستخدم hoşlanmak أو sevmek. مثال: Elma seviyorum (أحب التفاح). وللنفي نقول sevmiyorum (لا أحب). تذكّر أن نهاية الفعل تتغير بحسب الضمير والزمن.', examples: [LessonExample('Balık seviyorum.', 'أحب السمك.'), LessonExample('Kahve sevmiyorum.', 'لا أحب القهوة.'), LessonExample('Sebzeleri seviyor musun?', 'هل تحب الخضروات؟')], question: 'ما معنى sevmiyorum؟', options: ['أحب', 'لا أحب', 'أشرب', 'آكل'], answer: 1, feedback: 'sevmiyorum تعني لا أحب.'),
    'a1-u5-5': LessonContent(goal: 'السؤال عن الرغبة والاختيار بين الأطعمة.', explanation: 'Ne istersiniz؟ سؤال مهذب معناه ماذا ترغب؟، وNe istersin؟ صيغة غير رسمية. ويمكن أن تسأل Hangisini istersin؟ أيهما تريد؟. للإجابة استخدم ... istiyorum أو ... alayım.', examples: [LessonExample('Ne istersiniz?', 'ماذا ترغب؟ بصيغة مهذبة'), LessonExample('Bir çorba istiyorum.', 'أريد حساءً.'), LessonExample('Elma mı, muz mu?', 'تفاحة أم موزة؟')], question: 'ما معنى Ne istersiniz؟', options: ['أين تذهب؟', 'ماذا ترغب؟', 'كم عمرك؟', 'ما هذا؟'], answer: 1, feedback: 'Ne istersiniz؟ تعني ماذا ترغب؟ بصيغة مهذبة.'),
    'a1-u5-6': LessonContent(goal: 'طلب الطعام والشراب في مقهى أو مطعم.', explanation: 'استخدم عبارات مهذبة عند الطلب: Bir menü alabilir miyim؟ (هل يمكنني الحصول على قائمة؟)، Bir kahve lütfen (قهوة من فضلك)، Hesap lütfen (الحساب من فضلك). كلمة lütfen تجعل الطلب أكثر تهذيباً.', examples: [LessonExample('Menü alabilir miyim?', 'هل يمكنني الحصول على قائمة؟'), LessonExample('Bir çorba lütfen.', 'حساء من فضلك.'), LessonExample('Hesap lütfen.', 'الحساب من فضلك.')], question: 'كيف تطلب الحساب؟', options: ['Menü lütfen.', 'Hesap lütfen.', 'Su nerede?', 'Günaydın.'], answer: 1, feedback: 'Hesap lütfen تعني الحساب من فضلك.'),
    'a1-u5-7': LessonContent(goal: 'فهم الأسعار والسؤال عن تكلفة الطعام.', explanation: 'للسؤال عن السعر استخدم Ne kadar؟ أي كم السعر؟ أو Bu kaç lira؟ أي بكم هذا بالليرة؟. كلمة lira هي الليرة، ويمكن أن تذكر الرقم قبلها. راجع الأرقام التي تعلمتها في الوحدة الثانية.', examples: [LessonExample('Bu ne kadar?', 'كم سعر هذا؟'), LessonExample('Kaç lira?', 'كم ليرة؟'), LessonExample('Elli lira.', 'خمسون ليرة.')], question: 'أي سؤال يعني «كم السعر؟»', options: ['Ne kadar?', 'Nerelisin?', 'Ne zaman?', 'Kim bu?'], answer: 0, feedback: 'Ne kadar؟ تُستخدم للسؤال عن السعر أو المقدار.'),
    'a1-u5-8': LessonContent(goal: 'فهم حوار قصير بين الزبون والعامل في المطعم.', explanation: 'استمع أو اقرأ الحوار وحدد من يطلب ومن يجيب. لاحظ كلمات القائمة والطلب والتفضيل والحساب. في المطعم قد يقول العامل Buyurun (تفضل)، ويجيب الزبون بطلبه مع lütfen.', examples: [LessonExample('Garson: Buyurun, ne istersiniz?', 'النادل: تفضل، ماذا ترغب؟'), LessonExample('Müşteri: Bir çorba ve su lütfen.', 'الزبون: حساء وماء من فضلك.'), LessonExample('Garson: Başka bir şey?', 'النادل: شيء آخر؟'), LessonExample('Müşteri: Hayır, teşekkürler.', 'الزبون: لا، شكراً.')], question: 'ماذا تعني Başka bir şey؟', options: ['شيء آخر؟', 'كم السعر؟', 'القائمة هنا', 'أنا جائع'], answer: 0, feedback: 'Başka bir şey؟ تعني هل تريد شيئاً آخر؟'),
    'a1-u5-9': LessonContent(goal: 'مراجعة الطعام والمشروبات والوجبات والطلب والأسعار.', explanation: 'تدرّب على تسمية ثلاثة أطعمة ومشروبين، وقل ما تحبه وما لا تحبه، ثم مثّل حواراً قصيراً في مطعم يتضمن الطلب والسؤال عن السعر وطلب الحساب.', examples: [LessonExample('Bir tost ve çay istiyorum.', 'أريد شطيرة محمصة وشاياً.'), LessonExample('Bu ne kadar?', 'كم سعر هذا؟'), LessonExample('Hesap lütfen.', 'الحساب من فضلك.')], question: 'اختر العبارة الصحيحة لطلب «ماء من فضلك».', options: ['Bir su lütfen.', 'Su nerelisin?', 'Su kaç yaşında?', 'Ben su değilim.'], answer: 0, feedback: 'Bir su lütfen طلب بسيط للماء: ماء واحد من فضلك.'),

    'a1-u6-1': LessonContent(goal: 'التعرّف إلى أيام الأسبوع واستخدامها في جمل بسيطة.', explanation: 'أيام الأسبوع بالتركية: pazartesi الاثنين، salı الثلاثاء، çarşamba الأربعاء، perşembe الخميس، cuma الجمعة، cumartesi السبت، pazar الأحد. كلمة bugün تعني اليوم، وyarın تعني غداً، وdün تعني أمس.', examples: [LessonExample('Bugün pazartesi.', 'اليوم الاثنين.'), LessonExample('Yarın salı.', 'غداً الثلاثاء.'), LessonExample('Pazar günü dinleniyorum.', 'أستريح يوم الأحد.')], question: 'ما معنى cuma؟', options: ['الاثنين', 'الأربعاء', 'الجمعة', 'الأحد'], answer: 2, feedback: 'cuma تعني الجمعة.'),
    'a1-u6-2': LessonContent(goal: 'تسمية أشهر السنة وفهم ترتيبها.', explanation: 'أشهر السنة: ocak يناير، şubat فبراير، mart مارس، nisan أبريل، mayıs مايو، haziran يونيو، temmuz يوليو، ağustos أغسطس، eylül سبتمبر، ekim أكتوبر، kasım نوفمبر، aralık ديسمبر. تُكتب أسماء الأشهر بحرف صغير عادةً داخل الجملة.', examples: [LessonExample('Ocak', 'يناير'), LessonExample('Mayıs', 'مايو'), LessonExample('Ağustos', 'أغسطس'), LessonExample('Aralık', 'ديسمبر')], question: 'أي شهر يعني eylül؟', options: ['يونيو', 'سبتمبر', 'نوفمبر', 'فبراير'], answer: 1, feedback: 'eylül هو شهر سبتمبر.'),
    'a1-u6-3': LessonContent(goal: 'قراءة التاريخ والسؤال عن اليوم والتاريخ.', explanation: 'للسؤال عن التاريخ قل Bugün ayın kaçı؟ أي كم تاريخ اليوم؟. ويمكن ذكر التاريخ بصيغة 5 Mayıs (5 مايو). كلمة tarih تعني التاريخ، وhangi gün؟ تعني أي يوم؟. عند كتابة التاريخ استخدم الأرقام واسم الشهر.', examples: [LessonExample('Bugün ayın kaçı?', 'كم تاريخ اليوم؟'), LessonExample('Bugün 5 Mayıs.', 'اليوم الخامس من مايو.'), LessonExample('Bugün hangi gün?', 'أي يوم اليوم؟')], question: 'ما معنى Bugün hangi gün؟', options: ['كم الساعة؟', 'أي يوم اليوم؟', 'ما الشهر القادم؟', 'أين تذهب؟'], answer: 1, feedback: 'Bugün hangi gün؟ تعني أي يوم اليوم؟'),
    'a1-u6-4': LessonContent(goal: 'السؤال عن الوقت وقراءة الساعة الكاملة.', explanation: 'للسؤال عن الوقت نقول Saat kaç؟ أي كم الساعة؟. للإجابة عن الساعة الكاملة نستخدم Saat üç (الساعة الثالثة)، Saat beş (الخامسة). كلمة saat تعني ساعة أو وقت بحسب السياق. تدرب على الأرقام من واحد إلى اثني عشر.', examples: [LessonExample('Saat kaç?', 'كم الساعة؟'), LessonExample('Saat bir.', 'الساعة الواحدة.'), LessonExample('Saat dokuz.', 'الساعة التاسعة.')], question: 'كيف تقول «كم الساعة؟»', options: ['Bugün ne?', 'Saat kaç?', 'Hangi gün?', 'Kaç yaşında?'], answer: 1, feedback: 'Saat kaç؟ هو السؤال الشائع عن الوقت.'),
    'a1-u6-5': LessonContent(goal: 'التعبير عن الدقائق والنصف والربع في الوقت.', explanation: 'بعد تعلم الساعة الكاملة، تعرّف إلى buçuk بمعنى النصف، çeyrek بمعنى ربع، geçiyor للدقائق التي تجاوزت الساعة، وvar للدقائق المتبقية حتى الساعة التالية. في هذه المرحلة ركّز على العبارات الشائعة مثل saat üç buçuk (الثالثة والنصف) وüçü çeyrek geçiyor (الثالثة والربع).', examples: [LessonExample('Saat iki buçuk.', 'الساعة الثانية والنصف.'), LessonExample('Saat dördü çeyrek geçiyor.', 'الساعة الرابعة والربع.'), LessonExample('Beşe çeyrek var.', 'بقي ربع ساعة على الخامسة.')], question: 'ما معنى Saat iki buçuk؟', options: ['الثانية تماماً', 'الثانية والنصف', 'الثالثة والنصف', 'الثانية والربع'], answer: 1, feedback: 'buçuk تعني النصف؛ أي الثانية والنصف.'),
    'a1-u6-6': LessonContent(goal: 'وصف الروتين اليومي باستخدام أفعال شائعة.', explanation: 'من أفعال الروتين uyanmak يستيقظ، kalkmak ينهض، kahvaltı yapmak يتناول الإفطار، çalışmak يعمل أو يدرس، gitmek يذهب، dönmek يعود، uyumak ينام. استخدم المضارع المستمر -yor للحديث عن نشاط يحدث الآن أو عن الروتين القريب بحسب السياق.', examples: [LessonExample('Saat yedide uyanıyorum.', 'أستيقظ في السابعة.'), LessonExample('Kahvaltı yapıyorum.', 'أتناول الإفطار.'), LessonExample('Okula gidiyorum.', 'أذهب إلى المدرسة.')], question: 'ما معنى uyumak؟', options: ['يستيقظ', 'يذهب', 'ينام', 'يعمل'], answer: 2, feedback: 'uyumak تعني ينام.'),
    'a1-u6-7': LessonContent(goal: 'استخدام كلمات التكرار لوصف العادات اليومية.', explanation: 'تساعدك كلمات التكرار على وصف الروتين: her gün كل يوم، genellikle عادةً، bazen أحياناً، sık sık كثيراً، nadiren نادراً، hiç أبداً في سياق النفي. ضع كلمة التكرار غالباً قبل الفعل أو في موضع يوضح معنى الجملة.', examples: [LessonExample('Her gün kitap okuyorum.', 'أقرأ كتاباً كل يوم.'), LessonExample('Bazen yürüyüş yapıyorum.', 'أحياناً أتمشى.'), LessonExample('Genellikle erken kalkıyorum.', 'عادةً أستيقظ مبكراً.')], question: 'ما معنى bazen؟', options: ['دائماً', 'أحياناً', 'أبداً', 'غداً'], answer: 1, feedback: 'bazen تعني أحياناً.'),
    'a1-u6-8': LessonContent(goal: 'السؤال عن المواعيد والاتفاق على وقت للقاء.', explanation: 'يمكن السؤال Ne zaman؟ (متى؟)، Saat kaçta؟ (في أي ساعة؟)، وHangi gün؟ (في أي يوم؟). للتعبير عن وقت وقوع الفعل نضيف لاحقة الحالة الزمنية -da/-de أو -ta/-te بحسب الانسجام الصوتي والتغيرات الصوتية، مثل saat üçte (في الساعة الثالثة) وpazartesi günü (يوم الاثنين).', examples: [LessonExample('Ne zaman buluşuyoruz?', 'متى نلتقي؟'), LessonExample('Saat kaçta?', 'في أي ساعة؟'), LessonExample('Saat beşte buluşalım.', 'لنلتقِ في الساعة الخامسة.')], question: 'أي عبارة تعني «في أي ساعة؟»', options: ['Saat kaçta?', 'Saat kaç?', 'Kaç yaşında?', 'Nerede?'], answer: 0, feedback: 'Saat kaçta؟ تسأل عن وقت حدوث النشاط.'),
    'a1-u6-9': LessonContent(goal: 'مراجعة الأيام والأشهر والتاريخ والساعة والروتين اليومي.', explanation: 'كوّن وصفاً ليومك من خمس جمل: اذكر اليوم، ووقت الاستيقاظ، ووجبة الإفطار، وموعد الذهاب إلى المدرسة أو العمل، ووقت النوم. أضف كلمة تكرار مثل her gün أو bazen.', examples: [LessonExample('Bugün cuma.', 'اليوم الجمعة.'), LessonExample('Saat yedide kalkıyorum.', 'أنهض في السابعة.'), LessonExample('Akşam saat onda uyuyorum.', 'أنام مساءً في الساعة العاشرة.')], question: 'اختر العبارة الصحيحة لمعنى «أستيقظ كل يوم في السابعة».', options: ['Her gün saat yedide uyanıyorum.', 'Yarın cuma.', 'Saat kaç?', 'Pazar günü dinleniyorum.'], answer: 0, feedback: 'Her gün تعني كل يوم، وsaat yedide تعني في السابعة، وuyanıyorum تعني أستيقظ.'),

    'a1-u7-1': LessonContent(goal: 'التعرّف إلى أسماء المنزل والغرف الأساسية.', explanation: 'كلمة ev تعني منزل أو بيت. من أسماء الغرف oda غرفة، oturma odası غرفة الجلوس، yatak odası غرفة النوم، mutfak مطبخ، banyo حمّام، balkon شرفة، bahçe حديقة. لاحظ أن بعض أسماء الغرف مركّبة من كلمتين.', examples: [LessonExample('ev', 'منزل'), LessonExample('mutfak', 'مطبخ'), LessonExample('yatak odası', 'غرفة نوم'), LessonExample('oturma odası', 'غرفة جلوس'), LessonExample('banyo', 'حمّام')], question: 'ما معنى mutfak؟', options: ['غرفة نوم', 'مطبخ', 'حديقة', 'شرفة'], answer: 1, feedback: 'mutfak تعني مطبخ.'),
    'a1-u7-2': LessonContent(goal: 'تسمية قطع الأثاث والأشياء الموجودة في المنزل.', explanation: 'تعلّم أسماء الأثاث الشائعة: masa طاولة، sandalye كرسي، koltuk أريكة، yatak سرير، dolap خزانة، lamba مصباح، halı سجادة، perde ستارة. اربط كل كلمة بالغرفة التي توجد فيها عادةً.', examples: [LessonExample('masa ve sandalye', 'طاولة وكرسي'), LessonExample('yatak', 'سرير'), LessonExample('koltuk', 'أريكة'), LessonExample('dolap', 'خزانة'), LessonExample('lamba', 'مصباح')], question: 'أي كلمة تعني «سرير»؟', options: ['yatak', 'perde', 'halı', 'masa'], answer: 0, feedback: 'yatak تعني سرير.'),
    'a1-u7-3': LessonContent(goal: 'وصف المنزل والغرف باستخدام الصفات الأساسية.', explanation: 'يمكن وصف المنزل بكلمات büyük كبير، küçük صغير، geniş واسع، dar ضيّق، güzel جميل، temiz نظيف، eski قديم، yeni جديد. تأتي الصفة قبل الاسم: büyük ev منزل كبير، temiz oda غرفة نظيفة.', examples: [LessonExample('büyük bir ev', 'منزل كبير'), LessonExample('küçük oda', 'غرفة صغيرة'), LessonExample('temiz mutfak', 'مطبخ نظيف'), LessonExample('geniş balkon', 'شرفة واسعة')], question: 'ما معنى geniş؟', options: ['ضيق', 'واسع', 'قديم', 'متسخ'], answer: 1, feedback: 'geniş تعني واسع.'),
    'a1-u7-4': LessonContent(goal: 'التعبير عن وجود الأشياء أو عدم وجودها باستخدام var وyok.', explanation: 'تُستخدم var للتعبير عن وجود شيء، وyok للتعبير عن عدم وجوده. مثال: Evde balkon var (يوجد شرفة في المنزل)، Evde garaj yok (لا يوجد مرآب في المنزل). ضع اسم المكان في صيغة -da/-de بحسب الانسجام الصوتي.', examples: [LessonExample('Evde üç oda var.', 'يوجد في المنزل ثلاث غرف.'), LessonExample('Mutfakta masa var.', 'توجد طاولة في المطبخ.'), LessonExample('Bahçede havuz yok.', 'لا يوجد مسبح في الحديقة.')], question: 'أي كلمة تعبّر عن عدم وجود شيء؟', options: ['var', 'yok', 'çok', 'ile'], answer: 1, feedback: 'yok تعني غير موجود أو لا يوجد.'),
    'a1-u7-5': LessonContent(goal: 'تحديد مكان الأشياء داخل المنزل.', explanation: 'استخدم كلمات المكان لوصف موقع الأثاث: içinde داخل، üstünde فوق، altında تحت، yanında بجانب، önünde أمام، arkasında خلف، arasında بين. أمثلة: kitap masanın üstünde (الكتاب فوق الطاولة)، koltuk pencerenin yanında (الأريكة بجانب النافذة).', examples: [LessonExample('Kitap masanın üstünde.', 'الكتاب فوق الطاولة.'), LessonExample('Kedi koltuğun altında.', 'القطة تحت الأريكة.'), LessonExample('Lamba yatağın yanında.', 'المصباح بجانب السرير.')], question: 'ما معنى yanında؟', options: ['داخل', 'خلف', 'بجانب', 'تحت'], answer: 2, feedback: 'yanında تعني بجانب.'),
    'a1-u7-6': LessonContent(goal: 'استخدام لاحقة المكان -da/-de/-ta/-te للسؤال والإجابة عن الموقع.', explanation: 'تُضاف لاحقة المكان إلى الاسم للإجابة عن سؤال Nerede؟ (أين؟). نختار -da أو -de وفق آخر حركة، وقد تتحول d إلى t بعد بعض الحروف المهموسة مثل ç, f, h, k, p, s, ş, t. أمثلة: evde في المنزل، okulda في المدرسة، parkta في الحديقة العامة.', examples: [LessonExample('Evdeyim.', 'أنا في المنزل.'), LessonExample('Kitap çantada.', 'الكتاب في الحقيبة.'), LessonExample('Çocuk parkta.', 'الطفل في الحديقة.')], question: 'ما الصيغة الصحيحة لمعنى «في المنزل»؟', options: ['evda', 'evde', 'evta', 'evte'], answer: 1, feedback: 'ev تنتهي بحركة أمامية e، لذلك نقول evde.'),
    'a1-u7-7': LessonContent(goal: 'السؤال عن الأماكن والاتجاهات الأساسية داخل المنزل.', explanation: 'للسؤال عن مكان شيء نستخدم Nerede؟ (أين؟)، وللسؤال عن الاتجاه Ne tarafta؟ (في أي جهة؟). من كلمات الاتجاه sağ يمين، sol يسار، ön أمام، arka خلف، yukarı أعلى، aşağı أسفل. يمكن الإجابة بجملة قصيرة مثل Mutfakta (في المطبخ).', examples: [LessonExample('Banyo nerede?', 'أين الحمّام؟'), LessonExample('Sağ tarafta.', 'في الجهة اليمنى.'), LessonExample('Merdivenler yukarıda.', 'السلالم في الأعلى.')], question: 'ما معنى sol؟', options: ['يمين', 'يسار', 'أمام', 'أعلى'], answer: 1, feedback: 'sol تعني يسار.'),
    'a1-u7-8': LessonContent(goal: 'إجراء حوار بسيط لوصف المنزل ومكان الأثاث.', explanation: 'في الحوار اسأل عن المنزل أو الغرفة: Evin nasıl؟ (كيف منزلك؟)، Kaç odası var؟ (كم غرفة فيه؟)، Mutfak nerede؟ (أين المطبخ؟). أجب بصفة أو عدد أو موقع، واستخدم var/yok لتذكر ما يوجد وما لا يوجد.', examples: [LessonExample('A: Evin büyük mü?', 'أ: هل منزلك كبير؟'), LessonExample('B: Hayır, küçük ama güzel.', 'ب: لا، إنه صغير لكنه جميل.'), LessonExample('A: Salonda ne var?', 'أ: ماذا يوجد في غرفة الجلوس؟'), LessonExample('B: Bir koltuk ve iki sandalye var.', 'ب: توجد أريكة واحدة وكرسيان.')], question: 'ماذا تعني Salonda ne var؟', options: ['أين غرفة الجلوس؟', 'ماذا يوجد في غرفة الجلوس؟', 'هل المنزل كبير؟', 'كم سعر الأريكة؟'], answer: 1, feedback: 'Salonda ne var؟ تسأل عمّا يوجد في غرفة الجلوس.'),
    'a1-u7-9': LessonContent(goal: 'مراجعة المنزل والغرف والأثاث والصفات والمواقع والاتجاهات.', explanation: 'صف منزلاً من خمس جمل: اذكر عدد الغرف، وصف غرفة واحدة، وسمّ قطعتين من الأثاث، ثم حدّد مكان شيء باستخدام üstünde أو yanında، واستخدم var أو yok في جملة.', examples: [LessonExample('Evimiz küçük ama güzel.', 'منزلنا صغير لكنه جميل.'), LessonExample('Mutfakta bir masa var.', 'توجد طاولة في المطبخ.'), LessonExample('Koltuk pencerenin yanında.', 'الأريكة بجانب النافذة.')], question: 'اختر الجملة التي تعني «يوجد سرير في غرفة النوم».', options: ['Yatak odasında yatak var.', 'Mutfakta masa yok.', 'Ev çok büyük.', 'Koltuk salonda.'], answer: 0, feedback: 'Yatak odasında تعني في غرفة النوم، وyatak var تعني يوجد سرير.'),

    'a1-u8-1': LessonContent(goal: 'التعرّف إلى أسماء الملابس الشائعة باللغة التركية.', explanation: 'ابدأ بأسماء الملابس التي تستخدمها يومياً: gömlek قميص، tişört قميص قطني، pantolon بنطال، etek تنورة، elbise فستان، ceket سترة، mont معطف، ayakkabı حذاء، çorap جورب، şapka قبعة. احفظ الكلمة مع أداة أو قطعة ملابس تتذكرها.', examples: [LessonExample('gömlek', 'قميص'), LessonExample('pantolon', 'بنطال'), LessonExample('elbise', 'فستان'), LessonExample('ayakkabı', 'حذاء'), LessonExample('mont', 'معطف')], question: 'ما معنى ayakkabı؟', options: ['قبعة', 'حذاء', 'قميص', 'جورب'], answer: 1, feedback: 'ayakkabı تعني حذاء.'),
    'a1-u8-2': LessonContent(goal: 'وصف الملابس بالألوان والصفات الأساسية.', explanation: 'تأتي الصفة عادة قبل الاسم في التركية. من الألوان: siyah أسود، beyaz أبيض، kırmızı أحمر، mavi أزرق، yeşil أخضر، sarı أصفر. ومن صفات الملابس yeni جديد، eski قديم، güzel جميل، uzun طويل، kısa قصير. مثال: siyah bir ceket سترة سوداء.', examples: [LessonExample('kırmızı elbise', 'فستان أحمر'), LessonExample('siyah ayakkabı', 'حذاء أسود'), LessonExample('mavi gömlek', 'قميص أزرق'), LessonExample('uzun etek', 'تنورة طويلة')], question: 'ما معنى sarı؟', options: ['أخضر', 'أصفر', 'أزرق', 'أبيض'], answer: 1, feedback: 'sarı تعني أصفر.'),
    'a1-u8-3': LessonContent(goal: 'السؤال عن مقاسات الملابس وفهم المقاسات الشائعة.', explanation: 'تُستخدم كلمة beden للمقاس. للسؤال عن المقاس قل Kaç beden؟ (أي مقاس؟)، وللسؤال عن حجم قطعة معينة قل Bu kaç beden؟. قد ترى المقاسات S وM وL وXL، كما يمكن وصف المقاس بـ küçük صغير، orta متوسط، büyük كبير.', examples: [LessonExample('beden', 'مقاس الملابس'), LessonExample('Kaç beden?', 'أي مقاس؟'), LessonExample('orta beden', 'مقاس متوسط'), LessonExample('büyük beden', 'مقاس كبير')], question: 'ما معنى beden في متجر الملابس؟', options: ['لون', 'مقاس', 'سعر', 'قماش'], answer: 1, feedback: 'beden تعني مقاس الملابس أو حجمها.'),
    'a1-u8-4': LessonContent(goal: 'السؤال عن السعر وفهم الإجابات في المتجر.', explanation: 'للسؤال عن السعر استخدم Bu ne kadar؟ (كم سعر هذا؟) أو Fiyatı ne kadar؟ (كم سعره؟). كلمة fiyat تعني السعر، وindirim تعني تخفيضاً، وpahalı غالٍ، وucuz رخيص. يمكن أن تسمع السعر متبوعاً بكلمة lira.', examples: [LessonExample('Bu ne kadar?', 'كم سعر هذا؟'), LessonExample('Fiyatı ne kadar?', 'كم سعره؟'), LessonExample('Çok pahalı.', 'إنه غالٍ جداً.'), LessonExample('İndirim var mı?', 'هل يوجد تخفيض؟')], question: 'ما معنى ucuz؟', options: ['غالٍ', 'رخيص', 'جميل', 'جديد'], answer: 1, feedback: 'ucuz تعني رخيص.'),
    'a1-u8-5': LessonContent(goal: 'استخدام عبارات مهذبة لطلب المساعدة في متجر الملابس.', explanation: 'عند دخول المتجر قد تسمع Hoş geldiniz (أهلاً وسهلاً). يمكنك قول Yardım eder misiniz؟ (هل تساعدني؟) أو Şu gömleği arıyorum (أبحث عن ذلك القميص). كلمة lütfen تضيف التهذيب إلى الطلب، وteşekkür ederim تعني شكراً لك.', examples: [LessonExample('Yardım eder misiniz?', 'هل يمكنكم مساعدتي؟'), LessonExample('Bir ceket arıyorum.', 'أبحث عن سترة.'), LessonExample('Teşekkür ederim.', 'شكراً لك.'), LessonExample('Rica ederim.', 'على الرحب والسعة.')], question: 'أي عبارة تعني «هل يمكنكم مساعدتي؟»', options: ['Yardım eder misiniz?', 'Kaç yaşındasın?', 'Saat kaç?', 'Nerede oturuyorsun?'], answer: 0, feedback: 'Yardım eder misiniz؟ صيغة مهذبة لطلب المساعدة.'),
    'a1-u8-6': LessonContent(goal: 'طلب تجربة الملابس قبل اتخاذ قرار الشراء.', explanation: 'غرفة القياس تُسمّى deneme kabini أو kabin. لطلب تجربة قطعة ملابس قل Deneyebilir miyim؟ (هل يمكنني تجربتها؟)، وللسؤال عن مكان غرفة القياس قل Deneme kabini nerede؟. بعد التجربة يمكنك وصفها: Çok büyük (كبيرة جداً) أو Tam oldu (المقاس مناسب تماماً).', examples: [LessonExample('Deneyebilir miyim?', 'هل يمكنني تجربتها؟'), LessonExample('Deneme kabini nerede?', 'أين غرفة القياس؟'), LessonExample('Tam oldu.', 'المقاس مناسب تماماً.'), LessonExample('Biraz küçük.', 'صغيرة قليلاً.')], question: 'ما معنى Deneme kabini nerede؟', options: ['كم السعر؟', 'أين غرفة القياس؟', 'هل يوجد تخفيض؟', 'أين المتجر؟'], answer: 1, feedback: 'Deneme kabini nerede؟ تعني أين غرفة القياس؟'),
    'a1-u8-7': LessonContent(goal: 'التعبير عن الاختيار وقرار الشراء أو عدمه.', explanation: 'للتعبير عن اختيارك يمكنك قول Bunu istiyorum (أريد هذا)، Bunu alıyorum (سآخذ هذا)، أو Başka bir renk var mı؟ (هل يوجد لون آخر؟). للإشارة إلى شيء قريب استخدم bu، وللإشارة إلى شيء أبعد استخدم şu أو o بحسب السياق.', examples: [LessonExample('Bunu istiyorum.', 'أريد هذا.'), LessonExample('Bunu alıyorum.', 'سآخذ هذا.'), LessonExample('Başka bir renk var mı?', 'هل يوجد لون آخر؟'), LessonExample('Sadece bakıyorum.', 'أنا أتفرج فقط.')], question: 'ما معنى Bunu alıyorum؟', options: ['أبحث عن هذا', 'سآخذ هذا', 'كم سعر هذا؟', 'لا أريد هذا'], answer: 1, feedback: 'Bunu alıyorum تعني سآخذ هذا أو أشتريه.'),
    'a1-u8-8': LessonContent(goal: 'فهم حوار قصير عند شراء الملابس والدفع.', explanation: 'يجمع هذا الحوار بين السؤال عن قطعة ملابس، والمقاس والسعر، وتجربتها، ثم اتخاذ قرار الشراء. من العبارات المفيدة Kasada ödeme yapabilirsiniz (يمكنك الدفع عند الصندوق)، Nakit أو kart (نقداً أو بالبطاقة)، وFiş alabilir miyim؟ (هل يمكنني أخذ الإيصال؟).', examples: [LessonExample('Müşteri: Bu gömlek ne kadar?', 'الزبون: كم سعر هذا القميص؟'), LessonExample('Satıcı: Beş yüz lira.', 'البائع: خمسمئة ليرة.'), LessonExample('Müşteri: Deneyebilir miyim?', 'الزبون: هل يمكنني تجربته؟'), LessonExample('Satıcı: Tabii, buyurun.', 'البائع: بالتأكيد، تفضل.')], question: 'ماذا تعني Tabii؟', options: ['مستحيل', 'بالتأكيد', 'غالي جداً', 'لا أعرف'], answer: 1, feedback: 'Tabii تعني بالطبع أو بالتأكيد.'),
    'a1-u8-9': LessonContent(goal: 'مراجعة الملابس والألوان والمقاسات والأسعار والشراء.', explanation: 'تدرّب على تسمية خمس قطع ملابس، ووصف قطعتين بلونهما، والسؤال عن المقاس والسعر، ثم إجراء حوار قصير تطلب فيه تجربة قطعة وتقرر شراءها أو البحث عن لون آخر.', examples: [LessonExample('Mavi bir gömlek arıyorum.', 'أبحث عن قميص أزرق.'), LessonExample('Kaç beden?', 'أي مقاس؟'), LessonExample('Biraz pahalı ama güzel.', 'إنه غالٍ قليلاً لكنه جميل.'), LessonExample('Bunu alıyorum.', 'سآخذ هذا.')], question: 'اختر العبارة الصحيحة لمعنى «هل يمكنني تجربتها؟».', options: ['Deneyebilir miyim?', 'Ne kadar?', 'Bunu alıyorum.', 'Hangi gün?'], answer: 0, feedback: 'Deneyebilir miyim؟ هي العبارة المناسبة لطلب تجربة الملابس.'),

    'a1-u9-1': LessonContent(goal: 'التعرّف إلى أسماء الأماكن المهمة في المدينة.', explanation: 'تعلّم أسماء الأماكن التي قد تحتاج إليها أثناء التجول: şehir مدينة، sokak شارع، cadde جادة، meydan ساحة، park حديقة، hastane مستشفى، eczane صيدلية، okul مدرسة، banka بنك، market متجر، postane مكتب بريد، polis merkezi مركز شرطة.', examples: [LessonExample('hastane', 'مستشفى'), LessonExample('eczane', 'صيدلية'), LessonExample('banka', 'بنك'), LessonExample('park', 'حديقة'), LessonExample('meydan', 'ساحة')], question: 'ما معنى eczane؟', options: ['مدرسة', 'صيدلية', 'بنك', 'مستشفى'], answer: 1, feedback: 'eczane تعني صيدلية.'),
    'a1-u9-2': LessonContent(goal: 'تسمية وسائل النقل الشائعة.', explanation: 'من وسائل النقل ulaşım مواصلات، otobüs حافلة، metro مترو، tramvay ترام، tren قطار، taksi سيارة أجرة، araba سيارة، bisiklet دراجة، vapur عبّارة، uçak طائرة. الفعل binmek يعني يركب وسيلة نقل، ويمكن أن تقول otobüse biniyorum أي أركب الحافلة.', examples: [LessonExample('otobüs', 'حافلة'), LessonExample('metro', 'مترو'), LessonExample('tren', 'قطار'), LessonExample('taksi', 'سيارة أجرة'), LessonExample('bisiklet', 'دراجة')], question: 'ما معنى tren؟', options: ['طائرة', 'قطار', 'حافلة', 'دراجة'], answer: 1, feedback: 'tren تعني قطار.'),
    'a1-u9-3': LessonContent(goal: 'السؤال عن موقع الأماكن في المدينة والإجابة عنه.', explanation: 'السؤال الأساسي عن المكان هو Nerede؟ أي أين؟. يمكنك أن تسأل Hastane nerede؟ (أين المستشفى؟)، وتجيب Yakında (بالقرب)، Uzakta (بعيد)، أو Sağda/Solda (على اليمين/اليسار). كلمة burada تعني هنا، وorada تعني هناك.', examples: [LessonExample('Banka nerede?', 'أين البنك؟'), LessonExample('Burada.', 'هنا.'), LessonExample('Eczane yakında.', 'الصيدلية قريبة.'), LessonExample('Okul uzakta.', 'المدرسة بعيدة.')], question: 'ما معنى yakında؟', options: ['بعيد', 'قريب', 'خلف', 'فوق'], answer: 1, feedback: 'yakında تعني قريب أو بالقرب.'),
    'a1-u9-4': LessonContent(goal: 'فهم الاتجاهات الأساسية وإعطاء تعليمات بسيطة.', explanation: 'اتجاهات مهمة: sağ يمين، sol يسار، düz مستقيم، geri إلى الخلف، kuzey شمال، güney جنوب، doğu شرق، batı غرب. عبارات مفيدة: Sağa dön (انعطف يميناً)، Sola dön (انعطف يساراً)، Düz git (تابع مستقيماً).', examples: [LessonExample('Sağa dön.', 'انعطف يميناً.'), LessonExample('Sola dön.', 'انعطف يساراً.'), LessonExample('Düz git.', 'تابع مستقيماً.'), LessonExample('İleri git.', 'تقدم إلى الأمام.')], question: 'ما معنى Düz git؟', options: ['انعطف يساراً', 'تابع مستقيماً', 'ارجع للخلف', 'توقف هنا'], answer: 1, feedback: 'Düz git تعني تابع السير مستقيماً.'),
    'a1-u9-5': LessonContent(goal: 'السؤال عن الطريق إلى مكان معين.', explanation: 'للسؤال بأدب استخدم ... nasıl gidebilirim؟ أي كيف يمكنني الذهاب إلى ...؟. مثال: Hastaneye nasıl gidebilirim؟ (كيف أصل إلى المستشفى؟). كلمة yakın قريب، uzak بعيد، karşısında مقابل، yanında بجانب، köşede عند الزاوية.', examples: [LessonExample('İstasyona nasıl gidebilirim?', 'كيف أصل إلى المحطة؟'), LessonExample('Düz gidin.', 'تابعوا مستقيماً بصيغة مهذبة.'), LessonExample('Sağda, köşede.', 'على اليمين عند الزاوية.'), LessonExample('Çok uzak mı?', 'هل هو بعيد جداً؟')], question: 'أي سؤال يعني «كيف أصل إلى المستشفى؟»', options: ['Hastaneye nasıl gidebilirim?', 'Saat kaç?', 'Bu ne kadar?', 'Nerelisin?'], answer: 0, feedback: 'Hastaneye nasıl gidebilirim؟ هو السؤال عن كيفية الوصول إلى المستشفى.'),
    'a1-u9-6': LessonContent(goal: 'استخدام وسائل النقل والسؤال عن الوجهة والمدة.', explanation: 'يمكنك أن تقول Otobüsle gidiyorum (أذهب بالحافلة)، Metroyla gidiyorum (أذهب بالمترو)، أو yürüyerek gidiyorum (أذهب مشياً). اللاحقة -le/-la تعني بواسطة أو مع، وتأتي بعد اسم وسيلة النقل. للسؤال عن المدة قل Ne kadar sürüyor؟ أي كم يستغرق؟.', examples: [LessonExample('Otobüsle gidiyorum.', 'أذهب بالحافلة.'), LessonExample('Metroyla merkeze gidiyorum.', 'أذهب إلى المركز بالمترو.'), LessonExample('Yürüyerek gidiyorum.', 'أذهب مشياً.'), LessonExample('Ne kadar sürüyor?', 'كم يستغرق؟')], question: 'ما معنى Otobüsle gidiyorum؟', options: ['أنتظر الحافلة', 'أذهب بالحافلة', 'أقود الحافلة', 'أشتري حافلة'], answer: 1, feedback: 'Otobüsle تعني بواسطة الحافلة، وgidiyorum تعني أذهب.'),
    'a1-u9-7': LessonContent(goal: 'التعرّف إلى التذاكر والسؤال عن الأجرة.', explanation: 'كلمات مفيدة: bilet تذكرة، ücret أجرة، kart بطاقة، durak موقف، istasyon محطة، tek yön ذهاب فقط، gidiş dönüş ذهاب وإياب. يمكنك السؤال Bir bilet ne kadar؟ (كم سعر التذكرة؟) أو Nereden bilet alabilirim؟ (من أين أستطيع شراء تذكرة؟).', examples: [LessonExample('Bir bilet lütfen.', 'تذكرة واحدة من فضلك.'), LessonExample('Bilet ne kadar?', 'كم سعر التذكرة؟'), LessonExample('Otobüs durağı nerede?', 'أين موقف الحافلة؟'), LessonExample('İki bilet istiyorum.', 'أريد تذكرتين.')], question: 'ما معنى bilet؟', options: ['موقف', 'تذكرة', 'شارع', 'محطة'], answer: 1, feedback: 'bilet تعني تذكرة.'),
    'a1-u9-8': LessonContent(goal: 'إجراء حوار قصير لطلب الاتجاهات واستخدام المواصلات.', explanation: 'في الحوار ابدأ بالتحية ثم اسأل عن المكان أو وسيلة النقل المناسبة. استمع إلى كلمات الاتجاه مثل sağ وsol وdüz، وانتبه إلى أسماء المحطات والمواقف. عند عدم الفهم يمكنك قول Tekrar eder misiniz؟ (هل يمكنكم الإعادة؟).', examples: [LessonExample('A: Affedersiniz, metro nerede?', 'أ: عذراً، أين المترو؟'), LessonExample('B: Düz gidin, sonra sola dönün.', 'ب: تابعوا مستقيماً ثم انعطفوا يساراً.'), LessonExample('A: Çok teşekkür ederim.', 'أ: شكراً جزيلاً.'), LessonExample('B: Rica ederim.', 'ب: على الرحب والسعة.')], question: 'ما معنى Tekrar eder misiniz؟', options: ['هل يمكنكم الإعادة؟', 'كم ثمنها؟', 'أين تسكن؟', 'هل أنت جائع؟'], answer: 0, feedback: 'Tekrar eder misiniz؟ طلب مهذب لإعادة الكلام.'),
    'a1-u9-9': LessonContent(goal: 'مراجعة أماكن المدينة والمواصلات والاتجاهات والتذاكر.', explanation: 'تدرّب على وصف طريق من مكانك إلى محطة المترو في أربع تعليمات قصيرة. اذكر وسيلة النقل التي تستخدمها، واسأل عن سعر تذكرة، ثم اكتب حواراً من أربعة أسطر تطلب فيه المساعدة بأدب.', examples: [LessonExample('Metro istasyonu nerede?', 'أين محطة المترو؟'), LessonExample('Düz gidin ve sağa dönün.', 'تابعوا مستقيماً ثم انعطفوا يميناً.'), LessonExample('Bir bilet lütfen.', 'تذكرة واحدة من فضلك.')], question: 'اختر العبارة الصحيحة لمعنى «أذهب بالمترو».', options: ['Metroyla gidiyorum.', 'Metro ne kadar?', 'Metro nerede?', 'Metroyu seviyor musun?'], answer: 0, feedback: 'Metroyla gidiyorum تعني أذهب باستخدام المترو.'),

    'a1-u10-1': LessonContent(goal: 'التعرّف إلى أسماء أجزاء الجسم الأساسية باللغة التركية.', explanation: 'تعلّم المفردات الأساسية: baş رأس، saç شعر، göz عين، kulak أذن، burun أنف، ağız فم، diş سن، boyun رقبة، omuz كتف، kol ذراع، el يد، parmak إصبع، bacak ساق، ayak قدم، sırt ظهر، karın بطن. استخدم هذه الكلمات في جمل قصيرة لوصف الجسم.', examples: [LessonExample('baş', 'رأس'), LessonExample('göz', 'عين'), LessonExample('kulak', 'أذن'), LessonExample('el', 'يد'), LessonExample('ayak', 'قدم')], question: 'ما معنى burun؟', options: ['أذن', 'أنف', 'عين', 'فم'], answer: 1, feedback: 'burun تعني أنف.'),
    'a1-u10-2': LessonContent(goal: 'التعبير عن الحواس والأفعال اليومية المرتبطة بالجسم.', explanation: 'من الأفعال المفيدة görmek يرى، duymak يسمع، koklamak يشم، tatmak يتذوق، dokunmak يلمس، yürümek يمشي، koşmak يركض، oturmak يجلس. يمكن تكوين جمل بسيطة مثل Gözlerimle görüyorum (أرى بعينيّ) وKulaklarımla duyuyorum (أسمع بأذنيّ).', examples: [LessonExample('Görmek', 'الرؤية'), LessonExample('Duymak', 'السمع'), LessonExample('Yürümek', 'المشي'), LessonExample('Koşmak', 'الركض'), LessonExample('Elimi yıkıyorum.', 'أغسل يدي.')], question: 'أي فعل يعني «يسمع»؟', options: ['görmek', 'duymak', 'yürümek', 'oturmak'], answer: 1, feedback: 'duymak يعني يسمع.'),
    'a1-u10-3': LessonContent(goal: 'تعلّم مفردات الصحة والعافية والتعبير عن الشعور العام.', explanation: 'كلمات أساسية: sağlık صحة، hasta مريض، sağlıklı بصحة جيدة، yorgun متعب، iyi جيد، kötü سيئ، ağrı ألم، ateş حرارة، öksürük سعال، dinlenmek يستريح. للتعبير عن حالتك يمكنك قول İyiyim (أنا بخير)، Yorgunum (أنا متعب)، أو Kendimi iyi hissetmiyorum (لا أشعر أنني بخير).', examples: [LessonExample('Nasılsın?', 'كيف حالك؟'), LessonExample('İyiyim, teşekkürler.', 'أنا بخير، شكراً.'), LessonExample('Biraz yorgunum.', 'أنا متعب قليلاً.'), LessonExample('Kendimi iyi hissetmiyorum.', 'لا أشعر أنني بخير.')], question: 'ما معنى yorgun؟', options: ['سعيد', 'متعب', 'جائع', 'سريع'], answer: 1, feedback: 'yorgun تعني متعب.'),
    'a1-u10-4': LessonContent(goal: 'وصف الأعراض الشائعة بعبارات تركية بسيطة.', explanation: 'يمكن وصف بعض الأعراض بكلمات مثل baş ağrısı صداع، boğaz ağrısı ألم الحلق، karın ağrısı ألم البطن، diş ağrısı ألم الأسنان، ateş حرارة، öksürük سعال، burun akıntısı سيلان الأنف. للتعبير عن وجود الألم قل Başım ağrıyor (رأسي يؤلمني) أو Boğazım ağrıyor (حلقي يؤلمني). هذه عبارات لغوية للتواصل وليست بديلاً عن تقييم المختص.', examples: [LessonExample('Başım ağrıyor.', 'رأسي يؤلمني.'), LessonExample('Dişim ağrıyor.', 'سني يؤلمني.'), LessonExample('Boğazım ağrıyor.', 'حلقي يؤلمني.'), LessonExample('Öksürüğüm var.', 'لديّ سعال.')], question: 'ما العبارة التي تعني «رأسي يؤلمني»؟', options: ['Başım ağrıyor.', 'Karnım tok.', 'İyiyim.', 'Su içiyorum.'], answer: 0, feedback: 'Başım ağrıyor تعني رأسي يؤلمني.'),
    'a1-u10-5': LessonContent(goal: 'التعرّف إلى الأماكن والأشخاص والخدمات الطبية.', explanation: 'أماكن وخدمات مهمة: hastane مستشفى، klinik عيادة، eczane صيدلية، doktor طبيب، hemşire ممرض أو ممرضة، hasta مريض، randevu موعد، muayene فحص طبي. اسأل عن المكان بعبارة Hastane nerede؟ (أين المستشفى؟)، وعن الموعد Randevum var (لدي موعد).', examples: [LessonExample('doktor', 'طبيب'), LessonExample('hemşire', 'ممرض/ممرضة'), LessonExample('hastane', 'مستشفى'), LessonExample('klinik', 'عيادة'), LessonExample('randevu', 'موعد'), LessonExample('eczane', 'صيدلية')], question: 'ما معنى randevu؟', options: ['دواء', 'موعد', 'مستشفى', 'وصفة طعام'], answer: 1, feedback: 'randevu تعني موعداً.'),
    'a1-u10-6': LessonContent(goal: 'استخدام عبارات بسيطة عند التحدث مع الطبيب.', explanation: 'في حوار العيادة قد يسأل الطبيب Nereniz ağrıyor؟ (أين تشعر بالألم؟)، Ne zamandır؟ (منذ متى؟)، Nasıl hissediyorsunuz؟ (كيف تشعر؟). يمكن أن تجيب Başım ağrıyor (رأسي يؤلمني)، İki gündür (منذ يومين)، أو Kendimi yorgun hissediyorum (أشعر بالتعب).', examples: [LessonExample('Nereniz ağrıyor?', 'أين تشعر بالألم؟'), LessonExample('Başım ağrıyor.', 'رأسي يؤلمني.'), LessonExample('Ne zamandır?', 'منذ متى؟'), LessonExample('Dünden beri.', 'منذ الأمس.')], question: 'ما معنى Ne zamandır؟', options: ['أين؟', 'منذ متى؟', 'كم السعر؟', 'من هذا؟'], answer: 1, feedback: 'Ne zamandır؟ تعني منذ متى؟'),
    'a1-u10-7': LessonContent(goal: 'فهم كلمات شائعة تتعلق بالأدوية والصيدلية دون الدخول في إرشادات علاجية.', explanation: 'في الصيدلية قد تسمع ilaç دواء، reçete وصفة طبية، eczacı صيدلي، kutu علبة، prospektüs نشرة الدواء، kullanım talimatı تعليمات الاستخدام. يمكنك السؤال Bu ilacın prospektüsü var mı؟ (هل توجد نشرة لهذا الدواء؟). اتبع تعليمات الطبيب أو الصيدلي بشأن أي دواء.', examples: [LessonExample('ilaç', 'دواء'), LessonExample('reçete', 'وصفة طبية'), LessonExample('eczacı', 'صيدلي'), LessonExample('prospektüs', 'نشرة الدواء'), LessonExample('Eczane nerede?', 'أين الصيدلية؟')], question: 'ما معنى reçete؟', options: ['وصفة طبية', 'موعد', 'مستشفى', 'ممرض'], answer: 0, feedback: 'reçete تعني وصفة طبية.'),
    'a1-u10-8': LessonContent(goal: 'إجراء حوار تعليمي قصير في عيادة أو صيدلية.', explanation: 'اقرأ الحوار ولاحظ كيف يصف الشخص ما يشعر به، وكيف يسأل عن الموعد. عند عدم فهم السؤال يمكنك طلب إعادته بقول Tekrar eder misiniz؟ (هل يمكنكم الإعادة؟). تعلّم العبارات لفهم المحادثة والتواصل بوضوح.', examples: [LessonExample('Hasta: Merhaba, randevum var.', 'المريض: مرحباً، لدي موعد.'), LessonExample('Görevli: Adınız nedir?', 'الموظف: ما اسمك؟'), LessonExample('Hasta: Başım ağrıyor.', 'المريض: رأسي يؤلمني.'), LessonExample('Doktor: Ne zamandır?', 'الطبيب: منذ متى؟')], question: 'ماذا تعني Adınız nedir؟', options: ['ما اسمك؟ بصيغة مهذبة', 'أين المستشفى؟', 'هل أنت بخير؟', 'كم عمرك؟'], answer: 0, feedback: 'Adınız nedir؟ تعني ما اسمك؟ بصيغة مهذبة.'),
    'a1-u10-9': LessonContent(goal: 'مراجعة أجزاء الجسم ومفردات الصحة والعيادة والصيدلية.', explanation: 'راجع أسماء خمسة أجزاء من الجسم، وثلاث عبارات لوصف الشعور أو الألم، وأسماء ثلاثة أماكن أو أشخاص في المجال الطبي. ثم اكتب حواراً قصيراً من أربعة أسطر تستخدم فيه randevu وdoktor وBaşım ağrıyor.', examples: [LessonExample('Gözüm ağrıyor.', 'عيني تؤلمني.'), LessonExample('Doktordan randevum var.', 'لدي موعد مع الطبيب.'), LessonExample('Eczane nerede?', 'أين الصيدلية؟')], question: 'اختر العبارة التي تعني «لدي موعد».', options: ['Randevum var.', 'Başım ağrıyor.', 'Eczane nerede?', 'İyiyim.'], answer: 0, feedback: 'Randevum var تعني لدي موعد.'),

    'a1-u11-1': LessonContent(goal: 'التعرّف إلى أسماء الأطعمة الأساسية باللغة التركية.', explanation: 'ابدأ بمفردات الطعام الشائعة: ekmek خبز، peynir جبن، zeytin زيتون، yumurta بيضة، et لحم، tavuk دجاج، balık سمك، pilav أرز مطبوخ، çorba حساء، salata سلطة، sebze خضار، meyve فاكهة. كلمة yemek تعني طعاماً أو وجبة بحسب السياق.', examples: [LessonExample('ekmek', 'خبز'), LessonExample('peynir', 'جبن'), LessonExample('yumurta', 'بيضة'), LessonExample('çorba', 'حساء'), LessonExample('meyve', 'فاكهة')], question: 'ما معنى peynir؟', options: ['خبز', 'جبن', 'سمك', 'أرز'], answer: 1, feedback: 'peynir تعني جبن.'),
    'a1-u11-2': LessonContent(goal: 'تسمية المشروبات وطلبها بطريقة بسيطة.', explanation: 'من المشروبات içecek مشروب، su ماء، çay شاي، kahve قهوة، süt حليب، meyve suyu عصير فواكه، ayran شراب الزبادي، limonata ليمونادة. للسؤال عمّا يرغب به الشخص قل Ne içersiniz؟ (ماذا تشرب؟ بصيغة مهذبة)، ويمكنك قول Bir çay lütfen (شاي واحد من فضلك).', examples: [LessonExample('su', 'ماء'), LessonExample('çay', 'شاي'), LessonExample('kahve', 'قهوة'), LessonExample('süt', 'حليب'), LessonExample('ayran', 'شراب الزبادي')], question: 'ما معنى süt؟', options: ['قهوة', 'حليب', 'ماء', 'عصير'], answer: 1, feedback: 'süt تعني حليب.'),
    'a1-u11-3': LessonContent(goal: 'التعرّف إلى أسماء الوجبات وأوقات تناول الطعام.', explanation: 'وجبات اليوم: kahvaltı فطور، öğle yemeği غداء، akşam yemeği عشاء، ara öğün وجبة خفيفة. كلمة aç تعني جائع، tok تعني شبعان. يمكنك قول Kahvaltı yapıyorum (أتناول الفطور)، أو Çok açım (أنا جائع جداً).', examples: [LessonExample('kahvaltı', 'الفطور'), LessonExample('öğle yemeği', 'الغداء'), LessonExample('akşam yemeği', 'العشاء'), LessonExample('Çok açım.', 'أنا جائع جداً.'), LessonExample('Tokum, teşekkürler.', 'أنا شبعان، شكراً.')], question: 'ما معنى kahvaltı؟', options: ['العشاء', 'الفطور', 'الغداء', 'الحلوى'], answer: 1, feedback: 'kahvaltı تعني الفطور.'),
    'a1-u11-4': LessonContent(goal: 'التعبير عن الرغبة والتفضيل في الطعام والشراب.', explanation: 'للتعبير عن الرغبة استخدم istiyorum (أريد)، وللتفضيل أحب قل seviyorum، ولا أحب sevmiyorum. أمثلة: Çay istiyorum (أريد شايًا)، Balık seviyorum (أحب السمك)، Soğan sevmiyorum (لا أحب البصل). ويمكنك السؤال Ne tercih edersiniz؟ (ماذا تفضّل؟ بصيغة مهذبة).', examples: [LessonExample('Su istiyorum.', 'أريد ماءً.'), LessonExample('Kahve seviyorum.', 'أحب القهوة.'), LessonExample('Balık sevmiyorum.', 'لا أحب السمك.'), LessonExample('Ne tercih edersiniz?', 'ماذا تفضّل؟')], question: 'ما معنى istiyorum؟', options: ['لا أريد', 'أريد', 'أحب', 'أشرب'], answer: 1, feedback: 'istiyorum تعني أريد.'),
    'a1-u11-5': LessonContent(goal: 'فهم كلمات أساسية في قائمة الطعام والمطعم.', explanation: 'في المطعم ستجد menü قائمة الطعام، restoran مطعم، masa طاولة، garson نادل، sipariş طلب، hesap فاتورة، tatlı حلوى، ana yemek طبق رئيسي، başlangıç مقبلات. عبارة Menü alabilir miyim؟ تعني هل يمكنني الحصول على قائمة الطعام؟.', examples: [LessonExample('menü', 'قائمة الطعام'), LessonExample('garson', 'نادل'), LessonExample('sipariş', 'طلب'), LessonExample('hesap', 'فاتورة'), LessonExample('tatlı', 'حلوى')], question: 'ما معنى hesap في المطعم؟', options: ['قائمة الطعام', 'الفاتورة', 'الطاولة', 'المطبخ'], answer: 1, feedback: 'hesap تعني الفاتورة أو الحساب.'),
    'a1-u11-6': LessonContent(goal: 'طلب الطعام والشراب بأدب في المطعم.', explanation: 'يمكنك بدء الطلب بقول Bir çorba istiyorum (أريد حساءً)، أو Şundan alabilir miyim؟ (هل يمكنني أخذ هذا؟). كلمة lütfen تعني من فضلك، وbir porsiyon تعني حصة واحدة. ولطلب الماء قل Bir şişe su lütfen (زجاجة ماء واحدة من فضلك).', examples: [LessonExample('Menüyü alabilir miyim?', 'هل يمكنني الحصول على قائمة الطعام؟'), LessonExample('Bir çorba lütfen.', 'حساء واحد من فضلك.'), LessonExample('Bir porsiyon pilav istiyorum.', 'أريد حصة من الأرز.'), LessonExample('Su alabilir miyim?', 'هل يمكنني الحصول على ماء؟')], question: 'أي عبارة تعني «الفاتورة من فضلك»؟', options: ['Hesap lütfen.', 'Menü lütfen.', 'Su lütfen.', 'Günaydın.'], answer: 0, feedback: 'Hesap lütfen تعني الفاتورة من فضلك.'),
    'a1-u11-7': LessonContent(goal: 'السؤال عن مكونات الطعام والتعبير عن الكمية.', explanation: 'كلمات مفيدة: içinde داخل أو يحتوي على، tuz ملح، şeker سكر، süt حليب، et لحم، biraz قليلاً، çok كثيراً، az قليل. يمكنك السؤال İçinde ne var؟ (ماذا يوجد بداخله؟)، أو Şekersiz olabilir mi؟ (هل يمكن أن يكون من دون سكر؟).', examples: [LessonExample('İçinde ne var?', 'ماذا يوجد بداخله؟'), LessonExample('Biraz tuz.', 'قليل من الملح.'), LessonExample('Şekersiz kahve.', 'قهوة من دون سكر.'), LessonExample('Az şeker lütfen.', 'قليل من السكر من فضلك.')], question: 'ما معنى içinde؟', options: ['بجانب', 'داخل', 'فوق', 'بعيد'], answer: 1, feedback: 'içinde تعني داخل أو يحتوي على بحسب الجملة.'),
    'a1-u11-8': LessonContent(goal: 'فهم حوار قصير في مطعم من الجلوس حتى طلب الفاتورة.', explanation: 'اقرأ الحوار ولاحظ ترتيب المحادثة: الترحيب، اختيار الطاولة، طلب قائمة الطعام، اختيار الوجبة، ثم طلب الحساب. عبارات مهمة: Buyurun (تفضل)، Ne alırsınız؟ (ماذا تطلب؟)، Afiyet olsun (صحة وعافية)، Hesap lütfen (الفاتورة من فضلك).', examples: [LessonExample('Garson: Hoş geldiniz.', 'النادل: أهلاً وسهلاً.'), LessonExample('Müşteri: Bir masa alabilir miyiz?', 'الزبون: هل يمكننا الحصول على طاولة؟'), LessonExample('Garson: Ne alırsınız?', 'النادل: ماذا تطلبون؟'), LessonExample('Müşteri: Bir çorba ve su lütfen.', 'الزبون: حساء وماء من فضلك.'), LessonExample('Garson: Afiyet olsun.', 'النادل: صحة وعافية.')], question: 'ما العبارة التركية التي تقال بمعنى «صحة وعافية»؟', options: ['Afiyet olsun.', 'Güle güle.', 'İyi geceler.', 'Geçmiş olsun.'], answer: 0, feedback: 'Afiyet olsun تقال عند تقديم الطعام أو تمني وجبة شهية.'),
    'a1-u11-9': LessonContent(goal: 'مراجعة الأطعمة والمشروبات والوجبات والطلب في المطعم.', explanation: 'راجع أسماء خمسة أطعمة وثلاثة مشروبات، وميّز بين kahvaltı وöğle yemeği وakşam yemeği. ثم اكتب حواراً قصيراً في مطعم تستخدم فيه menü وsipariş وhesap، وعبّر عن طعام تحبه وآخر لا تفضله.', examples: [LessonExample('Bir çay ve bir tost lütfen.', 'شاي وشطيرة توست من فضلك.'), LessonExample('Balık seviyorum.', 'أحب السمك.'), LessonExample('Hesap lütfen.', 'الفاتورة من فضلك.')], question: 'اختر العبارة الصحيحة لمعنى «أريد ماءً».', options: ['Su istiyorum.', 'Su nerede?', 'Su sevmiyorum.', 'Hesap istiyorum.'], answer: 0, feedback: 'Su istiyorum تعني أريد ماءً.'),

    'a1-u12-1': LessonContent(goal: 'السؤال عن الوقت وقراءة الساعة باللغة التركية.', explanation: 'كلمة saat تعني ساعة أو وقت. للسؤال قل Saat kaç؟ (كم الساعة؟). للساعة الكاملة قل Saat üç (الثالثة)، وللنصف Saat üç buçuk (الثالثة والنصف). وتستخدم geçiyor للدقائق بعد الساعة، مثل Saat üçü çeyrek geçiyor (الثالثة والربع).', examples: [LessonExample('Saat kaç?', 'كم الساعة؟'), LessonExample('Saat iki.', 'الساعة الثانية.'), LessonExample('Saat iki buçuk.', 'الثانية والنصف.'), LessonExample('Saat üçü çeyrek geçiyor.', 'الثالثة والربع.')], question: 'ما معنى Saat kaç؟', options: ['ما اليوم؟', 'كم الساعة؟', 'كم السعر؟', 'أين المكان؟'], answer: 1, feedback: 'Saat kaç؟ هو السؤال عن الوقت.'),
    'a1-u12-2': LessonContent(goal: 'حفظ أيام الأسبوع والتحدث عن الأيام.', explanation: 'أيام الأسبوع: pazartesi الاثنين، salı الثلاثاء، çarşamba الأربعاء، perşembe الخميس، cuma الجمعة، cumartesi السبت، pazar الأحد. bugün اليوم، dün أمس، yarın غداً. مثال: Bugün pazartesi (اليوم الاثنين)، Yarın cuma (غداً الجمعة).', examples: [LessonExample('Bugün pazartesi.', 'اليوم الاثنين.'), LessonExample('Yarın salı.', 'غداً الثلاثاء.'), LessonExample('Dün pazardı.', 'كان أمس الأحد.'), LessonExample('Hafta sonu', 'نهاية الأسبوع')], question: 'ما معنى yarın؟', options: ['أمس', 'اليوم', 'غداً', 'الأسبوع'], answer: 2, feedback: 'yarın تعني غداً.'),
    'a1-u12-3': LessonContent(goal: 'التعرّف إلى أسماء الأشهر والتعبير عن التاريخ.', explanation: 'الأشهر: ocak يناير، şubat فبراير، mart مارس، nisan أبريل، mayıs مايو، haziran يونيو، temmuz يوليو، ağustos أغسطس، eylül سبتمبر، ekim أكتوبر، kasım نوفمبر، aralık ديسمبر. للسؤال عن التاريخ قل Bugün ayın kaçı؟ (ما تاريخ اليوم؟).', examples: [LessonExample('ocak', 'يناير'), LessonExample('nisan', 'أبريل'), LessonExample('ağustos', 'أغسطس'), LessonExample('ekim', 'أكتوبر'), LessonExample('Bugün ayın kaçı?', 'ما تاريخ اليوم؟')], question: 'أي شهر يعني eylül؟', options: ['يونيو', 'سبتمبر', 'أكتوبر', 'ديسمبر'], answer: 1, feedback: 'eylül تعني سبتمبر.'),
    'a1-u12-4': LessonContent(goal: 'تسمية الفصول ووصف الطقس بصورة أولية.', explanation: 'الفصول: ilkbahar الربيع، yaz الصيف، sonbahar الخريف، kış الشتاء. من مفردات الطقس hava durumu حالة الطقس، güneşli مشمس، bulutlu غائم، yağmurlu ممطر، karlı مثلج، rüzgârlı كثير الرياح. مثال: Yazın hava sıcak (الجو حار في الصيف).', examples: [LessonExample('ilkbahar', 'الربيع'), LessonExample('yaz', 'الصيف'), LessonExample('sonbahar', 'الخريف'), LessonExample('kış', 'الشتاء'), LessonExample('Bugün hava güneşli.', 'الجو مشمس اليوم.')], question: 'ما معنى kış؟', options: ['الربيع', 'الصيف', 'الخريف', 'الشتاء'], answer: 3, feedback: 'kış تعني الشتاء.'),
    'a1-u12-5': LessonContent(goal: 'وصف حالة الطقس ودرجة الحرارة بجمل بسيطة.', explanation: 'للسؤال عن الطقس قل Bugün hava nasıl؟ (كيف الطقس اليوم؟). كلمات مفيدة: sıcak حار، soğuk بارد، serin معتدل البرودة، ılık دافئ، açık صافٍ، kapalı ملبد بالغيوم، yağmur مطر، kar ثلج، rüzgâr رياح. مثال: Bugün hava soğuk (الجو بارد اليوم)، Hava ılık ve güneşli (الجو دافئ ومشمس).', examples: [LessonExample('Hava nasıl?', 'كيف الطقس؟'), LessonExample('Hava çok sıcak.', 'الجو حار جداً.'), LessonExample('Bugün yağmurlu.', 'الجو ممطر اليوم.'), LessonExample('Hava serin.', 'الجو معتدل البرودة.')], question: 'ما معنى bulutlu؟', options: ['مشمس', 'غائم', 'مثلج', 'حار'], answer: 1, feedback: 'bulutlu تعني غائم.'),
    'a1-u12-6': LessonContent(goal: 'التحدث عن المواعيد والخطط باستخدام اليوم والوقت.', explanation: 'كلمات مهمة: randevu موعد، toplantı اجتماع، ders درس، bugün اليوم، yarın غداً، sabah صباحاً، öğleden sonra بعد الظهر، akşam مساءً. للسؤال عن موعد قل Saat kaçta؟ (في أي ساعة؟). مثال: Yarın saat onda dersim var (لدي درس غداً الساعة العاشرة).', examples: [LessonExample('Saat kaçta?', 'في أي ساعة؟'), LessonExample('Sabah dokuzda.', 'في التاسعة صباحاً.'), LessonExample('Yarın toplantım var.', 'لدي اجتماع غداً.'), LessonExample('Akşam görüşürüz.', 'نلتقي مساءً.')], question: 'ما معنى sabah؟', options: ['مساءً', 'صباحاً', 'أمس', 'شتاءً'], answer: 1, feedback: 'sabah تعني صباحاً.'),
    'a1-u12-7': LessonContent(goal: 'استخدام ظروف التكرار والتعبير عن الروتين الأسبوعي.', explanation: 'ظروف التكرار: her gün كل يوم، her hafta كل أسبوع، bazen أحياناً، sık sık كثيراً، nadiren نادراً. أمثلة: Her gün çalışıyorum (أعمل كل يوم)، Bazen yürüyüş yapıyorum (أتمشى أحياناً)، Hafta sonu dinleniyorum (أستريح في نهاية الأسبوع).', examples: [LessonExample('her gün', 'كل يوم'), LessonExample('her hafta', 'كل أسبوع'), LessonExample('bazen', 'أحياناً'), LessonExample('sık sık', 'كثيراً'), LessonExample('nadiren', 'نادراً')], question: 'ما معنى bazen؟', options: ['دائماً', 'أحياناً', 'أبداً', 'غداً'], answer: 1, feedback: 'bazen تعني أحياناً.'),
    'a1-u12-8': LessonContent(goal: 'فهم حوار قصير يجمع الوقت والتاريخ والطقس والموعد.', explanation: 'لاحظ كيف يسأل المتحدث عن الطقس ثم يحدد موعداً. ركّز على yarın (غداً)، saat üçte (في الساعة الثالثة)، güneşli (مشمس)، وbuluşalım (لنلتقِ). يمكنك اقتراح موعد بقول Saat üçte buluşalım mı؟ (هل نلتقي الساعة الثالثة؟).', examples: [LessonExample('A: Yarın hava nasıl?', 'أ: كيف سيكون الطقس غداً؟'), LessonExample('B: Güneşli olacak.', 'ب: سيكون مشمساً.'), LessonExample('A: Saat üçte buluşalım mı?', 'أ: هل نلتقي الساعة الثالثة؟'), LessonExample('B: Evet, görüşürüz.', 'ب: نعم، أراك لاحقاً.')], question: 'ما معنى Saat üçte buluşalım mı؟', options: ['هل نلتقي الساعة الثالثة؟', 'كم الساعة الآن؟', 'هل الجو بارد؟', 'ما تاريخ اليوم؟'], answer: 0, feedback: 'العبارة تقترح اللقاء في الساعة الثالثة.'),
    'a1-u12-9': LessonContent(goal: 'مراجعة الوقت وأيام الأسبوع والأشهر والفصول والطقس والمواعيد.', explanation: 'راجع أيام الأسبوع وأشهر السنة، ثم صف الطقس في فصلين مختلفين. اكتب ثلاث جمل عن برنامجك: ماذا تفعل اليوم، وماذا ستفعل غداً، وفي أي ساعة لديك موعد. استخدم bugün وyarın وsaat kaçta وhava nasıl.', examples: [LessonExample('Bugün salı.', 'اليوم الثلاثاء.'), LessonExample('Kışın hava soğuk.', 'الجو بارد في الشتاء.'), LessonExample('Yarın saat beşte görüşelim.', 'لنلتقِ غداً الساعة الخامسة.')], question: 'اختر العبارة التي تعني «غداً الساعة الخامسة».', options: ['Dün saat beşte.', 'Yarın saat beşte.', 'Bugün hava soğuk.', 'Her hafta cuma.'], answer: 1, feedback: 'Yarın saat beşte تعني غداً الساعة الخامسة.'),

    'a1-u13-1': LessonContent(goal: 'التعرّف إلى أسماء غرف المنزل وأجزائه باللغة التركية.', explanation: 'كلمة ev تعني منزل. من الغرف: oda غرفة، oturma odası غرفة الجلوس، yatak odası غرفة النوم، mutfak مطبخ، banyo حمّام، salon صالة، balkon شرفة، bahçe حديقة، koridor ممر. للسؤال عن مكان شيء قل Nerede؟ (أين؟)، ولوصف المنزل قل Evim büyük (منزلي كبير).', examples: [LessonExample('ev', 'منزل'), LessonExample('oda', 'غرفة'), LessonExample('mutfak', 'مطبخ'), LessonExample('banyo', 'حمّام'), LessonExample('balkon', 'شرفة')], question: 'ما معنى mutfak؟', options: ['غرفة النوم', 'مطبخ', 'شرفة', 'حديقة'], answer: 1, feedback: 'mutfak تعني مطبخ.'),
    'a1-u13-2': LessonContent(goal: 'تسمية قطع الأثاث والأشياء الموجودة في المنزل.', explanation: 'أثاث المنزل: masa طاولة، sandalye كرسي، koltuk أريكة، yatak سرير، dolap خزانة، kitaplık مكتبة كتب، halı سجادة، lamba مصباح، ayna مرآة، perde ستارة. لاحظ أن بعض الكلمات يمكن أن تشير إلى قطعة الأثاث أو الشيء بحسب السياق.', examples: [LessonExample('masa', 'طاولة'), LessonExample('sandalye', 'كرسي'), LessonExample('koltuk', 'أريكة'), LessonExample('yatak', 'سرير'), LessonExample('ayna', 'مرآة')], question: 'ما معنى sandalye؟', options: ['كرسي', 'سرير', 'خزانة', 'مصباح'], answer: 0, feedback: 'sandalye تعني كرسي.'),
    'a1-u13-3': LessonContent(goal: 'التعرّف إلى الأدوات المنزلية وأغراض المطبخ.', explanation: 'من أدوات المطبخ: tabak طبق، bardak كأس، fincan فنجان، kaşık ملعقة، çatal شوكة، bıçak سكين مائدة، tencere قدر، tava مقلاة، buzdolabı ثلاجة، fırın فرن. كلمة mutfak eşyaları تعني أدوات المطبخ. اربط كل كلمة باستخدامها اليومي لتسهيل حفظها.', examples: [LessonExample('tabak', 'طبق'), LessonExample('bardak', 'كأس'), LessonExample('kaşık', 'ملعقة'), LessonExample('çatal', 'شوكة'), LessonExample('buzdolabı', 'ثلاجة')], question: 'ما معنى buzdolabı؟', options: ['فرن', 'ثلاجة', 'مقلاة', 'قدر'], answer: 1, feedback: 'buzdolabı تعني ثلاجة.'),
    'a1-u13-4': LessonContent(goal: 'وصف المنزل والغرف باستخدام الصفات الأساسية.', explanation: 'صفات مفيدة: büyük كبير، küçük صغير، geniş واسع، dar ضيق، temiz نظيف، kirli متسخ، yeni جديد، eski قديم، güzel جميل، rahat مريح. ضع الصفة عادة قبل الاسم: büyük ev (منزل كبير)، temiz oda (غرفة نظيفة). وفي الجملة: Evim çok güzel (منزلي جميل جداً).', examples: [LessonExample('büyük ev', 'منزل كبير'), LessonExample('küçük oda', 'غرفة صغيرة'), LessonExample('temiz mutfak', 'مطبخ نظيف'), LessonExample('rahat koltuk', 'أريكة مريحة'), LessonExample('Evim güzel.', 'منزلي جميل.')], question: 'ما معنى geniş؟', options: ['قديم', 'واسع', 'متسخ', 'صغير'], answer: 1, feedback: 'geniş تعني واسع.'),
    'a1-u13-5': LessonContent(goal: 'تحديد مواقع الأشياء والأثاث داخل المنزل.', explanation: 'للمكان استخدم: içinde داخل، üstünde فوق أو على، altında تحت، yanında بجانب، önünde أمام، arkasında خلف، karşısında مقابل. أمثلة: Kitap masanın üstünde (الكتاب على الطاولة)، Çanta sandalyenin yanında (الحقيبة بجانب الكرسي). السؤال Nerede؟ يعني أين؟.', examples: [LessonExample('masanın üstünde', 'على الطاولة'), LessonExample('yatağın altında', 'تحت السرير'), LessonExample('kapının yanında', 'بجانب الباب'), LessonExample('Evin önünde', 'أمام المنزل')], question: 'ما معنى altında؟', options: ['فوق', 'تحت', 'بجانب', 'أمام'], answer: 1, feedback: 'altında تعني تحت.'),
    'a1-u13-6': LessonContent(goal: 'التحدث عن الأعمال المنزلية والروتين اليومي في البيت.', explanation: 'أفعال منزلية شائعة: temizlemek ينظّف، yıkamak يغسل، pişirmek يطبخ، toplamak يرتّب أو يجمع، süpürmek يكنس، ütü yapmak يكوي، çamaşır yıkamak يغسل الملابس، bulaşık yıkamak يغسل الصحون. مثال: Evi temizliyorum (أنظف المنزل)، Yemek pişiriyorum (أطبخ الطعام).', examples: [LessonExample('Evi temizliyorum.', 'أنظف المنزل.'), LessonExample('Yemek pişiriyorum.', 'أطبخ الطعام.'), LessonExample('Bulaşıkları yıkıyorum.', 'أغسل الصحون.'), LessonExample('Odayı topluyorum.', 'أرتّب الغرفة.')], question: 'ما معنى yemek pişirmek؟', options: ['غسل الملابس', 'طبخ الطعام', 'كنس الأرض', 'ترتيب السرير'], answer: 1, feedback: 'yemek pişirmek تعني طبخ الطعام.'),
    'a1-u13-7': LessonContent(goal: 'السؤال عن المنزل ومحتوياته والإجابة بجمل بسيطة.', explanation: 'أسئلة مفيدة: Evin kaç odası var؟ (كم غرفة في منزلك؟)، Evinde balkon var mı؟ (هل يوجد شرفة في منزلك؟)، Bu ne؟ (ما هذا؟)، Nerede؟ (أين؟). استخدم var للتعبير عن وجود شيء، وyok للتعبير عن عدم وجوده: Evimde balkon var (في منزلي شرفة)، Bahçem yok (ليس لدي حديقة).', examples: [LessonExample('Evin kaç odası var?', 'كم غرفة في منزلك؟'), LessonExample('Balkon var mı?', 'هل توجد شرفة؟'), LessonExample('Evimde iki oda var.', 'في منزلي غرفتان.'), LessonExample('Bahçem yok.', 'ليس لدي حديقة.')], question: 'ما معنى yok؟', options: ['موجود', 'غير موجود', 'كبير', 'جميل'], answer: 1, feedback: 'yok تعني غير موجود أو لا يوجد.'),
    'a1-u13-8': LessonContent(goal: 'فهم حوار بسيط عن المنزل ووصف غرفة ومكان الأثاث.', explanation: 'في هذا الحوار يصف شخص منزله ويشرح مكان الأثاث. انتبه إلى أسماء الغرف والأثاث وحروف المكان: üstünde على، yanında بجانب، içinde داخل. حاول بعد القراءة أن تصف غرفتك بثلاث جمل قصيرة.', examples: [LessonExample('A: Evin nasıl?', 'أ: كيف منزلك؟'), LessonExample('B: Küçük ama güzel.', 'ب: صغير لكنه جميل.'), LessonExample('A: Oturma odasında ne var?', 'أ: ماذا يوجد في غرفة الجلوس؟'), LessonExample('B: Bir koltuk ve bir masa var.', 'ب: توجد أريكة وطاولة.'), LessonExample('A: Kitaplar nerede?', 'أ: أين الكتب؟'), LessonExample('B: Kitaplar rafta.', 'ب: الكتب على الرف.')], question: 'ما معنى Oturma odasında ne var؟', options: ['كم سعر المنزل؟', 'ماذا يوجد في غرفة الجلوس؟', 'أين المطبخ؟', 'هل المنزل جديد؟'], answer: 1, feedback: 'السؤال يعني ماذا يوجد في غرفة الجلوس؟'),
    'a1-u13-9': LessonContent(goal: 'مراجعة غرف المنزل والأثاث والأدوات والمواقع والأعمال المنزلية.', explanation: 'راجع أسماء خمس غرف وخمس قطع أثاث، ثم صف منزلاً باستخدام صفتين على الأقل. اكتب ثلاث جمل تحدد فيها مكان الأشياء مستخدماً üstünde وaltında وyanında، وجملتين عن الأعمال المنزلية. اختم بوصف منزلك أو غرفة تتخيلها.', examples: [LessonExample('Ev büyük ve temiz.', 'المنزل كبير ونظيف.'), LessonExample('Kitap masanın üstünde.', 'الكتاب على الطاولة.'), LessonExample('Her gün odamı topluyorum.', 'أرتب غرفتي كل يوم.')], question: 'اختر العبارة التي تعني «الكتاب تحت الطاولة».', options: ['Kitap masanın üstünde.', 'Kitap masanın altında.', 'Kitap odada.', 'Kitap masanın yanında.'], answer: 1, feedback: 'altında تعني تحت، لذا Kitap masanın altında تعني الكتاب تحت الطاولة.'),

    'a1-u14-1': LessonContent(goal: 'التعرّف إلى الأماكن العامة والخدمات الموجودة في المدينة.', explanation: 'كلمة şehir تعني مدينة. من الأماكن المهمة: hastane مستشفى، okul مدرسة، üniversite جامعة، banka بنك، postane مكتب بريد، market متجر، eczane صيدلية، park حديقة عامة، müze متحف، kütüphane مكتبة، belediye بلدية، polis merkezi مركز شرطة. للسؤال عن المكان قل Nerede؟ (أين؟).', examples: [LessonExample('hastane', 'مستشفى'), LessonExample('okul', 'مدرسة'), LessonExample('banka', 'بنك'), LessonExample('eczane', 'صيدلية'), LessonExample('kütüphane', 'مكتبة')], question: 'ما معنى hastane؟', options: ['مدرسة', 'مستشفى', 'بنك', 'حديقة'], answer: 1, feedback: 'hastane تعني مستشفى.'),
    'a1-u14-2': LessonContent(goal: 'تسمية وسائل النقل وطرق التنقل داخل المدينة.', explanation: 'وسائل النقل: otobüs حافلة، metro مترو، tramvay ترام، tren قطار، taksi سيارة أجرة، araba سيارة، bisiklet دراجة، vapur عبّارة، uçak طائرة، yürüyerek سيراً على الأقدام. الفعل binmek يعني ركوب وسيلة نقل، وinmek يعني النزول منها. مثال: Otobüse biniyorum (أركب الحافلة).', examples: [LessonExample('otobüs', 'حافلة'), LessonExample('metro', 'مترو'), LessonExample('tren', 'قطار'), LessonExample('taksi', 'سيارة أجرة'), LessonExample('bisiklet', 'دراجة')], question: 'ما معنى tren؟', options: ['قطار', 'طائرة', 'حافلة', 'دراجة'], answer: 0, feedback: 'tren تعني قطار.'),
    'a1-u14-3': LessonContent(goal: 'فهم كلمات الاتجاهات وتحديد موقع مكان في المدينة.', explanation: 'الاتجاهات: sağ يمين، sol يسار، düz إلى الأمام، geri إلى الخلف، kuzey شمال، güney جنوب، doğu شرق، batı غرب. كلمات الموقع: yakın قريب، uzak بعيد، karşı مقابل، yanında بجانب. مثال: Sağa dön (انعطف يميناً)، Düz gidin (تابع إلى الأمام بصيغة مهذبة).', examples: [LessonExample('sağ', 'يمين'), LessonExample('sol', 'يسار'), LessonExample('düz', 'إلى الأمام'), LessonExample('yakın', 'قريب'), LessonExample('uzak', 'بعيد')], question: 'ما معنى sola؟', options: ['إلى اليمين', 'إلى اليسار', 'إلى الأمام', 'إلى الخلف'], answer: 1, feedback: 'sola تعني إلى اليسار.'),
    'a1-u14-4': LessonContent(goal: 'السؤال عن الطريق وشرح مسار بسيط للوصول إلى مكان.', explanation: 'للسؤال قل ... nasıl gidebilirim؟ أي كيف أصل إلى ...؟ مثل Hastaneye nasıl gidebilirim؟ (كيف أصل إلى المستشفى؟). للإرشاد استخدم: Sağa dönün انعطف يميناً، Sola dönün انعطف يساراً، Düz gidin تابع إلى الأمام، İlk sokaktan dönün انعطف من أول شارع. كلمة sokak تعني شارعاً صغيراً، وcadde تعني شارعاً رئيسياً.', examples: [LessonExample('Buraya nasıl gidebilirim?', 'كيف أصل إلى هنا؟'), LessonExample('Sağa dönün.', 'انعطف يميناً.'), LessonExample('Düz gidin.', 'تابع إلى الأمام.'), LessonExample('İlk sokaktan dönün.', 'انعطف من أول شارع.')], question: 'ما معنى Düz gidin؟', options: ['انعطف يميناً', 'تابع إلى الأمام', 'ارجع للخلف', 'توقف هنا'], answer: 1, feedback: 'Düz gidin تعني تابع إلى الأمام.'),
    'a1-u14-5': LessonContent(goal: 'التعرّف إلى محطات النقل وأماكن شراء التذاكر.', explanation: 'مفردات مهمة: durak موقف، otogar محطة حافلات بين المدن، istasyon محطة قطار، havaalanı مطار، bilet تذكرة، gişe شباك التذاكر، peron رصيف أو منصة، sefer رحلة أو خدمة، kalkış مغادرة، varış وصول. للسؤال عن التذكرة قل Bir bilet lütfen (تذكرة واحدة من فضلك).', examples: [LessonExample('durak', 'موقف'), LessonExample('istasyon', 'محطة'), LessonExample('havaalanı', 'مطار'), LessonExample('bilet', 'تذكرة'), LessonExample('gişe', 'شباك التذاكر')], question: 'ما معنى bilet؟', options: ['موقف', 'تذكرة', 'مطار', 'رصيف'], answer: 1, feedback: 'bilet تعني تذكرة.'),
    'a1-u14-6': LessonContent(goal: 'السؤال عن الأسعار وشراء تذكرة مواصلات.', explanation: 'عبارات نافعة: Bilet ne kadar؟ (كم سعر التذكرة؟)، Bir öğrenci bileti lütfen (تذكرة طالب من فضلك)، Gidiş dönüş bilet istiyorum (أريد تذكرة ذهاب وعودة)، Saat kaçta kalkıyor؟ (متى تنطلق؟)، Hangi peron؟ (أي رصيف؟). كلمة ücret تعني الأجرة أو الرسوم، وtek yön تعني اتجاه واحد.', examples: [LessonExample('Bilet ne kadar?', 'كم سعر التذكرة؟'), LessonExample('Bir bilet lütfen.', 'تذكرة واحدة من فضلك.'), LessonExample('Saat kaçta kalkıyor?', 'متى تنطلق؟'), LessonExample('Hangi peron?', 'أي رصيف؟')], question: 'كيف تسأل عن سعر التذكرة؟', options: ['Bilet ne kadar?', 'Nerede yaşıyorsun?', 'Saat kaç?', 'Hava nasıl?'], answer: 0, feedback: 'Bilet ne kadar؟ تعني كم سعر التذكرة؟'),
    'a1-u14-7': LessonContent(goal: 'التحدث عن المسافة والمدة ووسيلة الوصول.', explanation: 'كلمات المسافة والوقت: dakika دقيقة، saat ساعة، kilometre كيلومتر، uzak بعيد، yakın قريب، yaklaşık تقريباً، yürüyerek سيراً على الأقدام. للسؤال قل Ne kadar sürer؟ (كم يستغرق؟)، أو Yürüyerek kaç dakika؟ (كم دقيقة مشياً؟). مثال: Beş dakika sürer (يستغرق خمس دقائق).', examples: [LessonExample('Beş dakika.', 'خمس دقائق.'), LessonExample('Ne kadar sürer?', 'كم يستغرق؟'), LessonExample('Çok uzak mı?', 'هل هو بعيد جداً؟'), LessonExample('Yürüyerek on dakika.', 'عشر دقائق سيراً.')], question: 'ما معنى dakika؟', options: ['ساعة', 'دقيقة', 'كيلومتر', 'تذكرة'], answer: 1, feedback: 'dakika تعني دقيقة.'),
    'a1-u14-8': LessonContent(goal: 'فهم حوار في المدينة يجمع السؤال عن الطريق وركوب المواصلات.', explanation: 'اقرأ الحوار ولاحظ كيف يسأل الزائر عن محطة المترو، ثم يحصل على إرشادات الطريق ويشتري تذكرة. ركّز على metro istasyonu محطة المترو، sağa dön انعطف يميناً، bilet تذكرة، وhangi durak أي موقف.', examples: [LessonExample('A: Metro istasyonu nerede?', 'أ: أين محطة المترو؟'), LessonExample('B: Düz gidin, sonra sağa dönün.', 'ب: تابع إلى الأمام ثم انعطف يميناً.'), LessonExample('A: Çok uzak mı?', 'أ: هل هي بعيدة؟'), LessonExample('B: Hayır, beş dakika yürüyerek.', 'ب: لا، خمس دقائق مشياً.'), LessonExample('A: Bir bilet lütfen.', 'أ: تذكرة واحدة من فضلك.')], question: 'ما معنى Çok uzak mı؟', options: ['هل هو بعيد؟', 'كم سعرها؟', 'أين المحطة؟', 'متى تنطلق؟'], answer: 0, feedback: 'Çok uzak mı؟ تعني هل هو بعيد جداً؟'),
    'a1-u14-9': LessonContent(goal: 'مراجعة الأماكن العامة والمواصلات والاتجاهات وشراء التذاكر.', explanation: 'راجع أسماء ستة أماكن عامة وخمس وسائل نقل. تدرب على إعطاء اتجاهات من ثلاثة أجزاء، ثم مثّل حواراً تسأل فيه عن محطة وتشتري تذكرة وتسأل عن وقت المغادرة. استخدم sağ، sol، düz، durak، bilet، وne kadar sürer.', examples: [LessonExample('Hastane nerede?', 'أين المستشفى؟'), LessonExample('Sola dönün.', 'انعطف يساراً.'), LessonExample('Bir metro bileti lütfen.', 'تذكرة مترو واحدة من فضلك.')], question: 'اختر العبارة التي تعني «انعطف يميناً».', options: ['Sola dönün.', 'Düz gidin.', 'Sağa dönün.', 'Geri dönün.'], answer: 2, feedback: 'Sağa dönün تعني انعطف يميناً.'),

    'a1-u15-1': LessonContent(goal: 'التعرّف إلى أسماء الملابس الأساسية باللغة التركية.', explanation: 'كلمة giysi تعني لباساً أو قطعة ملابس. من المفردات: gömlek قميص، tişört قميص قصير، pantolon بنطال، etek تنورة، elbise فستان، ceket سترة، mont معطف، ayakkabı حذاء، çorap جوارب، şapka قبعة. مثال: Bir gömlek arıyorum (أبحث عن قميص).', examples: [LessonExample('gömlek', 'قميص'), LessonExample('pantolon', 'بنطال'), LessonExample('elbise', 'فستان'), LessonExample('ceket', 'سترة'), LessonExample('ayakkabı', 'حذاء')], question: 'ما معنى ayakkabı؟', options: ['قبعة', 'حذاء', 'قميص', 'جوارب'], answer: 1, feedback: 'ayakkabı تعني حذاء.'),
    'a1-u15-2': LessonContent(goal: 'وصف الملابس باستخدام الألوان والصفات والمقاسات.', explanation: 'الألوان: kırmızı أحمر، mavi أزرق، yeşil أخضر، siyah أسود، beyaz أبيض، sarı أصفر، pembe وردي، gri رمادي. صفات ومقاسات: büyük كبير، küçük صغير، uzun طويل، kısa قصير، dar ضيق، bol واسع، pahalı غالٍ، ucuz رخيص. غالباً تأتي الصفة قبل الاسم: kırmızı elbise (فستان أحمر).', examples: [LessonExample('kırmızı elbise', 'فستان أحمر'), LessonExample('mavi gömlek', 'قميص أزرق'), LessonExample('siyah ayakkabı', 'حذاء أسود'), LessonExample('çok büyük', 'كبير جداً'), LessonExample('küçük beden', 'مقاس صغير')], question: 'ما معنى ucuz؟', options: ['غالٍ', 'رخيص', 'طويل', 'أحمر'], answer: 1, feedback: 'ucuz تعني رخيص.'),
    'a1-u15-3': LessonContent(goal: 'التعرّف إلى مفردات المتاجر والأقسام والمنتجات.', explanation: 'أماكن التسوق: mağaza متجر، dükkân محل، alışveriş merkezi مركز تسوق، market سوبرماركت، kasap محل جزارة، fırın مخبز. مفردات أخرى: ürün منتج، reyon قسم، deneme kabini غرفة قياس الملابس، beden مقاس، numara رقم المقاس، raf رف. مثال: Deneme kabini nerede؟ (أين غرفة القياس؟).', examples: [LessonExample('mağaza', 'متجر'), LessonExample('alışveriş merkezi', 'مركز تسوق'), LessonExample('ürün', 'منتج'), LessonExample('beden', 'مقاس'), LessonExample('deneme kabini', 'غرفة قياس الملابس')], question: 'ما معنى mağaza؟', options: ['محطة', 'متجر', 'مستشفى', 'مطبخ'], answer: 1, feedback: 'mağaza تعني متجر.'),
    'a1-u15-4': LessonContent(goal: 'السؤال عن السعر وفهم الأرقام والعملة عند الشراء.', explanation: 'للسؤال عن السعر قل Bu ne kadar؟ (كم سعر هذا؟) أو Fiyatı ne kadar؟ (كم سعره؟). العملة التركية lira وتعني ليرة، وkuruş قرش. أرقام مفيدة: on عشرة، yirmi عشرون، elli خمسون، yüz مئة، bin ألف. مثال: Elli lira (خمسون ليرة)، Çok pahalı (غالي جداً).', examples: [LessonExample('Bu ne kadar?', 'كم سعر هذا؟'), LessonExample('Fiyatı ne kadar?', 'كم سعره؟'), LessonExample('elli lira', 'خمسون ليرة'), LessonExample('çok pahalı', 'غالي جداً'), LessonExample('çok ucuz', 'رخيص جداً')], question: 'كيف تسأل «كم سعر هذا؟»؟', options: ['Bu nerede?', 'Bu ne kadar?', 'Saat kaç?', 'Ne zaman?'], answer: 1, feedback: 'Bu ne kadar؟ تعني كم سعر هذا؟'),
    'a1-u15-5': LessonContent(goal: 'طلب مقاس أو لون مختلف وتجربة الملابس في المتجر.', explanation: 'عبارات مهمة: Başka beden var mı؟ (هل يوجد مقاس آخر؟)، Daha büyük beden istiyorum (أريد مقاساً أكبر)، Başka renk var mı؟ (هل يوجد لون آخر؟)، Deneyebilir miyim؟ (هل يمكنني تجربته؟)، Bana küçük geldi (جاء صغيراً عليّ). كلمة denemek تعني التجربة أو القياس.', examples: [LessonExample('Başka beden var mı?', 'هل يوجد مقاس آخر؟'), LessonExample('Daha büyük beden istiyorum.', 'أريد مقاساً أكبر.'), LessonExample('Başka renk var mı?', 'هل يوجد لون آخر؟'), LessonExample('Deneyebilir miyim?', 'هل يمكنني تجربته؟')], question: 'ما معنى Deneyebilir miyim؟', options: ['كم سعره؟', 'هل يمكنني تجربته؟', 'أين المتجر؟', 'هل يوجد لون أزرق؟'], answer: 1, feedback: 'Deneyebilir miyim؟ تعني هل يمكنني تجربته؟'),
    'a1-u15-6': LessonContent(goal: 'التحدث مع البائع وطلب المساعدة بطريقة مهذبة.', explanation: 'يمكنك بدء الحديث بقول Merhaba, yardımcı olur musunuz؟ (مرحباً، هل تساعدني؟). ولطلب منتج قل Şu gömleği alabilir miyim؟ (هل يمكنني أخذ ذلك القميص؟). كلمات مفيدة: arıyorum أبحث عن، istiyorum أريد، beğendim أعجبني، uygun مناسب. استخدم lütfen بمعنى من فضلك وteşekkür ederim بمعنى شكراً.', examples: [LessonExample('Yardımcı olur musunuz?', 'هل يمكنكم مساعدتي؟'), LessonExample('Bir ceket arıyorum.', 'أبحث عن سترة.'), LessonExample('Bunu beğendim.', 'أعجبني هذا.'), LessonExample('Teşekkür ederim.', 'شكراً لك.')], question: 'ما معنى yardımcı olur musunuz؟', options: ['هل يمكنكم مساعدتي؟', 'كم الساعة؟', 'هل هو بعيد؟', 'أين المحطة؟'], answer: 0, feedback: 'العبارة طلب مهذب للمساعدة.'),
    'a1-u15-7': LessonContent(goal: 'فهم عبارات التخفيض والدفع وطرق التسديد.', explanation: 'مفردات الدفع: kasa صندوق المحاسبة، nakit نقداً، kredi kartı بطاقة ائتمان، banka kartı بطاقة مصرفية، fiş إيصال، indirim تخفيض، taksit أقساط. عبارات: Kartla ödeyebilir miyim؟ (هل يمكنني الدفع بالبطاقة؟)، İndirim var mı؟ (هل يوجد تخفيض؟)، Fiş alabilir miyim؟ (هل يمكنني أخذ الإيصال؟).', examples: [LessonExample('kasa', 'صندوق المحاسبة'), LessonExample('nakit', 'نقداً'), LessonExample('kredi kartı', 'بطاقة ائتمان'), LessonExample('indirim', 'تخفيض'), LessonExample('Fiş alabilir miyim?', 'هل يمكنني أخذ الإيصال؟')], question: 'ما معنى indirim؟', options: ['إيصال', 'تخفيض', 'بطاقة', 'مقاس'], answer: 1, feedback: 'indirim تعني تخفيض.'),
    'a1-u15-8': LessonContent(goal: 'فهم حوار متكامل في متجر للملابس من السؤال حتى الدفع.', explanation: 'اقرأ الحوار ولاحظ تسلسل التسوق: البحث عن قميص، السؤال عن السعر، طلب مقاس آخر، تجربة القطعة ثم الدفع. انتبه إلى arıyorum (أبحث)، ne kadar (كم السعر)، beden (المقاس)، deneyebilir miyim (هل يمكنني التجربة)، وkartla (بالبطاقة).', examples: [LessonExample('A: Merhaba, bir gömlek arıyorum.', 'أ: مرحباً، أبحث عن قميص.'), LessonExample('B: Hangi renk?', 'ب: أي لون؟'), LessonExample('A: Mavi olsun. Fiyatı ne kadar?', 'أ: ليكن أزرق. كم سعره؟'), LessonExample('B: Beş yüz lira.', 'ب: خمسمئة ليرة.'), LessonExample('A: Daha büyük beden var mı?', 'أ: هل يوجد مقاس أكبر؟'), LessonExample('B: Evet, buyurun.', 'ب: نعم، تفضل.'), LessonExample('A: Kartla ödeyeceğim, teşekkürler.', 'أ: سأدفع بالبطاقة، شكراً.')], question: 'ما معنى Daha büyük beden var mı؟', options: ['هل يوجد مقاس أكبر؟', 'هل يوجد تخفيض؟', 'كم سعر القميص؟', 'أين صندوق المحاسبة؟'], answer: 0, feedback: 'السؤال عن توفر مقاس أكبر.'),
    'a1-u15-9': LessonContent(goal: 'مراجعة الملابس والألوان والمقاسات والأسعار والشراء والدفع.', explanation: 'راجع أسماء عشر قطع ملابس وثمانية ألوان، ثم تدرب على السؤال عن السعر والمقاس والتخفيض. اكتب حواراً من ست جمل في متجر: ابدأ بالتحية، اذكر ما تبحث عنه، اسأل عن السعر، اطلب مقاساً أو لوناً آخر، ثم اختر طريقة الدفع واشكر البائع.', examples: [LessonExample('Siyah bir ceket istiyorum.', 'أريد سترة سوداء.'), LessonExample('Bu ne kadar?', 'كم سعر هذا؟'), LessonExample('Kartla ödeyeceğim.', 'سأدفع بالبطاقة.')], question: 'اختر العبارة التي تعني «هل يوجد تخفيض؟».', options: ['Başka beden var mı?', 'İndirim var mı?', 'Deneyebilir miyim?', 'Fiyatı ne kadar?'], answer: 1, feedback: 'İndirim var mı؟ تعني هل يوجد تخفيض؟'),
    'a1-u16-1': LessonContent(goal: 'أجزاء الجسم الأساسية باللغة التركية.', explanation: 'كلمة vücut تعني الجسم. مفردات: baş الرأس، saç الشعر، yüz الوجه، göz العين، kulak الأذن، burun الأنف، ağız الفم، diş السن، boyun الرقبة، omuz الكتف، kol الذراع، el اليد، parmak الإصبع، bacak الساق، ayak القدم.', examples: [LessonExample('baş', 'رأس'), LessonExample('göz', 'عين'), LessonExample('kulak', 'أذن'), LessonExample('el', 'يد'), LessonExample('ayak', 'قدم')], question: 'ما معنى göz؟', options: ['أذن', 'عين', 'يد', 'قدم'], answer: 1, feedback: 'göz تعني عين.'),
    'a1-u16-2': LessonContent(goal: 'وصف الجسم والحالة العامة باللغة التركية.', explanation: 'صفات شائعة: hasta مريض، sağlıklı بصحة جيدة، yorgun متعب، iyi جيد، kötü سيئ. للسؤال عن الحال نقول Nasılsın؟ (كيف حالك؟)، والرد İyiyim (أنا بخير) أو Biraz yorgunum (أنا متعب قليلاً).', examples: [LessonExample('Nasılsın?', 'كيف حالك؟'), LessonExample('İyiyim, teşekkürler.', 'أنا بخير، شكراً.'), LessonExample('Biraz yorgunum.', 'أنا متعب قليلاً.'), LessonExample('Kendimi iyi hissediyorum.', 'أشعر أنني بخير.')], question: 'ما معنى yorgun؟', options: ['سعيد', 'متعب', 'سريع', 'جديد'], answer: 1, feedback: 'yorgun تعني متعب.'),
    'a1-u16-3': LessonContent(goal: 'الأعراض الشائعة والتعبير عنها باللغة التركية.', explanation: 'مفردات لغوية عامة: ağrı ألم، baş ağrısı صداع، boğaz ağrısı ألم الحلق، öksürük سعال، ateş حرارة، burun akıntısı سيلان الأنف، mide ağrısı ألم المعدة. قل Başım ağrıyor (رأسي يؤلمني)، أو Öksürüyorum (أسعل). هذه عبارات لتعلّم اللغة وليست تشخيصاً طبياً.', examples: [LessonExample('Başım ağrıyor.', 'رأسي يؤلمني.'), LessonExample('Boğazım ağrıyor.', 'حلقي يؤلمني.'), LessonExample('Öksürüyorum.', 'أسعل.'), LessonExample('Ateşim var.', 'لديّ حرارة.'), LessonExample('Midem ağrıyor.', 'معدتي تؤلمني.')], question: 'ما معنى Boğazım ağrıyor؟', options: ['رأسي يؤلمني', 'حلقي يؤلمني', 'أنا جائع', 'أنا متعب'], answer: 1, feedback: 'Boğazım تعني حلقي، و ağrıyor تعني يؤلمني.'),
    'a1-u16-4': LessonContent(goal: 'الطبيب والعيادة والمستشفى باللغة التركية.', explanation: 'أماكن وأشخاص: doktor طبيب، hemşire ممرض/ممرضة، hastane مستشفى، klinik عيادة، hasta مريض، muayene فحص طبي، randevu موعد، acil طوارئ. عبارات: Doktor nerede؟ (أين الطبيب؟)، Hastane nerede؟ (أين المستشفى؟).', examples: [LessonExample('doktor', 'طبيب'), LessonExample('hemşire', 'ممرض/ممرضة'), LessonExample('hastane', 'مستشفى'), LessonExample('klinik', 'عيادة'), LessonExample('randevu', 'موعد')], question: 'ما معنى hemşire؟', options: ['صيدلية', 'ممرض أو ممرضة', 'مريض', 'موعد'], answer: 1, feedback: 'hemşire تعني ممرضاً أو ممرضة.'),
    'a1-u16-5': LessonContent(goal: 'حجز موعد وتحديد الوقت باللغة التركية.', explanation: 'للسؤال عن الموعد: Randevu alabilir miyim؟ (هل يمكنني حجز موعد؟). لتحديد الوقت: Saat kaçta؟ (في أي ساعة؟)، Bugün müsait misiniz؟ (هل أنتم متاحون اليوم؟). قل Yarın saat onda (غداً الساعة العاشرة)، Pazartesi günü (يوم الاثنين).', examples: [LessonExample('Randevu alabilir miyim?', 'هل يمكنني حجز موعد؟'), LessonExample('Saat kaçta?', 'في أي ساعة؟'), LessonExample('Yarın saat onda.', 'غداً الساعة العاشرة.'), LessonExample('Pazartesi günü.', 'يوم الاثنين.')], question: 'ما معنى Randevu alabilir miyim؟', options: ['هل يمكنني حجز موعد؟', 'أين الصيدلية؟', 'كيف حالك؟', 'كم السعر؟'], answer: 0, feedback: 'هذه العبارة تُستخدم لطلب حجز موعد.'),
    'a1-u16-6': LessonContent(goal: 'الصيدلية ومفردات الدواء باللغة التركية.', explanation: 'كلمات أساسية: eczane صيدلية، eczacı صيدلي، ilaç دواء، reçete وصفة طبية، kutu علبة. عبارات: Eczane nerede؟ (أين الصيدلية؟)، Eczacıyla konuşabilir miyim؟ (هل يمكنني التحدث مع الصيدلي؟). اطلب إرشاد مختص أو شخص بالغ موثوق بشأن الأدوية؛ هذا الدرس لغوي فقط.', examples: [LessonExample('eczane', 'صيدلية'), LessonExample('eczacı', 'صيدلي'), LessonExample('ilaç', 'دواء'), LessonExample('reçete', 'وصفة طبية'), LessonExample('Eczane nerede?', 'أين الصيدلية؟')], question: 'ما معنى eczane؟', options: ['مستشفى', 'صيدلية', 'مدرسة', 'محطة'], answer: 1, feedback: 'eczane تعني صيدلية.'),
    'a1-u16-7': LessonContent(goal: 'طلب المساعدة والتواصل بوضوح باللغة التركية.', explanation: 'تراكيب مفيدة: Yardıma ihtiyacım var (أحتاج إلى مساعدة)، Bir doktora görünmek istiyorum (أريد مراجعة طبيب)، Lütfen ailemi arayın (من فضلكم اتصلوا بعائلتي)، Anlamadım, tekrar eder misiniz؟ (لم أفهم، هل تعيدون؟). اطلب مساعدة شخص بالغ موثوق أو مختص عند الحاجة.', examples: [LessonExample('Yardıma ihtiyacım var.', 'أحتاج إلى مساعدة.'), LessonExample('Bir doktora görünmek istiyorum.', 'أريد مراجعة طبيب.'), LessonExample('Lütfen ailemi arayın.', 'من فضلكم اتصلوا بعائلتي.'), LessonExample('Tekrar eder misiniz?', 'هل تعيدون من فضلكم؟')], question: 'ما معنى Yardıma ihtiyacım var؟', options: ['أحتاج إلى مساعدة', 'أريد الطعام', 'أنا في المنزل', 'أين الحافلة؟'], answer: 0, feedback: 'الجملة تعني أحتاج إلى مساعدة.'),
    'a1-u16-8': LessonContent(goal: 'حوار في استقبال العيادة باللغة التركية.', explanation: 'اقرأ الحوار: Hasta: Merhaba, randevu almak istiyorum (المراجع: مرحباً، أريد حجز موعد). Görevli: Hangi gün؟ (الموظف: أي يوم؟). Hasta: Yarın mümkün mü؟ (هل غداً ممكن؟). Görevli: Evet, saat onda (نعم، الساعة العاشرة). Hasta: Teşekkür ederim (شكراً).', examples: [LessonExample('Merhaba, randevu almak istiyorum.', 'مرحباً، أريد حجز موعد.'), LessonExample('Hangi gün?', 'أي يوم؟'), LessonExample('Yarın mümkün mü?', 'هل غداً ممكن؟'), LessonExample('Evet, saat onda.', 'نعم، الساعة العاشرة.'), LessonExample('Teşekkür ederim.', 'شكراً لك.')], question: 'ما معنى Hangi gün؟', options: ['أي يوم؟', 'أي لون؟', 'كم السعر؟', 'أين الطبيب؟'], answer: 0, feedback: 'Hangi تعني أيّ، وgün تعني يوم.'),
    'a1-u16-9': LessonContent(goal: 'مراجعة واختبار الوحدة باللغة التركية.', explanation: 'راجع أسماء أجزاء الجسم، وصف الحالة العامة، بعض الكلمات التي تصف الأعراض، وأسماء العاملين والأماكن الصحية. تدرب على وصف حالتك بجملة بسيطة، وذكر عرض لغوياً، وطلب موعد، والسؤال عن موقع الصيدلية. هذه المفردات للتواصل وتعلّم التركية ولا تحل محل نصيحة المختص.', examples: [LessonExample('Kendimi iyi hissediyorum.', 'أشعر أنني بخير.'), LessonExample('Başım ağrıyor.', 'رأسي يؤلمني.'), LessonExample('Randevu almak istiyorum.', 'أريد حجز موعد.'), LessonExample('Eczane nerede?', 'أين الصيدلية؟')], question: 'ما معنى Randevu almak istiyorum؟', options: ['Randevu almak istiyorum.', 'Eczane nerede?', 'Yarın saat onda.', 'Kendimi iyi hissediyorum.'], answer: 0, feedback: 'Randevu almak istiyorum تعني أريد حجز موعد.'),
    'a1-u17-1': LessonContent(goal: 'التعرّف إلى أسماء المهن الشائعة باللغة التركية.', explanation: 'كلمات المهن: öğretmen معلّم، doktor طبيب، mühendis مهندس، öğrenci طالب، aşçı طاهٍ، şoför سائق، polis شرطي، hemşire ممرض، çiftçi مزارع، sanatçı فنان. للسؤال عن المهنة نقول Ne iş yapıyorsun؟ أي ما عملك؟', examples: [LessonExample('öğretmen', 'معلّم'), LessonExample('mühendis', 'مهندس'), LessonExample('aşçı', 'طاهٍ'), LessonExample('şoför', 'سائق'), LessonExample('çiftçi', 'مزارع')], question: 'ما معنى öğretmen؟', options: ['مهندس', 'معلّم', 'سائق', 'طاهٍ'], answer: 1, feedback: 'öğretmen تعني معلّم.'),
    'a1-u17-2': LessonContent(goal: 'تسمية أماكن العمل والمؤسسات الأساسية.', explanation: 'أماكن العمل: okul مدرسة، hastane مستشفى، ofis مكتب، fabrika مصنع، restoran مطعم، mağaza متجر، banka مصرف، otel فندق. اللاحقة -de أو -da قد تدل على الوجود في مكان بحسب الانسجام الصوتي: okulda في المدرسة، ofiste في المكتب.', examples: [LessonExample('okul', 'مدرسة'), LessonExample('ofis', 'مكتب'), LessonExample('fabrika', 'مصنع'), LessonExample('mağaza', 'متجر'), LessonExample('otelde', 'في الفندق')], question: 'ما معنى fabrika؟', options: ['مصنع', 'مكتب', 'مدرسة', 'مصرف'], answer: 0, feedback: 'fabrika تعني مصنع.'),
    'a1-u17-3': LessonContent(goal: 'طرح سؤال عن مهنة الشخص والإجابة عنه.', explanation: 'للسؤال عن العمل: Ne iş yapıyorsun؟ (ما عملك؟)، Mesleğin ne؟ (ما مهنتك؟). للإجابة: Öğretmenim (أنا معلّم)، Mühendisim (أنا مهندس)، Bir şirkette çalışıyorum (أعمل في شركة). لاحظ اتصال لاحقة المتكلم بالكلمة في Öğretmenim.', examples: [LessonExample('Ne iş yapıyorsun?', 'ما عملك؟'), LessonExample('Mesleğin ne?', 'ما مهنتك؟'), LessonExample('Öğretmenim.', 'أنا معلّم.'), LessonExample('Bir şirkette çalışıyorum.', 'أعمل في شركة.')], question: 'كيف تقول «أنا معلّم»؟', options: ['Öğretmenim.', 'Nerede?', 'Saat kaç?', 'Evdeyim.'], answer: 0, feedback: 'Öğretmenim تعني أنا معلّم.'),
    'a1-u17-4': LessonContent(goal: 'استخدام أفعال بسيطة لوصف مهام العمل.', explanation: 'أفعال شائعة: çalışmak يعمل، öğretmek يعلّم، yazmak يكتب، okumak يقرأ، üretmek ينتج، yönetmek يدير، yardım etmek يساعد. أمثلة: İnsanlara yardım ediyorum (أساعد الناس)، Öğrencilere Türkçe öğretiyorum (أعلّم التركية للطلاب).', examples: [LessonExample('çalışmak', 'يعمل'), LessonExample('öğretmek', 'يعلّم'), LessonExample('yazmak', 'يكتب'), LessonExample('üretmek', 'ينتج'), LessonExample('yardım etmek', 'يساعد')], question: 'ما معنى öğretmek؟', options: ['ينتج', 'يعلّم', 'يقرأ', 'يدير'], answer: 1, feedback: 'öğretmek تعني يعلّم.'),
    'a1-u17-5': LessonContent(goal: 'الحديث عن أوقات العمل وأيام الدوام.', explanation: 'كلمات مهمة: iş saati ساعات العمل، çalışma günü يوم العمل، sabah صباحاً، öğleden sonra بعد الظهر، akşam مساءً، izin إجازة، hafta sonu عطلة نهاية الأسبوع. أمثلة: Saat dokuzda başlıyorum (أبدأ الساعة التاسعة)، Saat beşte bitiriyorum (أنتهي الساعة الخامسة)، Hafta sonu izinliyim (أنا في إجازة نهاية الأسبوع).', examples: [LessonExample('Saat dokuzda başlıyorum.', 'أبدأ الساعة التاسعة.'), LessonExample('Saat beşte bitiriyorum.', 'أنتهي الساعة الخامسة.'), LessonExample('Hafta sonu', 'عطلة نهاية الأسبوع'), LessonExample('izinliyim', 'أنا في إجازة')], question: 'ما معنى Hafta sonu؟', options: ['صباحاً', 'عطلة نهاية الأسبوع', 'مكان العمل', 'المهنة'], answer: 1, feedback: 'Hafta sonu تعني عطلة نهاية الأسبوع.'),
    'a1-u17-6': LessonContent(goal: 'وصف المهارات والقدرات باستخدام تراكيب بسيطة.', explanation: 'كلمات: beceri مهارة، deneyim خبرة، bilgisayar حاسوب، yabancı dil لغة أجنبية، takım çalışması العمل الجماعي. للتعبير عن القدرة نستخدم -ebil/-abil: Bilgisayar kullanabilirim (أستطيع استخدام الحاسوب)، Türkçe konuşabilirim (أستطيع التحدث بالتركية).', examples: [LessonExample('beceri', 'مهارة'), LessonExample('deneyim', 'خبرة'), LessonExample('Bilgisayar kullanabilirim.', 'أستطيع استخدام الحاسوب.'), LessonExample('Türkçe konuşabilirim.', 'أستطيع التحدث بالتركية.')], question: 'ما معنى deneyim؟', options: ['خبرة', 'إجازة', 'راتب', 'مكتب'], answer: 0, feedback: 'deneyim تعني خبرة.'),
    'a1-u17-7': LessonContent(goal: 'فهم عبارات عامة في التقديم إلى وظيفة.', explanation: 'عبارات: İş arıyorum (أبحث عن عمل)، İş başvurusu (طلب توظيف)، özgeçmiş السيرة الذاتية، görüşme مقابلة، deneyimim var لدي خبرة، Teşekkür ederim (شكراً). هذه عبارات تعلّم لغوي للتعرّف إلى مفردات المواقف المهنية.', examples: [LessonExample('İş arıyorum.', 'أبحث عن عمل.'), LessonExample('İş başvurusu', 'طلب توظيف'), LessonExample('özgeçmiş', 'السيرة الذاتية'), LessonExample('Görüşme ne zaman?', 'متى المقابلة؟'), LessonExample('Deneyimim var.', 'لدي خبرة.')], question: 'ما معنى İş arıyorum؟', options: ['أبحث عن عمل', 'أنا في المدرسة', 'أذهب إلى المنزل', 'أكتب رسالة'], answer: 0, feedback: 'İş arıyorum تعني أبحث عن عمل.'),
    'a1-u17-8': LessonContent(goal: 'فهم حوار قصير عن المهنة ومكان العمل.', explanation: 'A: Ne iş yapıyorsun؟ (ما عملك؟) B: Öğretmenim. (أنا معلّم.) A: Nerede çalışıyorsun؟ (أين تعمل؟) B: Bir okulda çalışıyorum. (أعمل في مدرسة.) A: İşini seviyor musun؟ (هل تحب عملك؟) B: Evet, seviyorum. (نعم، أحبه.)', examples: [LessonExample('Ne iş yapıyorsun?', 'ما عملك؟'), LessonExample('Öğretmenim.', 'أنا معلّم.'), LessonExample('Nerede çalışıyorsun?', 'أين تعمل؟'), LessonExample('Bir okulda çalışıyorum.', 'أعمل في مدرسة.'), LessonExample('İşini seviyor musun?', 'هل تحب عملك؟')], question: 'ما معنى Nerede çalışıyorsun؟', options: ['أين تعمل؟', 'ما اسمك؟', 'كم عمرك؟', 'متى تبدأ؟'], answer: 0, feedback: 'Nerede تعني أين، وçalışıyorsun تعني تعمل.'),
    'a1-u17-9': LessonContent(goal: 'مراجعة المهن وأماكن العمل والمهام والدوام والمهارات.', explanation: 'راجع أسماء المهن والمؤسسات، واسأل عن وظيفة شخص، وصف مكان عملك، واذكر مهمة أو مهارة، وتحدث عن وقت بداية الدوام ونهايته. كوّن جملاً مثل Bir ofiste çalışıyorum (أعمل في مكتب) وTürkçe konuşabilirim (أستطيع التحدث بالتركية).', examples: [LessonExample('Ben öğrenciyim.', 'أنا طالب.'), LessonExample('Bir hastanede çalışıyor.', 'هو/هي يعمل في مستشفى.'), LessonExample('Saat dokuzda başlıyorum.', 'أبدأ الساعة التاسعة.'), LessonExample('Türkçe konuşabilirim.', 'أستطيع التحدث بالتركية.')], question: 'اختر ترجمة «أستطيع التحدث بالتركية».', options: ['Türkçe konuşabilirim.', 'İş arıyorum.', 'Okul nerede?', 'Saat beşte.'], answer: 0, feedback: 'Türkçe konuşabilirim تعني أستطيع التحدث بالتركية.'),
    'a1-u18-1': LessonContent(goal: 'التعرّف إلى أسماء الهوايات والأنشطة في التركية.', explanation: 'كلمات شائعة: hobi هواية، kitap okumak قراءة الكتب، müzik dinlemek الاستماع إلى الموسيقى، resim yapmak الرسم، yemek yapmak الطبخ، fotoğraf çekmek التصوير، dans etmek الرقص، yüzmek السباحة. المصدر -mak/-mek يحوّل الفعل إلى صيغة المصدر.', examples: [LessonExample('kitap okumak', 'قراءة الكتب'), LessonExample('müzik dinlemek', 'الاستماع إلى الموسيقى'), LessonExample('resim yapmak', 'الرسم'), LessonExample('yüzmek', 'السباحة'), LessonExample('dans etmek', 'الرقص')], question: 'ما معنى kitap okumak؟', options: ['قراءة الكتب', 'السباحة', 'الطبخ', 'التصوير'], answer: 0, feedback: 'kitap okumak تعني قراءة الكتب.'),
    'a1-u18-2': LessonContent(goal: 'التعرّف إلى أسماء الرياضات والأدوات الرياضية.', explanation: 'رياضات: futbol كرة القدم، basketbol كرة السلة، tenis التنس، voleybol الكرة الطائرة، koşu الجري، bisiklet sürmek ركوب الدراجة. أدوات: top كرة، bisiklet دراجة، raket مضرب، spor ayakkabısı حذاء رياضي.', examples: [LessonExample('futbol', 'كرة القدم'), LessonExample('basketbol', 'كرة السلة'), LessonExample('tenis', 'التنس'), LessonExample('koşu', 'الجري'), LessonExample('bisiklet sürmek', 'ركوب الدراجة')], question: 'ما معنى tenis؟', options: ['كرة السلة', 'التنس', 'الجري', 'السباحة'], answer: 1, feedback: 'tenis تعني التنس.'),
    'a1-u18-3': LessonContent(goal: 'التعبير عن الهوايات والتفضيلات الشخصية.', explanation: 'للتعبير عن الإعجاب نستخدم hoşlanmak أو sevmek. أمثلة: Kitap okumayı seviyorum (أحب قراءة الكتب)، Müzik dinlemekten hoşlanıyorum (أستمتع بالاستماع إلى الموسيقى)، Futbolu seviyorum (أحب كرة القدم). انتبه إلى اللاحقة التي تأتي مع الفعل في كل تركيب.', examples: [LessonExample('Kitap okumayı seviyorum.', 'أحب قراءة الكتب.'), LessonExample('Müzik dinlemekten hoşlanıyorum.', 'أستمتع بالاستماع إلى الموسيقى.'), LessonExample('Futbolu seviyorum.', 'أحب كرة القدم.'), LessonExample('Dans etmeyi seviyorum.', 'أحب الرقص.')], question: 'كيف تقول «أحب قراءة الكتب»؟', options: ['Kitap okumayı seviyorum.', 'Kitap nerede?', 'Saat kaç?', 'Yemek yapıyorum.'], answer: 0, feedback: 'Kitap okumayı seviyorum تعني أحب قراءة الكتب.'),
    'a1-u18-4': LessonContent(goal: 'استخدام كلمات التكرار والوقت للحديث عن الأنشطة.', explanation: 'ظروف التكرار: her gün كل يوم، sık sık كثيراً، bazen أحياناً، nadiren نادراً، hiç أبداً/مطلقاً بحسب السياق. أمثلة: Her gün yürüyüş yapıyorum (أتمشى كل يوم)، Bazen tenis oynarım (ألعب التنس أحياناً)، Hafta sonları yüzerim (أسبح في عطلات نهاية الأسبوع).', examples: [LessonExample('her gün', 'كل يوم'), LessonExample('sık sık', 'كثيراً'), LessonExample('bazen', 'أحياناً'), LessonExample('nadiren', 'نادراً'), LessonExample('Hafta sonları', 'في عطلات نهاية الأسبوع')], question: 'ما معنى bazen؟', options: ['دائماً', 'أحياناً', 'نادراً', 'غداً'], answer: 1, feedback: 'bazen تعني أحياناً.'),
    'a1-u18-5': LessonContent(goal: 'دعوة شخص إلى نشاط والرد على الدعوة.', explanation: 'للدعوة نقول: Benimle sinemaya gelir misin؟ (هل تأتي معي إلى السينما؟)، Birlikte yürüyüş yapalım mı؟ (هل نتمشى معاً؟). للقبول: Tabii, memnuniyetle (بالتأكيد، بكل سرور). للاعتذار: Üzgünüm, bugün gelemem (آسف، لا أستطيع المجيء اليوم).', examples: [LessonExample('Benimle gelir misin?', 'هل تأتي معي؟'), LessonExample('Birlikte yürüyüş yapalım mı?', 'هل نتمشى معاً؟'), LessonExample('Tabii, memnuniyetle.', 'بالتأكيد، بكل سرور.'), LessonExample('Bugün gelemem.', 'لا أستطيع المجيء اليوم.')], question: 'ما معنى Tabii, memnuniyetle؟', options: ['لا أستطيع', 'بالتأكيد، بكل سرور', 'إلى أين؟', 'ليس اليوم'], answer: 1, feedback: 'تُستخدم للقبول بالدعوة بسرور.'),
    'a1-u18-6': LessonContent(goal: 'تحديد المكان والزمان لممارسة نشاط.', explanation: 'أماكن الأنشطة: park حديقة، spor salonu نادٍ رياضي، sinema سينما، kütüphane مكتبة، yüzme havuzu مسبح، sahil شاطئ. أمثلة: Parkta buluşalım (لنلتقِ في الحديقة)، Saat altıda sinemada olacağım (سأكون في السينما الساعة السادسة).', examples: [LessonExample('park', 'حديقة'), LessonExample('spor salonu', 'نادٍ رياضي'), LessonExample('sinema', 'سينما'), LessonExample('kütüphane', 'مكتبة'), LessonExample('yüzme havuzu', 'مسبح')], question: 'ما معنى kütüphane؟', options: ['مكتبة', 'مسبح', 'حديقة', 'سينما'], answer: 0, feedback: 'kütüphane تعني مكتبة.'),
    'a1-u18-7': LessonContent(goal: 'وصف القدرة على ممارسة الأنشطة والتحدث عن المهارات.', explanation: 'نستخدم -ebil/-abil للتعبير عن القدرة: Yüzebilirim (أستطيع السباحة)، Gitar çalabilirim (أستطيع العزف على الغيتار)، İyi dans edebilirim (أستطيع الرقص جيداً). للنفي: Yüzemem (لا أستطيع السباحة).', examples: [LessonExample('Yüzebilirim.', 'أستطيع السباحة.'), LessonExample('Gitar çalabilirim.', 'أستطيع العزف على الغيتار.'), LessonExample('İyi dans edebilirim.', 'أستطيع الرقص جيداً.'), LessonExample('Yüzemem.', 'لا أستطيع السباحة.')], question: 'ما معنى Gitar çalabilirim؟', options: ['أستطيع العزف على الغيتار', 'أحب القراءة', 'أذهب إلى المدرسة', 'أسبح كل يوم'], answer: 0, feedback: 'Gitar çalabilirim تعني أستطيع العزف على الغيتار.'),
    'a1-u18-8': LessonContent(goal: 'فهم حوار قصير لترتيب نشاط مع صديق.', explanation: 'A: Hafta sonu ne yapalım؟ (ماذا نفعل في عطلة نهاية الأسبوع؟) B: Sinemaya gidelim mi؟ (ما رأيك أن نذهب إلى السينما؟) A: Harika fikir! Saat kaçta؟ (فكرة رائعة! في أي ساعة؟) B: Saat beşte buluşalım. (لنلتقِ الساعة الخامسة).', examples: [LessonExample('Hafta sonu ne yapalım?', 'ماذا نفعل في عطلة نهاية الأسبوع؟'), LessonExample('Sinemaya gidelim mi?', 'ما رأيك أن نذهب إلى السينما؟'), LessonExample('Harika fikir!', 'فكرة رائعة!'), LessonExample('Saat kaçta?', 'في أي ساعة؟'), LessonExample('Saat beşte buluşalım.', 'لنلتقِ الساعة الخامسة.')], question: 'ما معنى Harika fikir؟', options: ['فكرة رائعة', 'ليس لدي وقت', 'أين المنزل؟', 'أنا متعب'], answer: 0, feedback: 'Harika fikir تعني فكرة رائعة.'),
    'a1-u18-9': LessonContent(goal: 'مراجعة الهوايات والرياضات والتفضيلات والدعوات.', explanation: 'راجع أسماء الهوايات والرياضات، وعبارات الإعجاب والقدرة، وظروف التكرار، وصيغ الدعوة والقبول والاعتذار. كوّن جملتين عن هواياتك، ثم ادعُ صديقاً إلى نشاط وحدد المكان والوقت.', examples: [LessonExample('Bazen tenis oynarım.', 'ألعب التنس أحياناً.'), LessonExample('Kitap okumayı seviyorum.', 'أحب قراءة الكتب.'), LessonExample('Benimle sinemaya gelir misin?', 'هل تأتي معي إلى السينما؟'), LessonExample('Parkta buluşalım.', 'لنلتقِ في الحديقة.')], question: 'اختر ترجمة «هل نتمشى معاً؟»', options: ['Birlikte yürüyüş yapalım mı?', 'Yüzemem.', 'Kütüphane nerede?', 'Saat beşte.'], answer: 0, feedback: 'Birlikte yürüyüş yapalım mı تعني هل نتمشى معاً؟'),
    'a1-u19-1': LessonContent(goal: 'التعرّف إلى مفردات السفر ووسائل النقل.', explanation: 'كلمات أساسية: seyahat سفر، tatil عطلة، yolculuk رحلة، uçak طائرة، tren قطار، otobüs حافلة، araba سيارة، gemi سفينة، bilet تذكرة، valiz حقيبة سفر. أمثلة: Uçakla seyahat ediyorum (أسافر بالطائرة)، Tren bileti aldım (اشتريت تذكرة قطار).', examples: [LessonExample('seyahat', 'سفر'), LessonExample('tatil', 'عطلة'), LessonExample('uçak', 'طائرة'), LessonExample('tren', 'قطار'), LessonExample('valiz', 'حقيبة سفر')], question: 'ما معنى bilet؟', options: ['حقيبة', 'تذكرة', 'فندق', 'مطار'], answer: 1, feedback: 'bilet تعني تذكرة.'),
    'a1-u19-2': LessonContent(goal: 'التحدث عن الوجهة وخطة الرحلة.', explanation: 'للسؤال عن الوجهة: Nereye gidiyorsun؟ (إلى أين تذهب؟)، Nereden geliyorsun؟ (من أين أتيت؟). للتعبير عن الوجهة: İstanbul'a gidiyorum (أذهب إلى إسطنبول)، Tatile çıkıyorum (أنطلق في عطلة)، Yazın Antalya'ya gideceğiz (سنذهب إلى أنطاليا في الصيف).', examples: [LessonExample('Nereye gidiyorsun?', 'إلى أين تذهب؟'), LessonExample('İstanbul'a gidiyorum.', 'أذهب إلى إسطنبول.'), LessonExample('Nereden geliyorsun?', 'من أين أتيت؟'), LessonExample('Tatile çıkıyorum.', 'أنطلق في عطلة.')], question: 'ما معنى Nereye gidiyorsun؟', options: ['من أين أتيت؟', 'إلى أين تذهب؟', 'متى تعود؟', 'أين الفندق؟'], answer: 1, feedback: 'Nereye gidiyorsun تعني إلى أين تذهب؟.'),
    'a1-u19-3': LessonContent(goal: 'التعرّف إلى مفردات الفندق وحجز غرفة.', explanation: 'مفردات الإقامة: otel فندق، oda غرفة، resepsiyon استقبال، rezervasyon حجز، anahtar مفتاح، tek kişilik غرفة لشخص واحد، çift kişilik غرفة لشخصين. عبارات: Bir oda ayırtmak istiyorum (أريد حجز غرفة)، Rezervasyonum var (لدي حجز)، Kahvaltı dahil mi؟ (هل الإفطار مشمول؟).', examples: [LessonExample('otel', 'فندق'), LessonExample('oda', 'غرفة'), LessonExample('rezervasyon', 'حجز'), LessonExample('resepsiyon', 'الاستقبال'), LessonExample('Kahvaltı dahil mi?', 'هل الإفطار مشمول؟')], question: 'ما معنى rezervasyon؟', options: ['مفتاح', 'حجز', 'حقيبة', 'تذكرة'], answer: 1, feedback: 'rezervasyon تعني حجز.'),
    'a1-u19-4': LessonContent(goal: 'استخدام مفردات المطار وإجراءات السفر الأساسية.', explanation: 'كلمات المطار: havaalanı مطار، pasaport جواز سفر، biniş kartı بطاقة صعود، kapı بوابة، uçuş رحلة جوية، bagaj أمتعة، güvenlik أمن. عبارات: Uçuş kapısı nerede؟ (أين بوابة الرحلة؟)، Pasaportum burada (جواز سفري هنا)، Uçağım saat üçte (طائرتي الساعة الثالثة).', examples: [LessonExample('havaalanı', 'مطار'), LessonExample('pasaport', 'جواز سفر'), LessonExample('biniş kartı', 'بطاقة صعود'), LessonExample('uçuş kapısı', 'بوابة الرحلة'), LessonExample('bagaj', 'أمتعة')], question: 'ما معنى havaalanı؟', options: ['محطة قطار', 'مطار', 'فندق', 'ميناء'], answer: 1, feedback: 'havaalanı تعني مطار.'),
    'a1-u19-5': LessonContent(goal: 'السؤال عن الاتجاهات والتنقل في مكان جديد.', explanation: 'عبارات نافعة: ... nerede؟ (أين ...؟)، Nasıl gidebilirim؟ (كيف يمكنني الذهاب؟)، sağ يمين، sol يسار، düz devam edin تابع إلى الأمام، yakın قريب، uzak بعيد. مثال: Otobüs durağı nerede؟ (أين موقف الحافلة؟)، Otele nasıl gidebilirim؟ (كيف أصل إلى الفندق؟).', examples: [LessonExample('sağ', 'يمين'), LessonExample('sol', 'يسار'), LessonExample('düz devam edin', 'تابع إلى الأمام'), LessonExample('yakın', 'قريب'), LessonExample('Otele nasıl gidebilirim?', 'كيف أصل إلى الفندق؟')], question: 'ما معنى sol؟', options: ['يمين', 'يسار', 'قريب', 'بعيد'], answer: 1, feedback: 'sol تعني يسار.'),
    'a1-u19-6': LessonContent(goal: 'وصف غرفة الفندق والسؤال عن الخدمات.', explanation: 'خدمات ومرافق: internet إنترنت، Wi-Fi واي فاي، klima تكييف، duş دش، havlu منشفة، asansör مصعد، kahvaltı إفطار، manzara إطلالة. عبارات: Odada Wi-Fi var mı؟ (هل يوجد واي فاي في الغرفة؟)، Havlu alabilir miyim؟ (هل يمكنني الحصول على منشفة؟)، Asansör nerede؟ (أين المصعد؟).', examples: [LessonExample('Wi-Fi', 'واي فاي'), LessonExample('klima', 'تكييف'), LessonExample('havlu', 'منشفة'), LessonExample('asansör', 'مصعد'), LessonExample('Odada Wi-Fi var mı?', 'هل يوجد واي فاي في الغرفة؟')], question: 'ما معنى havlu؟', options: ['منشفة', 'مفتاح', 'مصعد', 'إفطار'], answer: 0, feedback: 'havlu تعني منشفة.'),
    'a1-u19-7': LessonContent(goal: 'التعبير عن مدة الإقامة والأنشطة في العطلة.', explanation: 'للسؤال عن المدة: Kaç gün؟ (كم يوماً؟)، Ne kadar kalacaksınız؟ (كم ستقيمون؟). عبارات: Üç gün kalacağım (سأقيم ثلاثة أيام)، Bir hafta tatildeyim (أنا في عطلة لمدة أسبوع)، Deniz kenarında dinleniyorum (أستريح على شاطئ البحر).', examples: [LessonExample('Kaç gün?', 'كم يوماً؟'), LessonExample('Üç gün kalacağım.', 'سأقيم ثلاثة أيام.'), LessonExample('Bir hafta', 'أسبوع واحد'), LessonExample('Deniz kenarında', 'على شاطئ البحر')], question: 'ما معنى Üç gün kalacağım؟', options: ['سأغادر اليوم', 'سأقيم ثلاثة أيام', 'أريد غرفة', 'أين المطار؟'], answer: 1, feedback: 'Üç gün kalacağım تعني سأقيم ثلاثة أيام.'),
    'a1-u19-8': LessonContent(goal: 'فهم حوار بسيط في الفندق أثناء تسجيل الوصول.', explanation: 'Misafir: Merhaba, rezervasyonum var (النزيل: مرحباً، لدي حجز). Görevli: Pasaportunuzu alabilir miyim؟ (الموظف: هل يمكنني أخذ جواز سفرك؟). Misafir: Tabii, buyurun (بالطبع، تفضل). Görevli: İşte oda anahtarınız (هذا مفتاح غرفتك). Misafir: Teşekkür ederim (شكراً).', examples: [LessonExample('Rezervasyonum var.', 'لدي حجز.'), LessonExample('Pasaportunuzu alabilir miyim?', 'هل يمكنني أخذ جواز سفرك؟'), LessonExample('Tabii, buyurun.', 'بالطبع، تفضل.'), LessonExample('Oda anahtarınız.', 'مفتاح غرفتك.'), LessonExample('Teşekkür ederim.', 'شكراً لك.')], question: 'ما معنى Rezervasyonum var؟', options: ['لدي حجز', 'ليس لدي حقيبة', 'أين المطار؟', 'أريد تذكرة'], answer: 0, feedback: 'Rezervasyonum var تعني لدي حجز.'),
    'a1-u19-9': LessonContent(goal: 'مراجعة مفردات السفر والمطار والفندق والاتجاهات.', explanation: 'راجع أسماء وسائل النقل وأماكن السفر والإقامة ومفردات المطار والخدمات. تدرب على ذكر وجهتك ومدة إقامتك، وطلب غرفة، والسؤال عن الطريق أو خدمة في الفندق. حاول تكوين حوار قصير من التحية إلى استلام مفتاح الغرفة.', examples: [LessonExample('İstanbul'a gidiyorum.', 'أذهب إلى إسطنبول.'), LessonExample('Bir oda ayırtmak istiyorum.', 'أريد حجز غرفة.'), LessonExample('Uçuş kapısı nerede?', 'أين بوابة الرحلة؟'), LessonExample('Üç gün kalacağım.', 'سأقيم ثلاثة أيام.')], question: 'اختر ترجمة «أريد حجز غرفة».', options: ['Bir oda ayırtmak istiyorum.', 'Tren bileti aldım.', 'Otel nerede?', 'Üç gün kalacağım.'], answer: 0, feedback: 'Bir oda ayırtmak istiyorum تعني أريد حجز غرفة.'),
    'a1-u20-1': LessonContent(goal: "مراجعة التعارف والتحيات والمعلومات الشخصية.", explanation: "راجع التحيات والتعريف بالاسم والجنسية واللغة والسكن. Kalıp: Benim adım ... (اسمي...)، Nerelisin؟ (من أين أنت؟)، ... yaşındayım (عمري...). انتبه إلى الضمائر وصيغ السؤال والجواب القصيرة.", examples: [LessonExample("Merhaba, nasılsın?", "مرحباً، كيف حالك؟"), LessonExample("Benim adım Elif.", "اسمي إليف."), LessonExample("Türkçe öğreniyorum.", "أتعلم التركية."), LessonExample("Ankara'da yaşıyorum.", "أعيش في أنقرة.")], question: "ما معنى Nerelisin؟", options: ["ما اسمك؟", "من أين أنت؟", "كم عمرك؟", "أين تسكن؟"], answer: 1, feedback: "Nerelisin تعني من أين أنت؟"),
    'a1-u20-2': LessonContent(goal: "مراجعة الأسماء والصفات والألوان والأشياء.", explanation: "تدرّب على أدوات التعريف بالإشارة: bu هذا/هذه، şu ذلك، o هو/هي أو ذاك. راجع الصفات والألوان ومطابقة الصفة للاسم. أمثلة: Bu kitap yeni (هذا الكتاب جديد)، Kırmızı çanta (حقيبة حمراء).", examples: [LessonExample("Bu bir kitap.", "هذا كتاب."), LessonExample("Mavi kalem", "قلم أزرق"), LessonExample("Ev büyük.", "البيت كبير."), LessonExample("Bu telefon pahalı.", "هذا الهاتف غالي.")], question: "ما معنى büyük؟", options: ["صغير", "كبير", "جديد", "قديم"], answer: 1, feedback: "büyük تعني كبير."),
    'a1-u20-3': LessonContent(goal: "مراجعة الأرقام والوقت والتاريخ والطقس.", explanation: "راجع الأرقام وأيام الأسبوع والشهور والساعة. للسؤال عن الوقت: Saat kaç؟ (كم الساعة؟). للتاريخ: Bugün günlerden ne؟ (ما اليوم؟). للطقس: Hava nasıl؟ (كيف الطقس؟).", examples: [LessonExample("Saat üç.", "الساعة الثالثة."), LessonExample("Bugün pazartesi.", "اليوم الاثنين."), LessonExample("Hava soğuk.", "الطقس بارد."), LessonExample("Yarın yağmur yağacak.", "غداً ستمطر.")], question: "كيف تسأل عن الساعة باللغة التركية؟", options: ["Hava nasıl?", "Saat kaç?", "Nereye gidiyorsun?", "Kaç yaşındasın?"], answer: 1, feedback: "Saat kaç تعني كم الساعة؟"),
    'a1-u20-4': LessonContent(goal: "مراجعة الروتين اليومي والأفعال الشائعة.", explanation: "راجع أفعال الحياة اليومية مثل kalkmak يستيقظ، gitmek يذهب، yemek يأكل، içmek يشرب، çalışmak يعمل/يدرس. استخدم المضارع المستمر -yor للحدث الجاري أو الروتين في سياق مناسب: Her gün erken kalkıyorum (أستيقظ مبكراً كل يوم).", examples: [LessonExample("Erken kalkıyorum.", "أستيقظ مبكراً."), LessonExample("Okula gidiyorum.", "أذهب إلى المدرسة."), LessonExample("Su içiyorum.", "أشرب الماء."), LessonExample("Akşam kitap okuyorum.", "أقرأ كتاباً مساءً.")], question: "ما معنى içiyorum؟", options: ["أذهب", "أشرب", "أكتب", "أنام"], answer: 1, feedback: "içiyorum تعني أشرب."),
    'a1-u20-5': LessonContent(goal: "مراجعة الطعام والتسوق والطلبات البسيطة.", explanation: "راجع أسماء الأطعمة والمشروبات والأسعار والملابس. للطلب بأدب: ... istiyorum (أريد...)، Ne kadar؟ (بكم؟)، Hesap lütfen (الحساب من فضلك).", examples: [LessonExample("Bir çay istiyorum.", "أريد شاياً."), LessonExample("Bu ne kadar?", "بكم هذا؟"), LessonExample("Ekmek ve peynir", "خبز وجبن"), LessonExample("Hesap lütfen.", "الحساب من فضلك.")], question: "ما معنى Bu ne kadar؟", options: ["أين هذا؟", "بكم هذا؟", "ماذا تريد؟", "هل هو جديد؟"], answer: 1, feedback: "Bu ne kadar تعني بكم هذا؟"),
    'a1-u20-6': LessonContent(goal: "مراجعة المنزل والمدينة والمواصلات والاتجاهات.", explanation: "راجع غرف المنزل وأثاثه وأماكن المدينة ووسائل النقل. استخدم var/yok للتعبير عن وجود شيء أو عدمه، وحروف الاتجاه والمكان الأساسية: yanında بجانب، içinde داخل، yakın قريب.", examples: [LessonExample("Evde iki oda var.", "في البيت غرفتان."), LessonExample("Otobüs durağı nerede?", "أين موقف الحافلة؟"), LessonExample("Market evin yanında.", "المتجر بجانب المنزل."), LessonExample("Metroya biniyorum.", "أركب المترو.")], question: "ما معنى yok؟", options: ["يوجد", "لا يوجد", "بعيد", "بجانب"], answer: 1, feedback: "yok تعني لا يوجد."),
    'a1-u20-7': LessonContent(goal: "مراجعة الأسرة والصحة والعمل والهوايات.", explanation: "تدرّب على وصف أفراد الأسرة والمهن وأجزاء الجسم والعبارات الصحية والهوايات. راجع الملكية والتفضيل والقدرة: seviyorum أحب، sevmiyorum لا أحب، -ebilmek يستطيع.", examples: [LessonExample("Bir kardeşim var.", "لدي أخ أو أخت."), LessonExample("Doktora gitmeliyim.", "يجب أن أذهب إلى الطبيب."), LessonExample("Öğretmenim.", "أنا معلم/معلمة."), LessonExample("Yüzebilirim.", "أستطيع السباحة.")], question: "ما معنى Yüzebilirim؟", options: ["أحب السباحة", "أستطيع السباحة", "أذهب للسباحة", "لا أسبح"], answer: 1, feedback: "Yüzebilirim تعني أستطيع السباحة."),
    'a1-u20-8': LessonContent(goal: "تطبيق محادثة متكاملة في مواقف الحياة اليومية.", explanation: "اقرأ الحوار وحاول فهم المعنى العام: A: Merhaba, nasılsınız؟ (مرحباً، كيف حالك؟) B: İyiyim, teşekkür ederim. (أنا بخير، شكراً.) A: Bugün nereye gidiyorsunuz؟ (إلى أين تذهب اليوم؟) B: Markete gidiyorum. (أذهب إلى المتجر.) A: Sonra kafeye gidelim mi؟ (هل نذهب إلى المقهى بعد ذلك؟) B: Harika fikir! (فكرة رائعة!).", examples: [LessonExample("Nasılsınız?", "كيف حالك؟ بصيغة مهذبة"), LessonExample("İyiyim, teşekkür ederim.", "أنا بخير، شكراً لك."), LessonExample("Markete gidiyorum.", "أذهب إلى المتجر."), LessonExample("Harika fikir!", "فكرة رائعة!")], question: "ماذا تعني Markete gidiyorum؟", options: ["أذهب إلى المتجر", "أعود إلى المنزل", "أشرب القهوة", "أتعلم التركية"], answer: 0, feedback: "Markete gidiyorum تعني أذهب إلى المتجر."),
    'a1-u20-9': LessonContent(goal: "اختبار ختامي شامل لمهارات A1.", explanation: "هذه المحطة تجمع أساسيات A1. اقرأ الجملة، حدّد الزمن والمعنى، وانتبه إلى اللواحق والسياق. الجملة: Yarın arkadaşım ile İstanbul'a gideceğim (غداً سأذهب إلى إسطنبول مع صديقي). لاحظ أن gideceğim صيغة مستقبل من gitmek.", examples: [LessonExample("Yarın", "غداً"), LessonExample("arkadaşım ile", "مع صديقي"), LessonExample("İstanbul'a", "إلى إسطنبول"), LessonExample("gideceğim", "سأذهب")], question: "ما زمن gideceğim؟", options: ["الماضي", "الحاضر المستمر", "المستقبل", "الأمر"], answer: 2, feedback: "gideceğim صيغة المستقبل وتعني سأذهب."),
    'a2-u1-1': LessonContent(goal: "التحدث عن أحداث يومية حدثت في الماضي القريب.", explanation: "في A2 نبدأ باستخدام الماضي المحدد -di للحديث عن حدث انتهى. يتغير شكل اللاحقة بحسب الانسجام الصوتي: geldi (جاء)، baktı (نظر)، gördü (رأى)، konuştu (تحدث). مثال: Dün sinemaya gittim (ذهبت إلى السينما أمس).", examples: [LessonExample("Dün", "أمس"), LessonExample("Dün kitap okudum.", "قرأت كتاباً أمس."), LessonExample("Eve geldim.", "وصلت إلى المنزل."), LessonExample("Arkadaşımı gördüm.", "رأيت صديقي.")], question: "ما معنى Dün sinemaya gittim؟", options: ["سأذهب إلى السينما غداً", "ذهبت إلى السينما أمس", "أنا في السينما الآن", "أذهب إلى السينما كل يوم"], answer: 1, feedback: "الجملة تعني ذهبت إلى السينما أمس."),
    'a2-u1-2': LessonContent(goal: "تكوين الماضي المحدد مع الأفعال المنتظمة.", explanation: "تُضاف لاحقة الماضي -dı/-di/-du/-dü أو -tı/-ti/-tu/-tü بحسب آخر صوت في الفعل. أمثلة: çalışmak ← çalıştım (عملت/درست)، dinlemek ← dinledim (استمعت)، başlamak ← başladım (بدأت). ضمير المتكلم المفرد يظهر في النهاية بصيغة -m.", examples: [LessonExample("çalıştım", "عملت/درست"), LessonExample("dinledim", "استمعت"), LessonExample("başladım", "بدأت"), LessonExample("Dün erken uyudum.", "نمت مبكراً أمس.")], question: "ما صيغة «استمعت» من dinlemek؟", options: ["dinledim", "dinliyorum", "dinleyeceğim", "dinlerim"], answer: 0, feedback: "dinledim هي صيغة الماضي للمتكلم: استمعت."),
    'a2-u1-3': LessonContent(goal: "نفي الماضي وصياغة الأسئلة عنه.", explanation: "لنفي الماضي نستخدم -ma/-me قبل لاحقة الماضي: gitmedim (لم أذهب)، izlemedim (لم أشاهد). وفي السؤال نستخدم mı/mi/mu/mü منفصلة: Geldin mi؟ (هل أتيت؟)، Dün çalıştınız mı؟ (هل عملتم أمس؟).", examples: [LessonExample("Gitmedim.", "لم أذهب."), LessonExample("Film izlemedim.", "لم أشاهد الفيلم."), LessonExample("Geldin mi?", "هل أتيت؟"), LessonExample("Dün çalıştınız mı?", "هل عملتم أمس؟")], question: "كيف تقول «لم أذهب»؟", options: ["Gittim", "Gitmedim", "Gidiyorum", "Gideceğim"], answer: 1, feedback: "Gitmedim تعني لم أذهب."),
    'a2-u1-4': LessonContent(goal: "استخدام كلمات الزمن مع الماضي.", explanation: "تساعد كلمات الزمن على تحديد وقت الحدث: dün أمس، önce önce قبل، geçen hafta الأسبوع الماضي، geçen yıl العام الماضي، sabah صباحاً، akşam مساءً. مثال: Geçen hafta müzeye gittik (ذهبنا إلى المتحف الأسبوع الماضي).", examples: [LessonExample("geçen hafta", "الأسبوع الماضي"), LessonExample("geçen yıl", "العام الماضي"), LessonExample("sabah", "صباحاً"), LessonExample("Geçen yıl Ankara'da yaşadım.", "عشت في أنقرة العام الماضي.")], question: "ما معنى geçen hafta؟", options: ["الأسبوع القادم", "الأسبوع الماضي", "كل أسبوع", "هذا الصباح"], answer: 1, feedback: "geçen hafta تعني الأسبوع الماضي."),
    'a2-u1-5': LessonContent(goal: "رواية أحداث يوم سابق بترتيب واضح.", explanation: "لربط الأحداث استخدم önce أولاً/قبل، sonra ثم/بعد ذلك، daha sonra لاحقاً، en sonunda أخيراً. مثال: Önce kahvaltı yaptım, sonra işe gittim (تناولت الفطور أولاً، ثم ذهبت إلى العمل). حافظ على صيغة الماضي في الأفعال المتتابعة.", examples: [LessonExample("Önce", "أولاً"), LessonExample("Sonra", "ثم"), LessonExample("Daha sonra", "بعد ذلك"), LessonExample("En sonunda", "أخيراً"), LessonExample("Önce duş aldım, sonra çıktım.", "استحممت أولاً، ثم خرجت.")], question: "أي كلمة تعني «ثم»؟", options: ["Önce", "Sonra", "Dün", "Yarın"], answer: 1, feedback: "Sonra تعني ثم أو بعد ذلك."),
    'a2-u1-6': LessonContent(goal: "السؤال عن تجربة شخص وما فعله.", explanation: "يمكن السؤال عن الماضي باستخدام Ne yaptın؟ (ماذا فعلت؟)، Nereye gittin؟ (إلى أين ذهبت؟)، Kiminle gittin؟ (مع من ذهبت؟)، Nasıl geçti؟ (كيف مرّ/كان؟). أجب بجمل قصيرة في الماضي: Ailemle gittim (ذهبت مع عائلتي).", examples: [LessonExample("Ne yaptın?", "ماذا فعلت؟"), LessonExample("Nereye gittin?", "إلى أين ذهبت؟"), LessonExample("Kiminle gittin?", "مع من ذهبت؟"), LessonExample("Nasıl geçti?", "كيف كان؟")], question: "ما السؤال التركي «إلى أين ذهبت؟»؟", options: ["Nereye gittin?", "Nereye gidiyorsun?", "Nerede yaşıyorsun?", "Ne istiyorsun?"], answer: 0, feedback: "Nereye gittin؟ تعني إلى أين ذهبت؟."),
    'a2-u1-7': LessonContent(goal: "التحدث عن عطلة أو رحلة سابقة.", explanation: "استخدم الماضي لوصف الرحلة: Tatilde denize girdim (سبحت في البحر خلال العطلة)، Çok fotoğraf çektik (التقطنا صوراً كثيرة)، Güzel bir otelde kaldık (أقمنا في فندق جميل). يمكن إضافة الصفات مثل güzel جميل، eğlenceli ممتع، yorucu متعب لوصف التجربة.", examples: [LessonExample("Tatil", "عطلة"), LessonExample("fotoğraf çektik", "التقطنا صوراً"), LessonExample("Otelde kaldık.", "أقمنا في الفندق."), LessonExample("Çok eğlendim.", "استمتعت كثيراً.")], question: "ما معنى Çok fotoğraf çektik؟", options: ["التقطنا صوراً كثيرة", "اشترينا تذاكر", "عدنا إلى المنزل", "حجزنا غرفة"], answer: 0, feedback: "تعني التقطنا صوراً كثيرة."),
    'a2-u1-8': LessonContent(goal: "فهم حوار عن عطلة نهاية الأسبوع الماضية.", explanation: "A: Hafta sonu ne yaptın؟ (ماذا فعلت في عطلة نهاية الأسبوع؟) B: Cumartesi arkadaşlarımla buluştum (التقيت أصدقائي يوم السبت). A: Nereye gittiniz؟ (إلى أين ذهبتم؟) B: Bir kafeye gittik ve kahve içtik (ذهبنا إلى مقهى وشربنا القهوة). A: Güzel miydi؟ (هل كان جميلاً؟) B: Evet, çok güzeldi (نعم، كان جميلاً جداً).", examples: [LessonExample("Hafta sonu", "نهاية الأسبوع"), LessonExample("arkadaşlarımla buluştum", "التقيت أصدقائي"), LessonExample("Bir kafeye gittik.", "ذهبنا إلى مقهى."), LessonExample("Güzel miydi?", "هل كان جميلاً؟")], question: "ماذا فعل المتحدث يوم السبت؟", options: ["سافر بالطائرة", "التقى أصدقاءه", "ذهب إلى الطبيب", "درس طوال اليوم"], answer: 1, feedback: "Cumartesi arkadaşlarımla buluştum تعني التقيت أصدقائي يوم السبت."),
    'a2-u1-9': LessonContent(goal: "مراجعة الماضي المحدد وإجراء محادثة قصيرة.", explanation: "راجع إثبات الماضي ونفيه والسؤال عنه، وانتبه إلى لواحق الانسجام الصوتي. كوّن فقرة من أربع جمل عن يومك السابق مستخدماً dün وönce وsonra. تذكّر: gittim ذهبت، gitmedim لم أذهب، gittin mi؟ هل ذهبت؟.", examples: [LessonExample("Dün evde kaldım.", "بقيت في المنزل أمس."), LessonExample("Kitap okumadım.", "لم أقرأ كتاباً."), LessonExample("Arkadaşımı aradım.", "اتصلت بصديقي."), LessonExample("Sonra uyudum.", "ثم نمت.")], question: "اختر صيغة الماضي المنفية الصحيحة للفعل gitmek مع أنا.", options: ["gitmedim", "gittim", "gidiyorum", "gideceğim"], answer: 0, feedback: "gitmedim هي صيغة الماضي المنفية: لم أذهب."),
    'a2-u2-1': LessonContent(goal: "التعبير عن الخطط والأحداث المستقبلية.", explanation: "نستخدم المستقبل في التركية مع اللاحقة -acak أو -ecek بحسب انسجام الحركات. أمثلة: yarın geleceğim (سآتي غداً)، çalışacağım (سأعمل/أدرس)، dinleneceğiz (سنرتاح). تُضاف لاحقة الشخص بعد لاحقة المستقبل.", examples: [LessonExample("Yarın geleceğim.", "سآتي غداً."), LessonExample("Çalışacağım.", "سأعمل/سأدرس."), LessonExample("Hafta sonu dinleneceğiz.", "سنرتاح في نهاية الأسبوع."), LessonExample("Yarın yağmur yağacak.", "ستمطر غداً.")], question: "ما معنى Yarın geleceğim؟", options: ["أتيت أمس", "سآتي غداً", "أنا آتي الآن", "آتي كل يوم"], answer: 1, feedback: "Yarın geleceğim تعني سآتي غداً."),
    'a2-u2-2': LessonContent(goal: "تكوين المستقبل مع ضمائر الأشخاص.", explanation: "بعد -acak/-ecek نضيف نهايات الشخص: ben -ım/-im/-um/-üm، sen -sın/-sin/-sun/-sün، o بلا نهاية، biz -ız/-iz/-uz/-üz، siz -sınız/-siniz/-sunuz/-sünüz، onlar غالباً -lar/-ler. مثال: gelmek ← geleceğim، geleceksin، gelecek، geleceğiz.", examples: [LessonExample("Ben geleceğim.", "أنا سآتي."), LessonExample("Sen geleceksin.", "أنت ستأتي."), LessonExample("O gelecek.", "هو/هي سيأتي."), LessonExample("Biz geleceğiz.", "نحن سنأتي.")], question: "ما صيغة «نحن سنأتي»؟", options: ["geleceğim", "geleceksin", "gelecek", "geleceğiz"], answer: 3, feedback: "geleceğiz هي صيغة المستقبل مع نحن."),
    'a2-u2-3': LessonContent(goal: "ملاحظة التغيرات الصوتية في بعض أفعال المستقبل.", explanation: "عند اتصال اللاحقة ببعض الأفعال قد يحدث تغير في شكل الفعل. gitmek يصبح gidecek (سيذهب)، yemek يصبح yiyecek (سيأكل)، demek يصبح diyecek (سيقول). احفظ هذه الصيغ الشائعة وتدرّب عليها ضمن جمل.", examples: [LessonExample("gitmek → gidecek", "يذهب ← سيذهب"), LessonExample("yemek → yiyecek", "يأكل ← سيأكل"), LessonExample("demek → diyecek", "يقول ← سيقول"), LessonExample("O yarın gelecek.", "سيأتي غداً.")], question: "ما صيغة المستقبل من gitmek؟", options: ["giticek", "gidecek", "gitacak", "gitmek"], answer: 1, feedback: "gidecek هي صيغة المستقبل الصحيحة من gitmek."),
    'a2-u2-4': LessonContent(goal: "نفي المستقبل والتعبير عما لن يحدث.", explanation: "نكوّن النفي بإضافة -ma/-me قبل لاحقة المستقبل، ثم نهاية الشخص: gelmeyeceğim (لن آتي)، gitmeyecek (لن يذهب)، çalışmayacağız (لن نعمل). لاحظ أن حركة النفي تتوافق مع الفعل.", examples: [LessonExample("Gelmeyeceğim.", "لن آتي."), LessonExample("Bugün çalışmayacağım.", "لن أعمل اليوم."), LessonExample("O gelmeyecek.", "لن يأتي."), LessonExample("Gitmeyeceğiz.", "لن نذهب.")], question: "كيف تقول «لن آتي»؟", options: ["Geleceğim", "Gelmeyeceğim", "Geliyorum", "Geldim"], answer: 1, feedback: "Gelmeyeceğim تعني لن آتي."),
    'a2-u2-5': LessonContent(goal: "صياغة الأسئلة عن الخطط المستقبلية.", explanation: "تأتي أداة السؤال منفصلة بعد صيغة الفعل: Gelecek misin؟ (هل ستأتي؟)، Yarın çalışacak mısın؟ (هل ستعمل غداً؟)، Bizimle gelecekler mi؟ (هل سيأتون معنا؟). تتغير أداة السؤال بحسب الانسجام الصوتي.", examples: [LessonExample("Gelecek misin?", "هل ستأتي؟"), LessonExample("Yarın gidecek miyiz?", "هل سنذهب غداً؟"), LessonExample("Çalışacak mısın?", "هل ستعمل؟"), LessonExample("Bize katılacak mı?", "هل سينضم إلينا؟")], question: "ما معنى Gelecek misin؟", options: ["هل أتيت؟", "هل ستأتي؟", "أين تذهب؟", "هل تعمل الآن؟"], answer: 1, feedback: "Gelecek misin تعني هل ستأتي؟."),
    'a2-u2-6': LessonContent(goal: "استخدام كلمات الزمن مع المستقبل.", explanation: "من كلمات المستقبل: yarın غداً، gelecek hafta الأسبوع القادم، gelecek ay الشهر القادم، gelecek yıl السنة القادمة، birazdan بعد قليل، yakında قريباً. مثال: Gelecek hafta sınava gireceğim (سأقدم امتحاناً الأسبوع القادم).", examples: [LessonExample("yarın", "غداً"), LessonExample("gelecek hafta", "الأسبوع القادم"), LessonExample("gelecek ay", "الشهر القادم"), LessonExample("birazdan", "بعد قليل"), LessonExample("Yakında taşınacağız.", "سننتقل قريباً.")], question: "ما معنى gelecek hafta؟", options: ["الأسبوع الماضي", "الأسبوع القادم", "كل أسبوع", "هذا الأسبوع"], answer: 1, feedback: "gelecek hafta تعني الأسبوع القادم."),
    'a2-u2-7': LessonContent(goal: "التعبير عن النوايا والترتيبات المستقبلية.", explanation: "يمكن التعبير عن الخطة باستخدام فعل المستقبل مع وقت أو مكان محدد: Akşam ders çalışacağım (سأدرس مساءً)، Pazar günü ailemi ziyaret edeceğim (سأزور عائلتي يوم الأحد). ولذكر النية: Tatilde dinleneceğim (سأرتاح في العطلة).", examples: [LessonExample("Akşam ders çalışacağım.", "سأدرس مساءً."), LessonExample("Ailemi ziyaret edeceğim.", "سأزور عائلتي."), LessonExample("Pazar günü buluşacağız.", "سنلتقي يوم الأحد."), LessonExample("Tatilde dinleneceğim.", "سأرتاح في العطلة.")], question: "ما معنى Ailemi ziyaret edeceğim؟", options: ["زرت عائلتي", "سأزور عائلتي", "أزور عائلتي الآن", "لن أزور عائلتي"], answer: 1, feedback: "تعني سأزور عائلتي."),
    'a2-u2-8': LessonContent(goal: "فهم حوار حول خطط نهاية الأسبوع.", explanation: "A: Hafta sonu ne yapacaksın؟ (ماذا ستفعل في نهاية الأسبوع؟) B: Cumartesi ailemi ziyaret edeceğim (سأزور عائلتي السبت). A: Pazar günü bizimle gelecek misin؟ (هل ستأتي معنا يوم الأحد؟) B: Evet, geleceğim (نعم، سآتي). A: Saat kaçta buluşacağız؟ (في أي ساعة سنلتقي؟).", examples: [LessonExample("Ne yapacaksın?", "ماذا ستفعل؟"), LessonExample("ailemi ziyaret edeceğim", "سأزور عائلتي"), LessonExample("Bizimle gelecek misin?", "هل ستأتي معنا؟"), LessonExample("Saat kaçta buluşacağız?", "في أي ساعة سنلتقي؟")], question: "متى سيزور المتحدث عائلته؟", options: ["يوم الجمعة", "يوم السبت", "يوم الأحد", "الأسبوع القادم"], answer: 1, feedback: "Cumartesi تعني يوم السبت."),
    'a2-u2-9': LessonContent(goal: "مراجعة المستقبل وإعداد خطة شخصية.", explanation: "راجع الإثبات والنفي والسؤال في المستقبل، ونهايات الضمائر والتغيرات الشائعة مثل gidecek وyiyecek. اكتب خطة من أربع جمل للأسبوع القادم مستخدماً yarın وgelecek hafta وbirazdan. مثال: Yarın erken kalkacağım (سأستيقظ مبكراً غداً).", examples: [LessonExample("Yarın erken kalkacağım.", "سأستيقظ مبكراً غداً."), LessonExample("Ders çalışmayacağım.", "لن أدرس."), LessonExample("Arkadaşım gelecek mi?", "هل سيأتي صديقي؟"), LessonExample("Gelecek hafta seyahat edeceğiz.", "سنسافر الأسبوع القادم.")], question: "اختر صيغة المستقبل المنفية الصحيحة للفعل çalışmak مع أنا.", options: ["çalışacağım", "çalışmadım", "çalışmayacağım", "çalışıyorum"], answer: 2, feedback: "çalışmayacağım تعني لن أدرس/أعمل."),
    'a2-u3-1': LessonContent(goal: "استخدام الصفة لوصف الأشخاص والأماكن والأشياء.", explanation: "تأتي الصفة غالباً قبل الاسم في التركية: güzel şehir مدينة جميلة، büyük ev منزل كبير، yeni araba سيارة جديدة. ويمكن استخدامها خبراً مع olmak المحذوف: Ev büyük (المنزل كبير)، Hava güzel (الطقس جميل).", examples: [LessonExample("güzel şehir", "مدينة جميلة"), LessonExample("büyük ev", "منزل كبير"), LessonExample("yeni araba", "سيارة جديدة"), LessonExample("Hava güzel.", "الطقس جميل.")], question: "ما معنى büyük ev؟", options: ["منزل صغير", "منزل كبير", "منزل جديد", "منزل جميل"], answer: 1, feedback: "büyük تعني كبير وev تعني منزل."),
    'a2-u3-2': LessonContent(goal: "تكوين المقارنة باستخدام daha.", explanation: "نضع daha قبل الصفة للمقارنة بمعنى «أكثر»: daha büyük أكبر، daha güzel أجمل، daha hızlı أسرع. مثال: Bu araba daha hızlı (هذه السيارة أسرع). ويمكن ذكر الطرف الثاني باستخدام -den/-dan: Bu ev o evden daha büyük (هذا المنزل أكبر من ذلك المنزل).", examples: [LessonExample("daha büyük", "أكبر"), LessonExample("daha güzel", "أجمل"), LessonExample("daha hızlı", "أسرع"), LessonExample("Bu kitap daha ilginç.", "هذا الكتاب أكثر إثارة للاهتمام.")], question: "ما معنى daha hızlı؟", options: ["أبطأ", "أسرع", "أجمل", "أصغر"], answer: 1, feedback: "daha hızlı تعني أسرع."),
    'a2-u3-3': LessonContent(goal: "المقارنة بين شيئين باستخدام لاحقة الحالة.", explanation: "نستخدم اسم الطرف الأول ثم -den/-dan أو -ten/-tan بحسب الانسجام والتوافق الصوتي، ثم daha والصفة: Ali, Mehmet'ten daha uzun (علي أطول من محمد)، İstanbul, bu şehirden daha kalabalık (إسطنبول أكثر ازدحاماً من هذه المدينة).", examples: [LessonExample("benden", "مني"), LessonExample("senden", "منك"), LessonExample("Mehmet'ten daha uzun", "أطول من محمد"), LessonExample("Bu yol diğerinden daha kısa.", "هذا الطريق أقصر من الآخر.")], question: "في المقارنة، ماذا تعني Mehmet'ten؟", options: ["إلى محمد", "مع محمد", "من محمد", "في محمد"], answer: 2, feedback: "Mehmet'ten تعني من محمد في تركيب المقارنة."),
    'a2-u3-4': LessonContent(goal: "التعبير عن الأفضل باستخدام en.", explanation: "نضع en قبل الصفة للتعبير عن الدرجة العليا: en güzel الأجمل، en büyük الأكبر، en hızlı الأسرع. مثال: Bu, en güzel park (هذه أجمل حديقة). ويمكن إضافة في مجموعة: Sınıfın en uzun öğrencisi (أطول طالب في الصف).", examples: [LessonExample("en güzel", "الأجمل"), LessonExample("en büyük", "الأكبر"), LessonExample("en hızlı", "الأسرع"), LessonExample("En sevdiğim renk mavi.", "لوني المفضل هو الأزرق.")], question: "ما معنى en büyük؟", options: ["الأكبر", "أكبر قليلاً", "الأصغر", "الكبير جداً"], answer: 0, feedback: "en büyük تعني الأكبر."),
    'a2-u3-5': LessonContent(goal: "التعبير عن التساوي باستخدام kadar.", explanation: "نستخدم kadar للتعبير عن المساواة: benim kadar طويل مثلي، senin kadar hızlı سريع مثلك. مثال: Ali, Mehmet kadar uzun (علي بطول محمد)، Bu oda diğer oda kadar büyük değil (هذه الغرفة ليست بحجم الغرفة الأخرى).", examples: [LessonExample("benim kadar", "بقدري / مثلي"), LessonExample("senin kadar", "بقدرك / مثلك"), LessonExample("onun kadar hızlı", "سريع مثله"), LessonExample("Benim kadar çalışıyor.", "يعمل بقدري.")], question: "ما معنى senin kadar؟", options: ["أكثر منك", "أقل منك", "مثلك / بقدرك", "بدلاً منك"], answer: 2, feedback: "senin kadar تعني مثلك أو بقدرك."),
    'a2-u3-6': LessonContent(goal: "وصف الأشخاص بمقارنة الصفات.", explanation: "يمكن مقارنة الطول والعمر والسرعة والهدوء والود: daha uzun أطول، daha genç أصغر سناً، daha sakin أهدأ، daha arkadaş canlısı أكثر ودّاً. مثال: Kardeşim benden daha genç (أخي أصغر مني).", examples: [LessonExample("uzun", "طويل"), LessonExample("genç", "شاب / صغير السن"), LessonExample("sakin", "هادئ"), LessonExample("Kardeşim benden daha genç.", "أخي أصغر مني.")], question: "ما معنى daha sakin؟", options: ["أكثر هدوءاً", "أكثر سرعة", "أكثر طولاً", "أكثر عمراً"], answer: 0, feedback: "daha sakin تعني أكثر هدوءاً."),
    'a2-u3-7': LessonContent(goal: "المقارنة بين المدن والأماكن والمنتجات.", explanation: "تُستخدم المقارنة عند الاختيار: Bu otel diğer otelden daha ucuz (هذا الفندق أرخص من الفندق الآخر)، Ankara İstanbul'dan daha sakin olabilir (قد تكون أنقرة أهدأ من إسطنبول). انتبه إلى أن المقارنة تصف الصفة ولا تعني دائماً حكماً مطلقاً.", examples: [LessonExample("daha ucuz", "أرخص"), LessonExample("daha pahalı", "أغلى"), LessonExample("daha kalabalık", "أكثر ازدحاماً"), LessonExample("Bu telefon daha hafif.", "هذا الهاتف أخف.")], question: "ما معنى daha ucuz؟", options: ["أغلى", "أرخص", "أكبر", "أبطأ"], answer: 1, feedback: "daha ucuz تعني أرخص."),
    'a2-u3-8': LessonContent(goal: "فهم حوار للمفاضلة بين خيارين.", explanation: "A: Bu iki otelden hangisi daha iyi؟ (أي الفندقين أفضل؟) B: Mavi otel daha ucuz, ama merkezdeki otel daha yakın (فندق مافي أرخص، لكن الفندق الموجود في المركز أقرب). A: Hangisini seçelim؟ (أيهما نختار؟) B: Bence merkezdeki otel daha uygun (برأيي الفندق المركزي أنسب).", examples: [LessonExample("hangisi", "أيّهما"), LessonExample("daha iyi", "أفضل"), LessonExample("daha yakın", "أقرب"), LessonExample("daha uygun", "أنسب")], question: "ما معنى hangisi؟", options: ["أين؟", "متى؟", "أيّهما؟", "كم؟"], answer: 2, feedback: "hangisi تعني أيّهما."),
    'a2-u3-9': LessonContent(goal: "مراجعة المقارنة والتفضيل واختبار الوحدة.", explanation: "راجع الفرق بين daha للمقارنة وen للدرجة العليا وkadar للتساوي. كوّن ثلاث جمل: مقارنة بين شخصين، ومقارنة بين مكانين، وجملة تفضيل. مثال: Bu şehir en güzel şehir değil, ama daha sakin (هذه المدينة ليست الأجمل لكنها أهدأ).", examples: [LessonExample("daha büyük", "أكبر"), LessonExample("en büyük", "الأكبر"), LessonExample("benim kadar", "مثلي"), LessonExample("Bu yol daha kısa.", "هذا الطريق أقصر.")], question: "اختر التعبير الذي يعني «الأجمل».", options: ["daha güzel", "en güzel", "güzel kadar", "güzelden"], answer: 1, feedback: "en güzel تعني الأجمل، بينما daha güzel تعني أجمل من شيء آخر."),
    'a2-u4-1': LessonContent(goal: "فهم الظروف ودورها في الجملة.", explanation: "الظرف يضيف معلومة إلى الفعل: متى حدث؟ أين؟ كيف؟ أو كم مرة؟ في التركية تأتي كلمات كثيرة قبل الفعل، مثل bugün اليوم، burada هنا، yavaşça ببطء، sık sık كثيراً. مثال: Bugün evde çalışıyorum (أعمل في المنزل اليوم).", examples: [LessonExample("bugün", "اليوم"), LessonExample("burada", "هنا"), LessonExample("yavaşça", "ببطء"), LessonExample("Sık sık kitap okuyorum.", "أقرأ الكتب كثيراً.")], question: "أي كلمة تعني «اليوم»؟", options: ["yarın", "bugün", "dün", "şimdi"], answer: 1, feedback: "bugün تعني اليوم."),
    'a2-u4-2': LessonContent(goal: "التعبير عن التكرار والعادات.", explanation: "تصف كلمات التكرار عدد مرات حدوث الفعل. من الشائع: her gün كل يوم، her zaman دائماً، genellikle عادةً، bazen أحياناً، nadiren نادراً، hiçbir zaman أبداً. مثال: Genellikle otobüsle gidiyorum (أذهب عادةً بالحافلة).", examples: [LessonExample("her gün", "كل يوم"), LessonExample("genellikle", "عادةً"), LessonExample("bazen", "أحياناً"), LessonExample("nadiren", "نادراً")], question: "ما معنى genellikle؟", options: ["نادراً", "أحياناً", "عادةً", "أبداً"], answer: 2, feedback: "genellikle تعني عادةً أو غالباً."),
    'a2-u4-3': LessonContent(goal: "السؤال عن عدد مرات حدوث الفعل.", explanation: "نسأل عن التكرار باستخدام Ne sıklıkla؟ أي «كم مرة؟» ويمكن الإجابة بـ haftada iki kez مرتين في الأسبوع، ayda bir مرة في الشهر، her sabah كل صباح. مثال: Ne sıklıkla spor yapıyorsun? (كم مرة تمارس الرياضة؟).", examples: [LessonExample("Ne sıklıkla?", "كم مرة؟"), LessonExample("haftada iki kez", "مرتين في الأسبوع"), LessonExample("ayda bir", "مرة في الشهر"), LessonExample("her sabah", "كل صباح")], question: "كيف تقول «مرتين في الأسبوع»؟", options: ["haftada iki kez", "her gün", "ayda bir", "hafta sonu"], answer: 0, feedback: "haftada iki kez تعني مرتين في الأسبوع."),
    'a2-u4-4': LessonContent(goal: "التعبير عن طريقة أداء الفعل.", explanation: "تجيب ظروف الطريقة عن سؤال Nasıl؟ أي «كيف؟». أمثلة: yavaş ببطء، hızlı بسرعة، dikkatlice بعناية، sessizce بهدوء. ويمكن استخدام اللاحقة -ca/-ce في كلمات مثل yavaşça وsessizce. مثال: Lütfen yavaş konuş (من فضلك تحدث ببطء).", examples: [LessonExample("Nasıl?", "كيف؟"), LessonExample("dikkatlice", "بعناية"), LessonExample("sessizce", "بهدوء"), LessonExample("hızlı konuşmak", "التحدث بسرعة")], question: "ما معنى dikkatlice؟", options: ["بسرعة", "بعناية", "نادراً", "غداً"], answer: 1, feedback: "dikkatlice تعني بعناية."),
    'a2-u4-5': LessonContent(goal: "التعبير عن الزمن وترتيب الروتين.", explanation: "تساعد كلمات الزمن على تحديد وقت الفعل: sabah صباحاً، öğleden sonra بعد الظهر، akşam مساءً، gece ليلاً، önce قبل، sonra بعد. مثال: Önce kahvaltı yapıyorum, sonra işe gidiyorum (أتناول الفطور أولاً، ثم أذهب إلى العمل).", examples: [LessonExample("sabah", "صباحاً"), LessonExample("akşam", "مساءً"), LessonExample("önce", "أولاً / قبل"), LessonExample("sonra", "بعد ذلك")], question: "ما معنى sonra؟", options: ["قبل", "بعد ذلك", "أمس", "دائماً"], answer: 1, feedback: "sonra تعني بعد ذلك."),
    'a2-u4-6': LessonContent(goal: "التعبير عن المكان والاتجاه في الروتين.", explanation: "تحدد ظروف المكان أين يقع الفعل: burada هنا، orada هناك، içeride في الداخل، dışarıda في الخارج، evde في المنزل، işte في العمل. مثال: Hafta sonları genellikle dışarıda yemek yiyoruz (نتناول الطعام عادةً خارج المنزل في عطلة نهاية الأسبوع).", examples: [LessonExample("burada", "هنا"), LessonExample("orada", "هناك"), LessonExample("içeride", "في الداخل"), LessonExample("dışarıda", "في الخارج")], question: "أي كلمة تعني «في الخارج»؟", options: ["içeride", "burada", "dışarıda", "evde"], answer: 2, feedback: "dışarıda تعني في الخارج."),
    'a2-u4-7': LessonContent(goal: "وضع الظرف في الجملة وفهم المعنى.", explanation: "غالباً يوضع الظرف قبل الفعل أو في موضع يبرز المعلومة المقصودة: Ben her sabah kahve içerim (أشرب القهوة كل صباح)، Kardeşim hızlı koşuyor (أخي يركض بسرعة). انتبه إلى أن ترتيب الكلمات قد يتغير للتوكيد، لكن الفعل يأتي غالباً قرب نهاية الجملة.", examples: [LessonExample("her sabah", "كل صباح"), LessonExample("hızlı koşuyor", "يركض بسرعة"), LessonExample("çok güzel", "بشكل جميل جداً"), LessonExample("Bugün erken kalktım.", "استيقظت مبكراً اليوم.")], question: "في جملة Ben her sabah kahve içerim، ماذا تصف her sabah؟", options: ["مكان الشرب", "تكرار الشرب", "طريقة الشرب", "لون القهوة"], answer: 1, feedback: "her sabah تحدد تكرار/موعد شرب القهوة."),
    'a2-u4-8': LessonContent(goal: "إجراء محادثة عن الروتين والعادات.", explanation: "A: Ne sıklıkla yürüyüş yaparsın? (كم مرة تتمشى؟) B: Her akşam yürüyüş yaparım (أتمشى كل مساء). A: Nerede yürüyüş yaparsın? (أين تتمشى؟) B: Genellikle parkta, bazen sahilde (عادةً في الحديقة، وأحياناً على الشاطئ).", examples: [LessonExample("Ne sıklıkla?", "كم مرة؟"), LessonExample("her akşam", "كل مساء"), LessonExample("genellikle", "عادةً"), LessonExample("bazen", "أحياناً")], question: "كيف تقول «كل مساء»؟", options: ["her sabah", "her akşam", "her hafta", "her gece"], answer: 1, feedback: "her akşam تعني كل مساء."),
    'a2-u4-9': LessonContent(goal: "مراجعة الظروف والتكرار والروتين.", explanation: "راجع أنواع الظروف: التكرار مثل genellikle، والطريقة مثل dikkatlice، والزمن مثل bugün وsonra، والمكان مثل burada وdışarıda. اكتب وصفاً قصيراً ليومك مستخدماً ثلاثة ظروف مختلفة على الأقل.", examples: [LessonExample("genellikle", "عادةً"), LessonExample("dikkatlice", "بعناية"), LessonExample("sonra", "بعد ذلك"), LessonExample("burada", "هنا")], question: "اختر الجملة التي تعني «أقرأ عادةً في المساء».", options: ["Akşam genellikle okurum.", "Akşam hiç okumam.", "Sabah hızlı koşarım.", "Burada kitap var."], answer: 0, feedback: "Akşam genellikle okurum تعني أقرأ عادةً في المساء."),
    'a2-u5-1': LessonContent(goal: "فهم التعبير عن القدرة والإمكانية.", explanation: "نستخدم اللاحقة -(y)Abil مع الفعل للتعبير عن القدرة أو الإمكانية. تتغير الحركة وفق الانسجام الصوتي: yapabilmek أن يستطيع أن يفعل، gelebilmek أن يستطيع أن يأتي، okuyabilmek أن يستطيع أن يقرأ. مثال: Türkçe konuşabilirim (أستطيع التحدث بالتركية).", examples: [LessonExample("yapabilmek", "القدرة على الفعل"), LessonExample("gelebilmek", "القدرة على المجيء"), LessonExample("okuyabilmek", "القدرة على القراءة"), LessonExample("Yüzebilirim.", "أستطيع السباحة.")], question: "ما معنى Türkçe konuşabilirim؟", options: ["لا أتحدث التركية", "أستطيع التحدث بالتركية", "أريد تعلم التركية", "أتحدث التركية أمس"], answer: 1, feedback: "konuşabilirim تعني أستطيع التحدث."),
    'a2-u5-2': LessonContent(goal: "تكوين صيغة القدرة مع الضمائر.", explanation: "نضيف -(y)Abil إلى جذر الفعل ثم نصرّفه بحسب الزمن والضمير: Ben yapabilirim أستطيع أن أفعل، Sen yapabilirsin تستطيع، O yapabilir يستطيع/تستطيع، Biz yapabiliriz نستطيع. مثال: Siz gelebilirsiniz (يمكنكم المجيء).", examples: [LessonExample("yapabilirim", "أستطيع أن أفعل"), LessonExample("yapabilirsin", "تستطيع أن تفعل"), LessonExample("yapabilir", "يستطيع أن يفعل"), LessonExample("yapabiliriz", "نستطيع أن نفعل")], question: "ما معنى yapabiliriz؟", options: ["أستطيع أن أفعل", "تستطيع أن تفعل", "نستطيع أن نفعل", "لا نستطيع أن نفعل"], answer: 2, feedback: "yapabiliriz تعني نستطيع أن نفعل."),
    'a2-u5-3': LessonContent(goal: "التعبير عن عدم القدرة.", explanation: "للنفي نستخدم غالباً -ama/-eme قبل علامة الزمن والضمير: yapamam لا أستطيع أن أفعل، gelemem لا أستطيع المجيء، konuşamam لا أستطيع التحدث. مثال: Bugün gelemem (لا أستطيع المجيء اليوم).", examples: [LessonExample("yapamam", "لا أستطيع أن أفعل"), LessonExample("gelemem", "لا أستطيع المجيء"), LessonExample("konuşamam", "لا أستطيع التحدث"), LessonExample("Bugün çalışamam.", "لا أستطيع العمل اليوم.")], question: "ما معنى gelemem؟", options: ["أستطيع المجيء", "لا أستطيع المجيء", "أريد المجيء", "جئت أمس"], answer: 1, feedback: "gelemem تعني لا أستطيع المجيء."),
    'a2-u5-4': LessonContent(goal: "السؤال عن القدرة والإمكانية.", explanation: "نحوّل الجملة إلى سؤال بإضافة أداة السؤال mı/mi/mu/mü بعد الفعل المصرف: Gelebilir misin? هل تستطيع المجيء؟ Yardım edebilir misiniz? هل يمكنكم المساعدة؟ تفصل أداة السؤال وتُكتب مستقلة، ثم تأخذ لاحقة الشخص.", examples: [LessonExample("Gelebilir misin?", "هل تستطيع المجيء؟"), LessonExample("Yapabilir miyim?", "هل أستطيع أن أفعل؟"), LessonExample("Anlayabilir misiniz?", "هل يمكنكم الفهم؟"), LessonExample("Açabilir misin?", "هل تستطيع الفتح؟")], question: "كيف تسأل «هل تستطيع المجيء؟»؟", options: ["Gelemem.", "Gelebilir misin?", "Geldim.", "Geliyorum."], answer: 1, feedback: "Gelebilir misin? سؤال عن القدرة على المجيء."),
    'a2-u5-5': LessonContent(goal: "تقديم طلب مهذب باستخدام صيغة القدرة.", explanation: "تُستخدم صيغة القدرة مع سؤال الشخص لتقديم طلب لطيف: Kapıyı açabilir misiniz? هل يمكنكم فتح الباب؟ Bana yardım edebilir misin? هل تستطيع مساعدتي؟ إضافة lütfen بمعنى «من فضلك» تجعل الطلب أكثر تهذيباً: Lütfen tekrar edebilir misiniz? (هل يمكنكم التكرار من فضلكم؟).", examples: [LessonExample("yardım etmek", "يساعد"), LessonExample("tekrar etmek", "يكرر"), LessonExample("açabilir misiniz?", "هل يمكنكم الفتح؟"), LessonExample("Lütfen bekleyebilir misiniz?", "هل يمكنكم الانتظار من فضلكم؟")], question: "أي جملة طلب مهذب؟", options: ["Kapıyı aç!", "Kapıyı açabilir misiniz?", "Kapıyı açtım.", "Kapı açık."], answer: 1, feedback: "استخدام صيغة السؤال مع misiniz يجعل الطلب ألطف."),
    'a2-u5-6': LessonContent(goal: "طلب الإذن والتعبير عن السماح.", explanation: "لطلب الإذن نستخدم: ...abilir miyim؟ مثل İçeri girebilir miyim? هل يمكنني الدخول؟ Fotoğraf çekebilir miyim? هل يمكنني التقاط صورة؟ وللسماح يمكن الإجابة: Tabii, girebilirsiniz (بالطبع، يمكنكم الدخول) أو Olur (حسناً).", examples: [LessonExample("İçeri girebilir miyim?", "هل يمكنني الدخول؟"), LessonExample("Fotoğraf çekebilir miyim?", "هل يمكنني التقاط صورة؟"), LessonExample("Tabii.", "بالطبع."), LessonExample("Olur.", "حسناً / ممكن.")], question: "كيف تقول «هل يمكنني التقاط صورة؟»؟", options: ["Fotoğraf çekebilir miyim?", "Fotoğraf çekemem.", "Fotoğraf çektim.", "Fotoğraf çekiyorum."], answer: 0, feedback: "Fotoğraf çekebilir miyim? طلب إذن لالتقاط صورة."),
    'a2-u5-7': LessonContent(goal: "اختيار درجة مناسبة من التهذيب.", explanation: "تختلف الصياغة بحسب الموقف: Yardım et. أمر مباشر غير رسمي؛ Yardım eder misin? طلب ألطف لشخص تعرفه؛ Yardım edebilir misiniz? صيغة أكثر تهذيباً أو رسمية. يمكن إضافة lütfen، ومن الأفضل استخدام نبرة محترمة.", examples: [LessonExample("Yardım et.", "ساعد."), LessonExample("Yardım eder misin?", "هل تساعدني؟"), LessonExample("Yardım edebilir misiniz?", "هل يمكنكم مساعدتي؟"), LessonExample("lütfen", "من فضلك")], question: "أي صيغة أنسب لطلب مهذب ورسمي؟", options: ["Yardım et!", "Yardım edebilir misiniz?", "Yardım!", "Yardım ettim."], answer: 1, feedback: "الصيغة الثالثة أكثر تهذيباً ورسمية."),
    'a2-u5-8': LessonContent(goal: "إجراء حوار لطلب المساعدة والخدمة.", explanation: "A: Bu formu doldurabilir misiniz? (هل يمكنكم ملء هذه الاستمارة؟) B: Tabii, yardımcı olabilirim (بالطبع، أستطيع المساعدة). A: Teşekkür ederim. B: Rica ederim. استخدم هذه العبارات في المتجر أو المدرسة أو مكان العمل.", examples: [LessonExample("doldurmak", "يملأ"), LessonExample("yardımcı olmak", "يقدم المساعدة"), LessonExample("Teşekkür ederim.", "شكراً لك."), LessonExample("Rica ederim.", "على الرحب والسعة.")], question: "ما معنى yardımcı olabilirim؟", options: ["لا أستطيع المساعدة", "أستطيع المساعدة", "أحتاج إلى استمارة", "شكراً لك"], answer: 1, feedback: "yardımcı olabilirim تعني أستطيع المساعدة."),
    'a2-u5-9': LessonContent(goal: "مراجعة القدرة والطلب والإذن.", explanation: "تذكّر: -(y)Abil للقدرة والإمكانية، و-ama/-eme للنفي مثل yapamam، والسؤال يتكوّن بأداة mı/mi مستقلة مثل Yapabilir miyim? لطلب الإذن. أما الطلب المهذب فيمكن أن يأتي بصيغة Yardım edebilir misiniz? اكتب ثلاثة أمثلة من حياتك اليومية.", examples: [LessonExample("yapabilirim", "أستطيع أن أفعل"), LessonExample("gelemem", "لا أستطيع المجيء"), LessonExample("Yapabilir miyim?", "هل يمكنني أن أفعل؟"), LessonExample("Lütfen yardım eder misiniz?", "هل تساعدونني من فضلكم؟")], question: "اختر السؤال الصحيح لطلب الإذن: «هل يمكنني الدخول؟»", options: ["İçeri giremem.", "İçeri girdim.", "İçeri girebilir miyim?", "İçeri giriyorum."], answer: 2, feedback: "Içeri girebilir miyim? هي الصيغة الصحيحة لطلب الإذن بالدخول."),
  };
